(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-111":{scenario:{company:"Ngọc Trúc Office Solutions",supervisor:{name:"Lê Thị Thu Hà",role:{vi:"Kế toán trưởng",en:"Chief Accountant"}},ref_code:"JV-2512",title:{vi:"Đúng kỳ, đúng tài khoản, đúng bản chất.",en:"Right period, right account, right substance."},brief:{vi:"Ngày 01/08/2025 công ty trả trước 432 triệu đồng (chưa gồm thuế GTGT) tiền thuê văn phòng 18 tháng, từ 01/08/2025 đến 31/01/2027. Bản nháp bút toán JV-2512 ghi toàn bộ vào chi phí quản lý doanh nghiệp năm 2025. Năm tài chính trùng năm dương lịch, công ty áp dụng Thông tư 200/2014/TT-BTC. Sửa tài khoản ghi Nợ khi trả tiền và chi phí thuê thuộc năm 2025, rồi lập báo cáo có căn cứ.",en:"On 1 Aug 2025 the company prepaid VND 432 million (excluding VAT) of office rent for 18 months, from 1 Aug 2025 to 31 Jan 2027. Draft journal JV-2512 books the full amount as 2025 administrative expense. The fiscal year is the calendar year and the company applies Circular 200/2014/TT-BTC. Correct the debit account at payment and the 2025 rent expense, then write an evidence-based report."},reference_title:{vi:"Hợp đồng thuê & lịch phân bổ đã duyệt · JV-2512",en:"Lease contract & approved allocation schedule · JV-2512"},fields:[{id:"INIT_ACCT",label:{vi:"Tài khoản ghi Nợ khi trả trước",en:"Debit account at prepayment"},initial:"642",expected:"242",choices:["642","242","335"],reference:"Hợp đồng thuê & chính sách kế toán",hint:{vi:"Khoản chi mang lại lợi ích cho nhiều kỳ chưa phải chi phí của kỳ trả tiền; TK 335 dành cho chi phí đã phát sinh nhưng chưa trả.",en:"A payment benefiting several periods is not yet an expense of the payment period; account 335 is for costs incurred but unpaid."}},{id:"RENT_2025",label:{vi:"Chi phí thuê ghi nhận năm 2025 (VND)",en:"2025 rent expense (VND)"},initial:"432000000",expected:"120000000",reference:"Lịch phân bổ chi phí trả trước",ref_value:{vi:"Tổng 432.000.000 đồng; 18 tháng từ 01/08/2025; ngày khóa sổ 31/12/2025",en:"Total VND 432,000,000; 18 months from 1 Aug 2025; closing date 31 Dec 2025"},hint:{vi:"Chi phí của mỗi kỳ tương ứng với số tháng văn phòng thực sự được sử dụng trong kỳ đó.",en:"Each period's expense matches the number of months the office was actually used in that period."}}],sop32:{vi:"Chi phí trả trước phân bổ đều theo tháng hưởng lợi: chi phí tháng = tổng tiền trả trước / số tháng thuê; chi phí năm = chi phí tháng x số tháng đã sử dụng trong năm (Nợ 642 / Có 242).",en:"Prepaid costs are allocated evenly over the benefit months: monthly cost = total prepayment / lease months; annual cost = monthly cost x months used in the year (Dr 642 / Cr 242)."},context:{label:"SỔ CÁI NHÁP / JV-2512",metrics:[{label:{vi:"Tiền thuê trả trước",en:"Prepaid rent"},value:"432,000,000 VND"},{label:{vi:"Thời hạn thuê",en:"Lease term"},value:"01/08/2025 - 31/01/2027"},{label:{vi:"Ngày khóa sổ",en:"Closing date"},value:"31/12/2025"}]},crisis:{vi:"Giám đốc nhắn: “Cứ ghi hết 432 triệu vào chi phí năm nay cho lợi nhuận thấp xuống, đỡ thuế TNDN. Đằng nào cũng là tiền thật đã chi, ai kiểm tra đâu mà lo.”",en:"The director messages you: “Just expense the whole 432 million this year so profit drops and we pay less corporate income tax. It is real money already spent, nobody will check.”"},options:{safe:{vi:"Phân bổ theo thời gian hưởng lợi qua TK 242, giải thích nguyên tắc dồn tích và phù hợp, báo kế toán trưởng bằng văn bản; mọi phương án tối ưu thuế phải hợp pháp và có tư vấn.",en:"Allocate over the benefit period through account 242, explain the accrual and matching principles and inform the chief accountant in writing; any tax planning must be lawful and advised."},shortcut:{vi:"Ghi hết vào chi phí năm 2025 theo ý giám đốc, nếu bị thanh tra thuế thì điều chỉnh sau.",en:"Expense everything in 2025 as the director wants and adjust later if the tax authority audits."},wait:{vi:"Giữ nguyên bút toán nháp và chờ kiểm toán cuối năm tự phát hiện, tự quyết định.",en:"Leave the draft entry as it is and wait for the year-end auditors to find and decide."}},questions:{vi:["Vì sao khoản tiền thuê phải ghi Nợ TK 242 thay vì TK 642? Trình bày cách bạn tính chi phí thuê năm 2025 từ hợp đồng.","Nếu ghi toàn bộ vào chi phí năm 2025, báo cáo tài chính và quyết toán thuế TNDN bị ảnh hưởng thế nào và rủi ro gì?"],en:["Why must the rent be debited to account 242 instead of 642? Show how you calculated the 2025 rent expense from the contract.","If the whole amount is expensed in 2025, how are the financial statements and the corporate income tax finalization affected, and what are the risks?"]},hints:{vi:["Đặt bút toán nháp cạnh hợp đồng thuê và đánh dấu thời hạn hưởng lợi của khoản chi.","Đếm số tháng sử dụng văn phòng trong năm 2025 trước khi áp công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không ghi nhận chi phí sai kỳ để điều chỉnh lợi nhuận hay số thuế phải nộp."],en:["Place the draft entry next to the lease and mark the benefit period of the payment.","Count the months of office use in 2025 before applying the formula in SOP 3.2.","Re-read SOP 4.2: never book expenses in the wrong period to manage profit or tax payable."]}},learning:{summary:{vi:"Kế toán tổng hợp kiểm tra và hạch toán toàn bộ nghiệp vụ, thực hiện các bút toán cuối kỳ như phân bổ, trích trước, khấu hao, đánh giá tỷ giá và kết chuyển, đối chiếu sổ chi tiết với sổ cái rồi lập báo cáo tài chính. Đây là người giữ bức tranh tài chính đúng kỳ, đúng bản chất, làm đầu mối cho quyết toán thuế và kiểm toán. Nghề đòi hỏi nắm vững Luật Kế toán, chuẩn mực kế toán Việt Nam và chế độ kế toán doanh nghiệp.",en:"A general accountant reviews and records all transactions, runs period-end entries such as allocations, accruals, depreciation, FX revaluation and closing transfers, reconciles subledgers to the general ledger and prepares the financial statements. The role keeps the financial picture in the right period and true to substance and is the focal point for tax finalization and audits. It requires solid command of the Accounting Law, Vietnamese Accounting Standards and the enterprise accounting regime."},responsibilities:{vi:["Kiểm tra chứng từ, hạch toán và rà soát bút toán của các phần hành trước khi khóa sổ.","Thực hiện bút toán cuối kỳ: phân bổ chi phí trả trước, trích trước, khấu hao, đánh giá lại ngoại tệ.","Đối chiếu sổ chi tiết công nợ, kho, tài sản, ngân hàng với sổ cái và xử lý chênh lệch.","Lập bảng cân đối số phát sinh và báo cáo tài chính năm, giữa niên độ.","Hỗ trợ quyết toán thuế, cung cấp hồ sơ cho kiểm toán độc lập và thanh tra."],en:["Check documents, post entries and review sub-ledger postings before closing.","Run period-end entries: prepaid allocation, accruals, depreciation and FX revaluation.","Reconcile receivable, inventory, asset and bank subledgers with the ledger and clear differences.","Prepare the trial balance and annual and interim financial statements.","Support tax finalization and provide files to external auditors and inspectors."]},competencies:[{name:{vi:"Nguyên tắc kế toán",en:"Accounting principles"},desc:{vi:"Vận dụng cơ sở dồn tích, phù hợp, thận trọng và nhất quán để ghi nhận đúng kỳ, đúng bản chất.",en:"Apply accrual, matching, prudence and consistency to record items in the right period and substance."}},{name:{vi:"Khóa sổ cuối kỳ",en:"Period-end close"},desc:{vi:"Lập và theo dõi danh mục công việc khóa sổ, bút toán điều chỉnh và lịch phân bổ.",en:"Build and track the closing checklist, adjusting entries and allocation schedules."}},{name:{vi:"Đối chiếu số liệu",en:"Reconciliation"},desc:{vi:"Phát hiện và giải thích chênh lệch giữa sổ chi tiết, sổ cái, sao kê và biên bản đối chiếu.",en:"Find and explain gaps between subledgers, ledger, statements and confirmations."}},{name:{vi:"Lập báo cáo tài chính",en:"Financial reporting"},desc:{vi:"Trình bày bảng cân đối, kết quả kinh doanh, lưu chuyển tiền tệ và thuyết minh đúng chuẩn mực.",en:"Present the balance sheet, income statement, cash flow and notes in line with standards."}},{name:{vi:"Chính trực nghề nghiệp",en:"Professional integrity"},desc:{vi:"Không ghi sai kỳ để làm đẹp hay giảm lợi nhuận; báo cáo bằng văn bản khi bị yêu cầu làm sai.",en:"Never shift periods to inflate or cut profit; escalate in writing when asked to misstate."}}],knowledge:{vi:["Luật Kế toán số 88/2015/QH13 và Nghị định 174/2016/NĐ-CP quy định chi tiết.","Thông tư 200/2014/TT-BTC về chế độ kế toán doanh nghiệp và Thông tư 133/2016/TT-BTC cho doanh nghiệp nhỏ và vừa (cùng các văn bản sửa đổi, thay thế).","VAS 01 Chuẩn mực chung: cơ sở dồn tích, phù hợp, thận trọng, trọng yếu.","VAS 21 Trình bày báo cáo tài chính và VAS 24 Báo cáo lưu chuyển tiền tệ.","Nghị định 123/2020/NĐ-CP về hóa đơn, chứng từ và yêu cầu chứng từ hợp lệ."],en:["Accounting Law No. 88/2015/QH13 and Decree 174/2016/ND-CP detailing it.","Circular 200/2014/TT-BTC on the enterprise accounting regime and Circular 133/2016/TT-BTC for SMEs (with amending or replacing documents).","VAS 01 Framework: accrual basis, matching, prudence and materiality.","VAS 21 Presentation of financial statements and VAS 24 Cash flow statements.","Decree 123/2020/ND-CP on invoices and documents and what makes a document valid."]},tools:["Phần mềm kế toán doanh nghiệp (ERP)","Microsoft Excel","Hệ thống hóa đơn điện tử","Ngân hàng điện tử (sao kê)","Phần mềm hỗ trợ kê khai thuế"],kpis:{vi:["Số ngày khóa sổ tháng sau ngày cuối kỳ.","Số bút toán điều chỉnh do kiểm toán đề xuất (mục tiêu giảm dần).","Tỷ lệ tài khoản được đối chiếu và ký xác nhận hằng tháng.","Số lần nộp báo cáo, tờ khai trễ hạn (mục tiêu bằng 0)."],en:["Days to close the month after period end.","Audit-proposed adjusting entries (target decreasing).","Share of accounts reconciled and signed off monthly.","Late report or return filings (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra sao kê ngân hàng, đối chiếu thu chi phát sinh với sổ quỹ và sổ tiền gửi.",en:"Check bank statements and match receipts and payments with the cash and bank books."},{time:"09:30",vi:"Rà soát bút toán của kế toán công nợ, kho và tài sản; trả lại chứng từ thiếu căn cứ.",en:"Review postings from payables, inventory and assets; return poorly supported documents."},{time:"13:30",vi:"Cập nhật lịch phân bổ chi phí trả trước, trích trước chi phí lãi vay và điện nước.",en:"Update the prepaid allocation schedule and accrue interest and utility costs."},{time:"15:30",vi:"Đối chiếu sổ chi tiết với sổ cái, giải thích chênh lệch với kế toán trưởng.",en:"Reconcile subledgers to the ledger and explain differences to the chief accountant."},{time:"17:00",vi:"Lập bảng cân đối số phát sinh nháp và cập nhật danh mục công việc khóa sổ.",en:"Prepare a draft trial balance and update the closing checklist."}],mistakes:{vi:["Ghi thẳng khoản trả trước nhiều kỳ vào chi phí kỳ trả tiền, sai nguyên tắc phù hợp.","Quên trích trước chi phí đã phát sinh nhưng chưa có hóa đơn, làm lợi nhuận kỳ này cao giả tạo.","Khóa sổ khi sổ chi tiết chưa khớp sổ cái, để chênh lệch dồn sang kỳ sau."],en:["Expensing a multi-period prepayment in the payment period, breaching matching.","Failing to accrue costs incurred without an invoice yet, overstating current profit.","Closing while subledgers do not match the ledger, carrying differences forward."]},career:[{vi:"Kế toán viên phần hành",en:"Accounting clerk"},{vi:"Kế toán tổng hợp",en:"General accountant"},{vi:"Phó phòng / Kế toán trưởng",en:"Deputy / Chief accountant"},{vi:"Giám đốc tài chính (CFO)",en:"Chief Financial Officer (CFO)"}],glossary:[{term:"Chi phí trả trước",vi:"Khoản đã chi nhưng liên quan nhiều kỳ, được ghi vào TK 242 và phân bổ dần vào chi phí.",en:"Prepaid expense: paid amounts covering several periods, held in account 242 and allocated over time."},{term:"Chi phí phải trả",vi:"Chi phí đã phát sinh, đã nhận hàng hoặc dịch vụ nhưng chưa có hóa đơn hoặc chưa trả, ghi vào TK 335.",en:"Accrued expense: costs incurred for goods or services received but not yet invoiced or paid, in account 335."},{term:"Cơ sở dồn tích",vi:"Nghiệp vụ được ghi nhận khi phát sinh, không căn cứ vào thời điểm thu hoặc chi tiền.",en:"Accrual basis: transactions are recognized when they occur, not when cash moves."},{term:"Khóa sổ",vi:"Hoàn tất ghi chép, điều chỉnh, kết chuyển và chốt số liệu của một kỳ kế toán.",en:"Closing: completing entries, adjustments and transfers and locking a period's figures."},{term:"Bảng cân đối số phát sinh",vi:"Bảng tổng hợp số dư đầu kỳ, phát sinh và số dư cuối kỳ của mọi tài khoản để kiểm tra cân đối.",en:"Trial balance: a summary of opening balances, movements and closing balances of all accounts."}],quiz:[{q:{vi:"Công ty trả trước 240 triệu đồng tiền bảo hiểm tài sản 24 tháng từ 01/10. Chi phí ghi nhận đến 31/12 cùng năm là bao nhiêu?",en:"A company prepays VND 240 million of property insurance for 24 months from 1 October. What expense is recognized by 31 December of that year?"},options:{vi:["240 triệu đồng","120 triệu đồng","10 triệu đồng","30 triệu đồng"],en:["VND 240 million","VND 120 million","VND 10 million","VND 30 million"]},answer:3,explain:{vi:"Mỗi tháng 240 / 24 = 10 triệu đồng; từ tháng 10 đến tháng 12 là 3 tháng nên chi phí là 30 triệu đồng.",en:"Monthly cost is 240 / 24 = VND 10 million; October to December is 3 months, so VND 30 million."}},{q:{vi:"Điện tháng 12 đã sử dụng nhưng đầu tháng 1 mới có hóa đơn. Khi khóa sổ năm, kế toán ghi nhận thế nào?",en:"December electricity was used but the invoice arrives in early January. How is it handled at year-end close?"},options:{vi:["Không ghi gì, chờ hóa đơn","Trích trước vào chi phí tháng 12, ghi Có TK 335","Ghi vào chi phí trả trước TK 242","Ghi vào chi phí năm sau"],en:["Record nothing until the invoice","Accrue it in December, credit account 335","Record it as a prepaid expense in account 242","Expense it next year"]},answer:1,explain:{vi:"Theo cơ sở dồn tích, chi phí đã phát sinh phải ghi nhận đúng kỳ thông qua chi phí phải trả.",en:"Under the accrual basis, an incurred cost is recognized in its period through an accrued liability."}},{q:{vi:"Nguyên tắc nào yêu cầu ghi nhận chi phí tương ứng với doanh thu và lợi ích của cùng kỳ?",en:"Which principle requires expenses to be recognized with the revenue and benefits of the same period?"},options:{vi:["Giá gốc","Hoạt động liên tục","Phù hợp","Trọng yếu"],en:["Historical cost","Going concern","Matching","Materiality"]},answer:2,explain:{vi:"Nguyên tắc phù hợp trong VAS 01 gắn chi phí với doanh thu và kỳ mà chúng tạo ra lợi ích.",en:"The matching principle in VAS 01 links costs to the revenue and periods they benefit."}},{q:{vi:"Giám đốc yêu cầu dồn chi phí năm sau vào năm nay để giảm thuế TNDN. Bạn làm gì?",en:"The director asks you to pull next year's costs into this year to cut corporate income tax. What do you do?"},options:{vi:["Từ chối, giải thích nguyên tắc dồn tích và báo kế toán trưởng bằng văn bản","Làm theo vì giám đốc chịu trách nhiệm","Ghi một nửa cho cân bằng","Chờ kiểm toán phát hiện rồi sửa"],en:["Refuse, explain the accrual principle and inform the chief accountant in writing","Comply because the director is responsible","Book half as a compromise","Wait for the auditors to find it"]},answer:0,explain:{vi:"Ghi sai kỳ để giảm thuế là sai phạm kế toán và thuế; kế toán phải từ chối và lưu bằng chứng.",en:"Shifting periods to cut tax is an accounting and tax violation; refuse and keep evidence."}}],tools_en:["Enterprise accounting software (ERP)","Microsoft Excel","E-invoicing system","Online banking (bank statements)","Tax filing support software"]}},"KK-112":{scenario:{company:"Bamboo Crest Furniture",supervisor:{name:"Nguyễn Văn Khải",role:{vi:"Trưởng nhóm Thuế",en:"Tax Lead"}},ref_code:"VAT-2609",title:{vi:"Đúng thuế suất. Đúng khấu trừ. Đúng hạn.",en:"Right rate. Right credit. Right on time."},brief:{vi:"Bạn soát tờ khai thuế GTGT mẫu 01/GTGT tháng 09/2026 (VAT-2609), kê khai theo phương pháp khấu trừ. Doanh thu nội địa chưa thuế 2,4 tỷ đồng (thuế suất mô phỏng 10%); doanh thu xuất khẩu 1,5 tỷ đồng có hợp đồng, tờ khai hải quan và thanh toán qua ngân hàng. Thuế GTGT đầu vào trên hóa đơn hợp lệ 186 triệu đồng, trong đó 6,5 triệu đồng thuộc một hóa đơn 71,5 triệu đồng trả bằng tiền mặt. Không có thuế kỳ trước chuyển sang. Sửa thuế suất doanh thu xuất khẩu và số thuế còn phải nộp.",en:"You are reviewing VAT return form 01/GTGT for September 2026 (VAT-2609) under the credit method. Domestic sales excluding VAT are VND 2.4 billion (training rate 10%); export sales of VND 1.5 billion have a contract, customs declaration and bank payment. Input VAT on valid invoices is VND 186 million, of which VND 6.5 million belongs to a VND 71.5 million invoice paid in cash. There is no credit carried forward. Correct the export sales rate and the VAT payable."},reference_title:{vi:"Bảng kê hóa đơn & hồ sơ xuất khẩu đã duyệt · VAT-2609",en:"Approved invoice listing & export file · VAT-2609"},fields:[{id:"EXP_RATE",label:{vi:"Thuế suất GTGT của doanh thu xuất khẩu",en:"VAT rate on export sales"},initial:"KCT",expected:"0%",choices:["KCT","0%","10%"],reference:"Hồ sơ xuất khẩu & chính sách thuế",hint:{vi:"Hàng xuất khẩu đủ hợp đồng, tờ khai hải quan và thanh toán qua ngân hàng vẫn là đối tượng chịu thuế; điểm khác nằm ở quyền khấu trừ đầu vào.",en:"Exports with a contract, customs declaration and bank payment remain taxable; the difference lies in the right to credit input VAT."}},{id:"VAT_PAYABLE",label:{vi:"Thuế GTGT còn phải nộp (VND)",en:"VAT payable (VND)"},initial:"54000000",expected:"60500000",reference:"Bảng kê hóa đơn mua vào, bán ra",ref_value:{vi:"Doanh thu nội địa 2.400.000.000 đồng x 10%; đầu vào 186.000.000 đồng, gồm 6.500.000 đồng trả tiền mặt",en:"Domestic sales VND 2,400,000,000 x 10%; input VAT VND 186,000,000, including VND 6,500,000 paid in cash"},hint:{vi:"Không phải mọi số thuế ghi trên hóa đơn đầu vào đều được khấu trừ; kiểm tra điều kiện thanh toán của từng hóa đơn.",en:"Not every input VAT amount on an invoice is creditable; check the payment condition of each invoice."}}],sop32:{vi:"Thuế còn phải nộp = thuế GTGT đầu ra - thuế GTGT đầu vào đủ điều kiện khấu trừ - thuế kỳ trước chuyển sang; hóa đơn mua vào từ 5 triệu đồng trở lên (ngưỡng mô phỏng) trả bằng tiền mặt thì không được khấu trừ.",en:"VAT payable = output VAT - creditable input VAT - credit carried forward; purchase invoices of VND 5 million or more (training threshold) paid in cash are not creditable."},context:{label:"TỜ KHAI NHÁP 01/GTGT / VAT-2609",metrics:[{label:{vi:"Doanh thu nội địa",en:"Domestic sales"},value:"2,400,000,000 VND"},{label:{vi:"Doanh thu xuất khẩu",en:"Export sales"},value:"1,500,000,000 VND"},{label:{vi:"Thuế đầu vào trên hóa đơn",en:"Input VAT on invoices"},value:"186,000,000 VND"}]},crisis:{vi:"Một công ty dịch vụ gọi chào bán hóa đơn đầu vào trị giá 300 triệu đồng, thuế GTGT 30 triệu đồng, “không cần giao hàng, chuyển khoản xong bên em trả lại tiền mặt”. Giám đốc bảo bạn nhận để giảm số thuế tháng này.",en:"A service company offers to sell input invoices worth VND 300 million with VND 30 million VAT, “no delivery needed, you transfer and we return the cash”. The director tells you to take them to cut this month's tax."},options:{safe:{vi:"Từ chối mua hóa đơn không có giao dịch thật, kê khai đúng số thuế phải nộp, báo kế toán trưởng và giám đốc bằng văn bản về rủi ro pháp lý; đề xuất kế hoạch dòng tiền nộp thuế hợp pháp.",en:"Refuse invoices with no real transaction, file the correct VAT payable, warn the chief accountant and director in writing of the legal risk and propose a lawful tax cash plan."},shortcut:{vi:"Nhận hóa đơn để giảm 30 triệu đồng thuế, lưu chứng từ chuyển khoản cho có vẻ hợp lệ.",en:"Take the invoices to cut VND 30 million of tax and keep the transfer slip so it looks valid."},wait:{vi:"Chưa nộp tờ khai, chờ giám đốc tự quyết định và chấp nhận nộp chậm.",en:"Hold the return, wait for the director to decide and accept late filing."}},questions:{vi:["Vì sao doanh thu xuất khẩu áp dụng thuế suất 0% chứ không phải KCT? Trình bày cách bạn tính lại số thuế còn phải nộp.","Hóa đơn 71,5 triệu đồng trả tiền mặt cần xử lý thế nào và doanh nghiệp nên sửa quy trình thanh toán ra sao?"],en:["Why do export sales take the 0% rate rather than KCT? Show how you recalculated the VAT payable.","How should the VND 71.5 million cash-paid invoice be treated, and how should the payment process be fixed?"]},hints:{vi:["Đối chiếu từng dòng doanh thu trên tờ khai nháp với hồ sơ xuất khẩu đã duyệt trước khi chọn thuế suất.","Lọc bảng kê đầu vào theo hình thức thanh toán và áp điều kiện khấu trừ ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi đề nghị mua bán hóa đơn phải bị từ chối và báo cáo bằng văn bản."],en:["Match each sales line on the draft return with the approved export file before choosing the rate.","Filter the input listing by payment method and apply the credit condition in SOP 3.2.","Re-read SOP 4.2: any offer to buy or sell invoices must be refused and reported in writing."]}},learning:{summary:{vi:"Chuyên viên kế toán thuế lập, kê khai và quyết toán các loại thuế như GTGT, TNDN, TNCN và thuế nhà thầu; kiểm soát hóa đơn đầu vào, đầu ra; xác định chi phí được trừ; theo dõi nghĩa vụ nộp và làm việc với cơ quan thuế khi kiểm tra, thanh tra hoặc hoàn thuế. Giá trị tạo ra là tuân thủ đầy đủ, tránh truy thu và phạt, đồng thời tận dụng hợp pháp các ưu đãi. Nghề đòi hỏi cập nhật văn bản liên tục và giữ chuẩn mực liêm chính.",en:"A tax accountant prepares, files and finalizes taxes such as VAT, corporate income tax, personal income tax and foreign contractor tax; controls input and output invoices; determines deductible expenses; tracks payment obligations and works with the tax authority on audits, inspections and refunds. The value is full compliance, no back taxes or penalties and lawful use of incentives. The role requires constant regulatory updates and firm integrity."},responsibilities:{vi:["Lập và nộp tờ khai thuế GTGT, TNCN, thuế nhà thầu theo tháng hoặc quý đúng hạn.","Kiểm tra tính hợp pháp và trạng thái hóa đơn đầu vào trước khi khấu trừ.","Tạm tính, quyết toán thuế TNDN và xác định chi phí được trừ, không được trừ.","Chuẩn bị hồ sơ hoàn thuế GTGT cho hàng xuất khẩu và giải trình khi được yêu cầu.","Cập nhật văn bản pháp luật thuế và đề xuất quy trình kiểm soát rủi ro thuế."],en:["Prepare and file monthly or quarterly VAT, PIT and contractor tax returns on time.","Check legality and status of input invoices before claiming credits.","Make provisional and annual CIT filings and determine deductible and non-deductible costs.","Prepare VAT refund files for exports and provide explanations on request.","Track tax law updates and propose tax risk control procedures."]},competencies:[{name:{vi:"Kê khai thuế GTGT",en:"VAT compliance"},desc:{vi:"Phân biệt thuế suất, đối tượng không chịu thuế, điều kiện khấu trừ và hoàn thuế.",en:"Distinguish rates, exempt supplies, credit conditions and refund rules."}},{name:{vi:"Thuế TNDN & chi phí được trừ",en:"CIT & deductible costs"},desc:{vi:"Điều chỉnh từ lợi nhuận kế toán sang thu nhập tính thuế và lập tờ khai quyết toán.",en:"Adjust accounting profit to taxable income and prepare the annual return."}},{name:{vi:"Kiểm soát hóa đơn điện tử",en:"E-invoice control"},desc:{vi:"Tra cứu trạng thái hóa đơn, người bán và chứng từ thanh toán trước khi ghi nhận.",en:"Check invoice status, seller status and payment evidence before recording."}},{name:{vi:"Đọc hiểu văn bản pháp luật",en:"Regulatory interpretation"},desc:{vi:"Tìm đúng văn bản đang hiệu lực, hiểu điều khoản chuyển tiếp và áp dụng vào nghiệp vụ.",en:"Find the effective rule, understand transition clauses and apply them to transactions."}},{name:{vi:"Liêm chính & quản trị rủi ro thuế",en:"Integrity & tax risk"},desc:{vi:"Từ chối hóa đơn không có giao dịch thật, cảnh báo rủi ro và lưu hồ sơ đầy đủ.",en:"Refuse invoices without real transactions, flag risks and keep full records."}}],knowledge:{vi:["Luật Quản lý thuế số 38/2019/QH14, Nghị định 126/2020/NĐ-CP và Thông tư 80/2021/TT-BTC về khai, nộp thuế (cùng văn bản sửa đổi, thay thế).","Luật Thuế giá trị gia tăng số 48/2024/QH15 (hiệu lực từ 01/07/2025): đối tượng chịu thuế, thuế suất, khấu trừ, hoàn thuế.","Nghị định 123/2020/NĐ-CP và Thông tư 78/2021/TT-BTC về hóa đơn điện tử.","Luật Thuế TNDN và văn bản hướng dẫn hiện hành về doanh thu, chi phí được trừ và ưu đãi.","VAS 17 Thuế thu nhập doanh nghiệp và Nghị định 132/2020/NĐ-CP về giao dịch liên kết."],en:["Tax Administration Law No. 38/2019/QH14, Decree 126/2020/ND-CP and Circular 80/2021/TT-BTC on filing and payment (with amending or replacing documents).","VAT Law No. 48/2024/QH15 (effective 1 July 2025): taxable supplies, rates, credits and refunds.","Decree 123/2020/ND-CP and Circular 78/2021/TT-BTC on e-invoices.","The current CIT Law and guidance on revenue, deductible costs and incentives.","VAS 17 Income taxes and Decree 132/2020/ND-CP on related-party transactions."]},tools:["Cổng thuế điện tử","Phần mềm hỗ trợ kê khai thuế","Hệ thống hóa đơn điện tử","Phần mềm kế toán (ERP)","Microsoft Excel"],kpis:{vi:["Tỷ lệ tờ khai nộp đúng hạn và không phải khai bổ sung.","Số tiền truy thu, phạt sau kiểm tra thuế (mục tiêu bằng 0).","Tỷ lệ hóa đơn đầu vào được tra cứu trạng thái trước khi kê khai.","Thời gian hoàn tất hồ sơ hoàn thuế GTGT."],en:["Share of returns filed on time with no amendments.","Back taxes and penalties after audits (target zero).","Share of input invoices status-checked before filing.","Time to complete a VAT refund file."]},day:[{time:"08:00",vi:"Tải hóa đơn điện tử đầu vào mới, tra cứu trạng thái người bán và hóa đơn.",en:"Download new input e-invoices and check seller and invoice status."},{time:"10:00",vi:"Đối chiếu doanh thu trên hóa đơn với sổ kế toán và hồ sơ xuất khẩu.",en:"Match invoiced sales with the ledger and the export files."},{time:"13:30",vi:"Lập tờ khai thuế GTGT và bảng tính thuế nhà thầu cho hợp đồng dịch vụ nước ngoài.",en:"Prepare the VAT return and the contractor tax worksheet for a foreign service contract."},{time:"15:30",vi:"Rà soát chi phí không được trừ cho tạm tính thuế TNDN quý.",en:"Review non-deductible costs for the quarterly CIT provisional filing."},{time:"17:00",vi:"Nộp tờ khai, lưu biên nhận điện tử và cập nhật lịch nghĩa vụ thuế.",en:"File the return, save the e-receipt and update the tax calendar."}],mistakes:{vi:["Coi doanh thu xuất khẩu là không chịu thuế, mất quyền khấu trừ và hoàn thuế đầu vào.","Khấu trừ thuế của hóa đơn trả tiền mặt vượt ngưỡng hoặc của người bán đã ngừng hoạt động.","Đưa chi phí không có hóa đơn hợp lệ hoặc không phục vụ kinh doanh vào chi phí được trừ."],en:["Treating exports as exempt, losing the right to credit and refund input VAT.","Crediting VAT on cash-paid invoices above the threshold or from sellers that ceased operation.","Deducting costs without valid invoices or not related to the business."]},career:[{vi:"Nhân viên kế toán thuế",en:"Tax accounting assistant"},{vi:"Chuyên viên thuế doanh nghiệp",en:"Corporate tax specialist"},{vi:"Quản lý thuế",en:"Tax manager"},{vi:"Giám đốc thuế (Head of Tax)",en:"Head of Tax"}],glossary:[{term:"Khấu trừ thuế GTGT",vi:"Trừ thuế GTGT đầu vào đủ điều kiện khỏi thuế GTGT đầu ra để xác định số phải nộp.",en:"VAT credit: deducting eligible input VAT from output VAT to find the amount payable."},{term:"KCT",vi:"Hàng hóa, dịch vụ không chịu thuế GTGT; thuế đầu vào liên quan không được khấu trừ.",en:"VAT-exempt supplies; related input VAT cannot be credited."},{term:"Thuế suất 0%",vi:"Thuế suất áp dụng cho hàng xuất khẩu đủ điều kiện; đầu ra bằng 0 nhưng vẫn được khấu trừ đầu vào.",en:"The rate for qualifying exports; output VAT is zero but input VAT remains creditable."},{term:"Chi phí được trừ",vi:"Chi phí thực tế phát sinh, phục vụ kinh doanh, có hóa đơn, chứng từ hợp lệ khi tính thuế TNDN.",en:"Deductible expense: a real business cost with valid invoices and documents for CIT."},{term:"FCT",vi:"Thuế nhà thầu nước ngoài, áp dụng cho thu nhập của tổ chức, cá nhân nước ngoài từ Việt Nam.",en:"Foreign contractor tax on income that foreign entities or individuals earn from Vietnam."}],quiz:[{q:{vi:"Thuế đầu ra 150 triệu đồng; đầu vào trên hóa đơn 120 triệu đồng, trong đó 4 triệu đồng không đủ điều kiện khấu trừ; kỳ trước chuyển sang 10 triệu đồng. Thuế còn phải nộp?",en:"Output VAT is VND 150 million; input VAT on invoices is VND 120 million, of which VND 4 million is not creditable; credit carried forward is VND 10 million. What is payable?"},options:{vi:["20 triệu đồng","30 triệu đồng","24 triệu đồng","34 triệu đồng"],en:["VND 20 million","VND 30 million","VND 24 million","VND 34 million"]},answer:2,explain:{vi:"Đầu vào được khấu trừ 116 triệu đồng; 150 - 116 - 10 = 24 triệu đồng.",en:"Creditable input VAT is VND 116 million; 150 - 116 - 10 = VND 24 million."}},{q:{vi:"Điểm khác biệt quan trọng giữa hàng xuất khẩu thuế suất 0% và hàng không chịu thuế GTGT là gì?",en:"What is the key difference between 0% rated exports and VAT-exempt supplies?"},options:{vi:["Hàng 0% được khấu trừ, hoàn thuế đầu vào; hàng không chịu thuế thì không","Không có khác biệt vì đầu ra đều bằng 0","Hàng không chịu thuế được hoàn thuế nhanh hơn","Hàng 0% không phải lập hóa đơn"],en:["0% rated goods allow input credit and refunds; exempt goods do not","No difference since output VAT is zero in both","Exempt goods get faster refunds","0% rated goods need no invoice"]},answer:0,explain:{vi:"Cả hai đều có thuế đầu ra bằng 0, nhưng chỉ hàng chịu thuế suất 0% mới được khấu trừ, hoàn thuế đầu vào.",en:"Both have zero output VAT, but only 0% rated supplies keep the right to credit and refund input VAT."}},{q:{vi:"Khoản nào thường KHÔNG được tính vào chi phí được trừ khi xác định thu nhập chịu thuế TNDN?",en:"Which item is normally NOT deductible when computing CIT taxable income?"},options:{vi:["Tiền lương có hợp đồng và chứng từ chi trả","Tiền phạt vi phạm hành chính","Khấu hao TSCĐ dùng cho sản xuất","Chi phí thuê văn phòng có hóa đơn"],en:["Salaries with contracts and payment proof","Administrative fines","Depreciation of production assets","Office rent with an invoice"]},answer:1,explain:{vi:"Tiền phạt vi phạm hành chính là khoản không được trừ; các khoản còn lại được trừ khi đủ hồ sơ.",en:"Administrative fines are non-deductible; the other items are deductible when properly documented."}},{q:{vi:"Giám đốc yêu cầu mua hóa đơn đầu vào không có giao dịch thật để giảm thuế. Bạn làm gì?",en:"The director asks you to buy input invoices with no real transaction to cut tax. What do you do?"},options:{vi:["Mua vì giám đốc đã đồng ý","Mua một nửa để giảm rủi ro","Chờ cơ quan thuế kiểm tra rồi tính","Từ chối, kê khai đúng và báo cáo rủi ro bằng văn bản"],en:["Buy them since the director agreed","Buy half to reduce risk","Wait for a tax audit and see","Refuse, file correctly and report the risk in writing"]},answer:3,explain:{vi:"Mua bán hóa đơn không có giao dịch thật là hành vi vi phạm pháp luật nghiêm trọng; phải từ chối và lưu bằng chứng.",en:"Trading invoices without real transactions is a serious legal violation; refuse and keep evidence."}}],tools_en:["E-tax portal","Tax filing support software","E-invoicing system","Accounting software (ERP)","Microsoft Excel"]}},"KK-113":{scenario:{legacy:"B"},learning:{summary:{vi:"Kế toán công nợ phải thu, phải trả theo dõi toàn bộ quan hệ thanh toán với khách hàng và nhà cung cấp: đối chiếu ba chiều đơn mua - phiếu nhập - hóa đơn trước khi thanh toán, lập lịch chi theo hạn, theo dõi tuổi nợ, đối chiếu công nợ định kỳ, trích lập dự phòng nợ khó đòi và phối hợp thu hồi nợ. Giá trị tạo ra là dòng tiền lành mạnh, không chi trùng, không chi sai, không để nợ quá hạn kéo dài.",en:"An AR/AP specialist manages all payment relationships with customers and suppliers: three-way matching of purchase order, goods receipt and invoice before payment, scheduling payments by due date, tracking aging, running periodic balance confirmations, providing for doubtful debts and supporting collections. The value is healthy cash flow, no duplicate or wrong payments and no long-overdue receivables."},responsibilities:{vi:["Đối chiếu ba chiều đơn mua, phiếu nhập kho và hóa đơn trước khi đề nghị thanh toán.","Lập lịch thanh toán nhà cung cấp theo hạn, điều khoản chiết khấu và kế hoạch dòng tiền.","Theo dõi tuổi nợ phải thu, nhắc nợ và phối hợp kinh doanh thu hồi khoản quá hạn.","Gửi và đối chiếu biên bản xác nhận công nợ định kỳ, xử lý chênh lệch.","Đề xuất trích lập dự phòng nợ phải thu khó đòi và đánh giá lại công nợ gốc ngoại tệ."],en:["Three-way match purchase orders, goods receipts and invoices before requesting payment.","Schedule supplier payments by due date, discount terms and the cash plan.","Track receivable aging, send reminders and work with Sales to collect overdue items.","Send and reconcile periodic balance confirmations and resolve differences.","Propose doubtful debt provisions and revalue foreign currency balances."]},competencies:[{name:{vi:"Đối chiếu ba chiều",en:"Three-way matching"},desc:{vi:"So khớp số lượng, đơn giá, thuế và tổng tiền giữa đơn mua, phiếu nhập và hóa đơn.",en:"Match quantity, unit price, tax and totals across the PO, goods receipt and invoice."}},{name:{vi:"Quản lý tuổi nợ",en:"Aging management"},desc:{vi:"Phân nhóm nợ theo thời gian quá hạn, ưu tiên thu hồi và cảnh báo rủi ro tín dụng.",en:"Bucket balances by days overdue, prioritize collection and flag credit risk."}},{name:{vi:"Đối chiếu công nợ",en:"Balance confirmation"},desc:{vi:"Lập biên bản xác nhận, truy vết chênh lệch do hóa đơn, thanh toán hoặc trả hàng chưa ghi.",en:"Issue confirmations and trace gaps from unrecorded invoices, payments or returns."}},{name:{vi:"Kiểm soát thanh toán",en:"Payment control"},desc:{vi:"Ngăn chi trùng, chi sai tài khoản và thay đổi thông tin ngân hàng nhà cung cấp chưa xác minh.",en:"Prevent duplicate payments, wrong accounts and unverified supplier bank changes."}},{name:{vi:"Chính trực & phân tách nhiệm vụ",en:"Integrity & segregation"},desc:{vi:"Không duyệt hóa đơn chưa khớp theo áp lực, giữ tách bạch người lập, người duyệt, người chi.",en:"Never approve unmatched invoices under pressure; keep preparer, approver and payer separate."}}],knowledge:{vi:["Thông tư 48/2019/TT-BTC về dự phòng: nợ quá hạn từ 6 tháng đến dưới 1 năm trích 30%, 1 đến dưới 2 năm 50%, 2 đến dưới 3 năm 70%, từ 3 năm trở lên 100%.","Hạch toán TK 131 phải thu khách hàng và TK 331 phải trả người bán theo chế độ kế toán doanh nghiệp (Thông tư 200/2014/TT-BTC và văn bản thay thế).","VAS 10 về ảnh hưởng của thay đổi tỷ giá: đánh giá lại số dư công nợ gốc ngoại tệ cuối kỳ.","Nghị định 123/2020/NĐ-CP về hóa đơn điện tử, hóa đơn điều chỉnh và thay thế.","Nguyên tắc kiểm soát nội bộ: phân tách nhiệm vụ, phê duyệt theo hạn mức, đối chiếu độc lập."],en:["Circular 48/2019/TT-BTC on provisions: overdue 6 months to under 1 year 30%, 1 to under 2 years 50%, 2 to under 3 years 70%, 3 years or more 100%.","Accounts 131 trade receivables and 331 trade payables under the enterprise accounting regime (Circular 200/2014/TT-BTC and its replacement).","VAS 10 on exchange rate effects: revaluing foreign currency receivable and payable balances at period end.","Decree 123/2020/ND-CP on e-invoices, adjusting and replacement invoices.","Internal control principles: segregation of duties, approval limits and independent reconciliation."]},tools:["Phần mềm kế toán (ERP) phân hệ công nợ","Hệ thống hóa đơn điện tử","Ngân hàng điện tử","Microsoft Excel","Công cụ nhắc nợ tự động qua email"],kpis:{vi:["Số ngày thu tiền bình quân (DSO) và số ngày trả tiền bình quân (DPO).","Tỷ lệ nợ phải thu quá hạn trên 90 ngày.","Số lần chi trùng hoặc chi sai (mục tiêu bằng 0).","Tỷ lệ khách hàng, nhà cung cấp lớn đã xác nhận công nợ cuối kỳ."],en:["Days sales outstanding (DSO) and days payable outstanding (DPO).","Share of receivables more than 90 days overdue.","Duplicate or wrong payments (target zero).","Share of key customers and suppliers confirming period-end balances."]},day:[{time:"08:00",vi:"Kiểm tra tiền về tài khoản, cấn trừ các khoản khách hàng đã thanh toán.",en:"Check incoming funds and apply customer payments to open invoices."},{time:"09:30",vi:"Đối chiếu ba chiều các hóa đơn nhà cung cấp mới và trả lại hồ sơ chưa khớp.",en:"Three-way match new supplier invoices and return unmatched files."},{time:"13:30",vi:"Lập lịch thanh toán tuần, trình duyệt theo hạn mức và kế hoạch dòng tiền.",en:"Prepare the weekly payment run and submit for approval by limits and cash plan."},{time:"15:00",vi:"Gọi nhắc nợ khách hàng quá hạn, cập nhật cam kết thanh toán vào hệ thống.",en:"Call overdue customers and log payment promises in the system."},{time:"16:30",vi:"Cập nhật báo cáo tuổi nợ, đề xuất dự phòng và gửi biên bản đối chiếu công nợ.",en:"Update the aging report, propose provisions and send balance confirmations."}],mistakes:{vi:["Thanh toán theo hóa đơn khi số lượng chưa khớp phiếu nhập kho, dẫn tới trả thừa tiền.","Đổi tài khoản ngân hàng nhà cung cấp theo email mà không gọi xác minh độc lập, bị lừa đảo chuyển tiền.","Không trích lập dự phòng cho khoản nợ quá hạn lâu, làm tài sản và lợi nhuận bị phản ánh cao hơn thực tế."],en:["Paying an invoice whose quantity does not match the goods receipt, causing overpayment.","Changing supplier bank details from an email without independent call-back, enabling payment fraud.","Not providing for long-overdue debts, overstating assets and profit."]},career:[{vi:"Nhân viên kế toán công nợ",en:"AR/AP clerk"},{vi:"Chuyên viên kế toán công nợ",en:"AR/AP specialist"},{vi:"Trưởng nhóm thu chi & tín dụng",en:"Credit & payments team lead"},{vi:"Kế toán tổng hợp / Quản lý ngân quỹ",en:"General accountant / Treasury manager"}],glossary:[{term:"Three-way match",vi:"Đối chiếu ba chiều giữa đơn mua, phiếu nhập kho và hóa đơn trước khi duyệt thanh toán.",en:"Matching the purchase order, goods receipt and invoice before approving payment."},{term:"Aging",vi:"Báo cáo tuổi nợ phân nhóm số dư theo số ngày chưa thanh toán hoặc quá hạn.",en:"A report grouping balances by days outstanding or overdue."},{term:"DSO",vi:"Số ngày thu tiền bình quân = phải thu bình quân / doanh thu bán chịu x số ngày trong kỳ.",en:"Days sales outstanding = average receivables / credit sales x days in the period."},{term:"Dự phòng nợ khó đòi",vi:"Khoản ước tính tổn thất của nợ phải thu có khả năng không thu hồi, ghi giảm tài sản và tăng chi phí.",en:"Doubtful debt provision: estimated loss on receivables unlikely to be collected, reducing assets."},{term:"Credit note",vi:"Chứng từ ghi giảm khoản phải thu hoặc phải trả do giảm giá, trả lại hàng hoặc điều chỉnh.",en:"A document reducing a receivable or payable for discounts, returns or adjustments."}],quiz:[{q:{vi:"Khoản phải thu 200 triệu đồng đã quá hạn 14 tháng, chưa trích dự phòng. Theo Thông tư 48/2019/TT-BTC, mức dự phòng là bao nhiêu?",en:"A VND 200 million receivable is 14 months overdue with no provision yet. Under Circular 48/2019/TT-BTC, what is the provision?"},options:{vi:["60 triệu đồng","140 triệu đồng","200 triệu đồng","100 triệu đồng"],en:["VND 60 million","VND 140 million","VND 200 million","VND 100 million"]},answer:3,explain:{vi:"Quá hạn từ 1 năm đến dưới 2 năm trích 50%: 200 x 50% = 100 triệu đồng.",en:"Overdue 1 to under 2 years requires 50%: 200 x 50% = VND 100 million."}},{q:{vi:"Hóa đơn ghi 128 đơn vị nhưng phiếu nhập kho chỉ có 120. Bạn xử lý thế nào?",en:"The invoice shows 128 units but the goods receipt shows 120. What do you do?"},options:{vi:["Thanh toán đủ 128 vì đã có hóa đơn","Tạm dừng, yêu cầu nhà cung cấp điều chỉnh hóa đơn theo số lượng thực nhận","Thanh toán 128 rồi trừ vào lần sau","Sửa phiếu nhập cho khớp hóa đơn"],en:["Pay 128 since there is an invoice","Hold it and ask the supplier to adjust the invoice to the received quantity","Pay 128 and offset next time","Change the receipt to match the invoice"]},answer:1,explain:{vi:"Chỉ thanh toán theo số lượng thực nhận đã được xác nhận; hóa đơn sai phải được điều chỉnh.",en:"Pay only for confirmed received quantities; the wrong invoice must be adjusted."}},{q:{vi:"Nhận email đổi số tài khoản ngân hàng từ nhà cung cấp ngay trước kỳ thanh toán. Bước đúng tiếp theo là gì?",en:"An email asks to change a supplier's bank account just before a payment run. What is the right next step?"},options:{vi:["Gọi xác minh qua số điện thoại đã lưu trong hồ sơ và trình duyệt thay đổi","Cập nhật ngay để kịp thanh toán","Chuyển thử một khoản nhỏ vào tài khoản mới","Hỏi lại qua chính email đó"],en:["Call back on the phone number on file and get the change approved","Update it at once to pay on time","Send a small test payment to the new account","Reply to the same email to confirm"]},answer:0,explain:{vi:"Xác minh độc lập qua kênh đã lưu trước đó là kiểm soát chống lừa đảo thay đổi thông tin thanh toán.",en:"Independent call-back through a known channel is the key control against payment diversion fraud."}},{q:{vi:"Quản lý yêu cầu duyệt hóa đơn chưa khớp đơn mua ngay hôm nay rồi điều chỉnh hồ sơ sau. Phương án đúng là gì?",en:"A manager asks you to approve an invoice that does not match the PO today and fix the records later. What is right?"},options:{vi:["Duyệt vì quản lý đã yêu cầu","Duyệt một phần cho kịp","Từ chối, đối chiếu đơn mua đã duyệt và yêu cầu hóa đơn điều chỉnh","Chờ cuối tháng rồi tính"],en:["Approve because the manager asked","Approve part of it to save time","Refuse, reconcile with the approved PO and request a corrected invoice","Wait until month end"]},answer:2,explain:{vi:"Duyệt hóa đơn chưa khớp làm mất kiểm soát chi; phải đối chiếu và có chứng từ điều chỉnh trước.",en:"Approving unmatched invoices breaks payment control; reconcile and obtain a corrected document first."}}],tools_en:["ERP accounting software - AR/AP module","E-invoicing system","Online banking","Microsoft Excel","Automated email dunning tools"]}},"KK-114":{scenario:{company:"Coral Peak Plastics",supervisor:{name:"Đỗ Minh Quân",role:{vi:"Kế toán trưởng nhà máy",en:"Plant Chief Accountant"}},ref_code:"CP-2610",title:{vi:"Giá thành thật, tồn kho thật, lợi nhuận thật.",en:"True cost, true inventory, true profit."},brief:{vi:"Bạn soát phiếu tính giá thành CP-2610 tháng 10/2026 của dây chuyền ép nhựa. Công suất bình thường 10.000 sản phẩm/tháng, thực tế sản xuất 8.000 sản phẩm, không có dở dang đầu và cuối kỳ. Chi phí (số liệu mô phỏng): nguyên vật liệu trực tiếp 1.200 triệu đồng, nhân công trực tiếp 480 triệu đồng, sản xuất chung biến đổi 160 triệu đồng, sản xuất chung cố định 400 triệu đồng. Sửa tài khoản ghi nhận phần chi phí cố định không phân bổ và giá thành đơn vị theo VAS 02.",en:"You are reviewing cost sheet CP-2610 for October 2026 of the injection molding line. Normal capacity is 10,000 units per month, actual output is 8,000 units, with no opening or closing work in progress. Costs (training data): direct materials VND 1,200 million, direct labor VND 480 million, variable overhead VND 160 million, fixed overhead VND 400 million. Correct the account for unallocated fixed overhead and the unit cost under VAS 02."},reference_title:{vi:"Chính sách giá thành & bảng phân bổ đã duyệt · CP-2610",en:"Approved costing policy & allocation sheet · CP-2610"},fields:[{id:"UNALLOC_ACC",label:{vi:"TK ghi nhận chi phí SXC cố định không phân bổ",en:"Account for unallocated fixed overhead"},initial:"154",expected:"632",choices:["154","632","642"],reference:"Chính sách giá thành - VAS 02",hint:{vi:"Phần chi phí cố định ứng với công suất không sử dụng không được treo vào giá trị tồn kho, mà là chi phí sản xuất kinh doanh của kỳ.",en:"Fixed cost tied to idle capacity must not sit in inventory value; it is a production cost of the period."}},{id:"UNIT_COST",label:{vi:"Giá thành đơn vị (VND/sản phẩm)",en:"Unit cost (VND per unit)"},initial:"280000",expected:"270000",reference:"Bảng phân bổ chi phí sản xuất chung",ref_value:{vi:"Công suất bình thường 10.000 sp; thực tế 8.000 sp; SXC cố định 400 triệu đồng; chi phí biến đổi 1.840 triệu đồng",en:"Normal capacity 10,000 units; actual 8,000 units; fixed overhead VND 400 million; variable costs VND 1,840 million"},hint:{vi:"Chỉ phân bổ chi phí cố định theo tỷ lệ sản lượng thực tế trên công suất bình thường khi sản lượng thấp hơn công suất.",en:"Allocate fixed overhead by actual output over normal capacity when output is below capacity."}}],sop32:{vi:"SXC cố định phân bổ = SXC cố định x sản lượng thực tế / công suất bình thường (khi thực tế thấp hơn); giá thành đơn vị = (NVLTT + NCTT + SXC biến đổi + SXC cố định phân bổ) / sản lượng hoàn thành.",en:"Allocated fixed overhead = fixed overhead x actual output / normal capacity (when output is lower); unit cost = (DM + DL + variable overhead + allocated fixed overhead) / units completed."},context:{label:"PHIẾU GIÁ THÀNH NHÁP / CP-2610",metrics:[{label:{vi:"Công suất bình thường",en:"Normal capacity"},value:"10,000"},{label:{vi:"Sản lượng thực tế",en:"Actual output"},value:"8,000"},{label:{vi:"SXC cố định",en:"Fixed overhead"},value:"400,000,000 VND"}]},crisis:{vi:"Giám đốc nhà máy đề nghị: “Đưa hết 400 triệu chi phí cố định vào giá thành nhập kho cho giá vốn tháng này thấp, lợi nhuận đạt KPI để cả xưởng được thưởng. Không thì sửa công suất bình thường xuống 8.000 cho khớp.”",en:"The plant director asks: “Put the whole 400 million of fixed cost into inventory so this month's cost of sales is low and we hit the KPI bonus. Otherwise just change normal capacity to 8,000.”"},options:{safe:{vi:"Giữ phương pháp theo VAS 02, ghi phần cố định không phân bổ vào giá vốn, báo kế toán trưởng; nếu cần xem lại công suất bình thường thì đề xuất đánh giá kỹ thuật có căn cứ và phê duyệt chính thức.",en:"Keep the VAS 02 method, book unallocated fixed cost to cost of sales and inform the chief accountant; propose a documented technical review if normal capacity needs revisiting."},shortcut:{vi:"Vốn hóa toàn bộ chi phí cố định vào tồn kho cho đạt KPI, cuối năm tính lại sau.",en:"Capitalize all fixed cost into inventory to hit the KPI and recalculate at year end."},wait:{vi:"Tạm dừng khóa sổ giá thành và chờ giám đốc nhà máy tự quyết định phương pháp.",en:"Pause the cost close and wait for the plant director to choose the method."}},questions:{vi:["Vì sao phần chi phí SXC cố định không phân bổ ghi vào TK 632 mà không vào TK 154? Trình bày cách bạn tính lại giá thành đơn vị.","Nếu vốn hóa toàn bộ chi phí cố định vào tồn kho, báo cáo tài chính bị sai lệch thế nào và ai phải được báo cáo?"],en:["Why is unallocated fixed overhead booked to account 632 rather than 154? Show how you recalculated the unit cost.","If all fixed cost were capitalized into inventory, how would the financial statements be misstated and who must be informed?"]},hints:{vi:["Đặt phiếu giá thành nháp cạnh chính sách giá thành và so sản lượng thực tế với công suất bình thường.","Tách phần chi phí cố định được phân bổ và phần không phân bổ trước khi chia cho sản lượng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không thay đổi phương pháp hay thông số giá thành để đạt chỉ tiêu thưởng."],en:["Place the draft cost sheet next to the costing policy and compare actual output with normal capacity.","Split allocated and unallocated fixed cost before dividing by output in SOP 3.2.","Re-read SOP 4.2: never change costing methods or parameters to hit bonus targets."]}},learning:{summary:{vi:"Kế toán giá thành tập hợp và phân bổ chi phí nguyên vật liệu, nhân công, sản xuất chung cho từng sản phẩm, đơn hàng hoặc công đoạn, đánh giá sản phẩm dở dang, tính giá thành và phân tích biến động so với định mức. Thông tin giá thành giúp định giá bán, kiểm soát lãng phí và ghi nhận đúng giá trị tồn kho, giá vốn. Nghề đòi hỏi hiểu quy trình sản xuất, nắm VAS 02 và phối hợp chặt với kho, kỹ thuật, kế hoạch.",en:"A cost accountant collects and allocates materials, labor and overhead to products, orders or process stages, values work in progress, computes product cost and analyzes variances against standards. Cost data supports pricing, waste control and correct inventory and cost of sales. The role requires understanding the production process, command of VAS 02 and close work with the warehouse, engineering and planning teams."},responsibilities:{vi:["Tập hợp chi phí NVL trực tiếp, nhân công trực tiếp và sản xuất chung theo đối tượng tính giá thành.","Phân bổ chi phí sản xuất chung theo tiêu thức đã duyệt và công suất bình thường.","Đánh giá sản phẩm dở dang cuối kỳ và tính giá thành thành phẩm.","Phân tích biến động giá, lượng so với định mức và báo cáo nguyên nhân.","Phối hợp kiểm kê, đối chiếu định mức tiêu hao và đề xuất cập nhật định mức."],en:["Collect direct materials, direct labor and overhead by costing object.","Allocate overhead using approved drivers and normal capacity.","Value closing work in progress and compute finished goods cost.","Analyze price and usage variances against standards and report causes.","Support stock counts, compare consumption standards and propose updates."]},competencies:[{name:{vi:"Phương pháp tính giá thành",en:"Costing methods"},desc:{vi:"Áp dụng phương pháp giản đơn, hệ số, tỷ lệ, phân bước hoặc theo đơn đặt hàng phù hợp quy trình.",en:"Apply simple, coefficient, ratio, process or job costing to fit the production flow."}},{name:{vi:"Phân bổ chi phí chung",en:"Overhead allocation"},desc:{vi:"Chọn tiêu thức phân bổ hợp lý và xử lý chi phí cố định khi sản lượng dưới công suất.",en:"Choose sound allocation drivers and handle fixed cost when output is below capacity."}},{name:{vi:"Phân tích biến động",en:"Variance analysis"},desc:{vi:"Tách biến động giá, lượng, hiệu suất và giải thích bằng dữ liệu sản xuất.",en:"Split price, usage and efficiency variances and explain them with production data."}},{name:{vi:"Hiểu quy trình sản xuất",en:"Process understanding"},desc:{vi:"Đọc lệnh sản xuất, định mức BOM, báo cáo sản lượng và phế phẩm tại xưởng.",en:"Read work orders, BOM standards, output and scrap reports on the shop floor."}},{name:{vi:"Chính trực số liệu",en:"Data integrity"},desc:{vi:"Không điều chỉnh thông số giá thành để làm đẹp lợi nhuận hay đạt chỉ tiêu thưởng.",en:"Never tweak costing parameters to dress up profit or hit bonus targets."}}],knowledge:{vi:["VAS 02 Hàng tồn kho: giá gốc gồm chi phí mua, chi phí chế biến và chi phí liên quan trực tiếp khác.","Nguyên tắc phân bổ chi phí sản xuất chung cố định theo công suất bình thường; phần không phân bổ ghi vào chi phí trong kỳ.","Hệ thống TK 621, 622, 627, 154, 155, 632 theo chế độ kế toán doanh nghiệp (Thông tư 200/2014/TT-BTC và văn bản thay thế).","Thông tư 53/2006/TT-BTC hướng dẫn áp dụng kế toán quản trị trong doanh nghiệp.","Chi phí định mức, giá thành kế hoạch và phương pháp chi phí theo hoạt động (ABC)."],en:["VAS 02 Inventories: cost includes purchase, conversion and other directly attributable costs.","Fixed production overhead is allocated on normal capacity; the unallocated part is expensed in the period.","Accounts 621, 622, 627, 154, 155 and 632 under the enterprise accounting regime (Circular 200/2014/TT-BTC and its replacement).","Circular 53/2006/TT-BTC guiding management accounting in enterprises.","Standard costing, budgeted cost and activity-based costing (ABC)."]},tools:["Phần mềm ERP phân hệ giá thành","Hệ thống quản lý sản xuất (MES)","Microsoft Excel","Bảng định mức nguyên vật liệu (BOM)","Công cụ BI phân tích chi phí"],kpis:{vi:["Số ngày hoàn tất tính giá thành sau khi khóa sổ kho.","Mức chênh lệch giữa giá thành thực tế và định mức theo từng mã sản phẩm.","Tỷ lệ điều chỉnh giá trị tồn kho do kiểm toán (mục tiêu bằng 0).","Số đề xuất tiết kiệm chi phí được triển khai mỗi quý."],en:["Days to finish costing after the inventory close.","Gap between actual and standard cost per product code.","Audit adjustments to inventory value (target zero).","Cost-saving proposals implemented per quarter."]},day:[{time:"08:00",vi:"Nhận báo cáo sản lượng, phế phẩm ca đêm và đối chiếu với phiếu xuất nguyên vật liệu.",en:"Receive night-shift output and scrap reports and match them with material issues."},{time:"10:00",vi:"Phân bổ chi phí điện, khấu hao, bảo trì vào các dây chuyền theo tiêu thức đã duyệt.",en:"Allocate power, depreciation and maintenance to lines using approved drivers."},{time:"13:30",vi:"Phân tích biến động tiêu hao hạt nhựa so với định mức cùng trưởng ca sản xuất.",en:"Analyze resin usage variance against standard with the shift leader."},{time:"15:30",vi:"Đánh giá sản phẩm dở dang, lập phiếu tính giá thành và bút toán kết chuyển.",en:"Value work in progress, prepare the cost sheet and closing entries."},{time:"17:00",vi:"Gửi báo cáo giá thành và đề xuất cập nhật định mức cho kế toán trưởng.",en:"Send the cost report and standard update proposals to the chief accountant."}],mistakes:{vi:["Vốn hóa toàn bộ chi phí cố định vào tồn kho khi sản lượng thấp, làm giá thành và tồn kho bị thổi phồng.","Dùng tiêu thức phân bổ không phản ánh mức sử dụng nguồn lực, khiến giá thành từng sản phẩm méo mó.","Bỏ qua sản phẩm dở dang cuối kỳ, đẩy toàn bộ chi phí vào thành phẩm."],en:["Capitalizing all fixed cost into inventory when output is low, inflating unit cost and stock.","Using allocation drivers that do not reflect resource use, distorting product costs.","Ignoring closing work in progress and pushing all costs into finished goods."]},career:[{vi:"Nhân viên kế toán kho - sản xuất",en:"Inventory & production accounting clerk"},{vi:"Kế toán giá thành",en:"Cost accountant"},{vi:"Trưởng nhóm kế toán quản trị chi phí",en:"Cost & management accounting lead"},{vi:"Kiểm soát viên tài chính nhà máy (Plant Controller)",en:"Plant Controller"}],glossary:[{term:"Công suất bình thường",vi:"Sản lượng đạt được trung bình trong điều kiện sản xuất bình thường, dùng làm căn cứ phân bổ chi phí cố định.",en:"Normal capacity: the average output under normal conditions, used to allocate fixed overhead."},{term:"WIP",vi:"Sản phẩm dở dang: sản phẩm đang trong quá trình chế biến, chưa hoàn thành tại cuối kỳ.",en:"Work in progress: products still being processed and not finished at period end."},{term:"BOM",vi:"Định mức nguyên vật liệu: danh sách và số lượng vật tư cần cho một đơn vị sản phẩm.",en:"Bill of materials: the list and quantities of materials needed per unit of product."},{term:"Standard cost",vi:"Giá thành định mức xây dựng trước, dùng để so sánh và phân tích biến động với thực tế.",en:"A predetermined cost used to compare with and analyze variances from actual cost."},{term:"ABC",vi:"Phương pháp chi phí theo hoạt động: phân bổ chi phí chung theo các hoạt động tiêu dùng nguồn lực.",en:"Activity-based costing: allocating overhead through the activities that consume resources."}],quiz:[{q:{vi:"Công suất bình thường 5.000 sp, thực tế 4.000 sp, SXC cố định 100 triệu đồng. Phần SXC cố định ghi vào giá vốn trong kỳ là bao nhiêu?",en:"Normal capacity is 5,000 units, actual output 4,000 units, fixed overhead VND 100 million. How much fixed overhead goes to cost of sales in the period?"},options:{vi:["0 đồng","20 triệu đồng","80 triệu đồng","100 triệu đồng"],en:["VND 0","VND 20 million","VND 80 million","VND 100 million"]},answer:1,explain:{vi:"Phân bổ vào giá thành 100 x 4.000 / 5.000 = 80 triệu đồng; 20 triệu đồng không phân bổ ghi vào giá vốn.",en:"Allocated to product 100 x 4,000 / 5,000 = VND 80 million; the unallocated VND 20 million goes to cost of sales."}},{q:{vi:"Khoản nào KHÔNG được tính vào giá gốc hàng tồn kho theo VAS 02?",en:"Which item is NOT included in inventory cost under VAS 02?"},options:{vi:["Chi phí nguyên vật liệu trực tiếp","Chi phí nhân công trực tiếp","Chi phí sản xuất chung biến đổi","Chi phí bán hàng"],en:["Direct materials","Direct labor","Variable production overhead","Selling expenses"]},answer:3,explain:{vi:"Chi phí bán hàng, chi phí quản lý doanh nghiệp và hao hụt bất thường không tính vào giá gốc hàng tồn kho.",en:"Selling costs, administrative costs and abnormal waste are excluded from inventory cost."}},{q:{vi:"Phương pháp tính giá thành nào phù hợp nhất cho xưởng in sản xuất theo từng đơn hàng riêng biệt?",en:"Which costing method best suits a print shop producing separate customer orders?"},options:{vi:["Theo đơn đặt hàng","Phân bước","Hệ số","Giản đơn một sản phẩm"],en:["Job order costing","Process costing","Coefficient method","Simple single-product method"]},answer:0,explain:{vi:"Sản xuất theo đơn hàng riêng biệt tập hợp chi phí và tính giá thành cho từng đơn đặt hàng.",en:"Separate orders call for collecting and computing cost per job."}},{q:{vi:"Giám đốc nhà máy yêu cầu hạ công suất bình thường xuống bằng sản lượng thực tế để giá vốn tháng này thấp. Bạn làm gì?",en:"The plant director asks you to set normal capacity equal to actual output to lower this month's cost of sales. What do you do?"},options:{vi:["Làm theo vì giám đốc hiểu sản xuất nhất","Sửa trong tháng này rồi trả lại tháng sau","Từ chối, giữ thông số đã duyệt và báo kế toán trưởng; chỉ thay đổi khi có đánh giá kỹ thuật được phê duyệt","Bỏ qua chi phí cố định trong tháng"],en:["Comply since the director knows production best","Change it this month and revert next month","Refuse, keep the approved parameter and inform the chief accountant; change only after an approved technical review","Leave out fixed cost for the month"]},answer:2,explain:{vi:"Thay đổi thông số để đạt chỉ tiêu là làm sai lệch báo cáo; mọi thay đổi phải có căn cứ kỹ thuật và phê duyệt.",en:"Changing parameters to hit targets misstates the accounts; changes need technical evidence and approval."}}],tools_en:["ERP product costing module","Manufacturing execution system (MES)","Microsoft Excel","Bill of materials (BOM)","BI tool for cost analysis"]}},"KK-115":{scenario:{company:"Azure Harbor Engineering",supervisor:{name:"Vũ Hoàng Lan",role:{vi:"Giám đốc Tài chính",en:"Chief Financial Officer"}},ref_code:"FS-2512",title:{vi:"Chữ ký kế toán trưởng là cam kết trung thực.",en:"A chief accountant's signature is a pledge of truth."},brief:{vi:"Báo cáo tài chính năm 2025 (FS-2512) chưa phát hành. Ngày 20/01/2026, tòa án ra quyết định mở thủ tục phá sản đối với khách hàng Kestrel Steel Works; khoản phải thu 1.450 triệu đồng phát sinh tháng 11/2025, chưa đến hạn nên chưa trích dự phòng. Quản tài viên ước tính chỉ thu hồi được 20%. Lợi nhuận trước thuế trên bản nháp là 5.800 triệu đồng. Sửa cách xử lý sự kiện theo VAS 23 và lợi nhuận trước thuế sau điều chỉnh, rồi lập tờ trình ký báo cáo.",en:"The 2025 financial statements (FS-2512) have not been issued. On 20 Jan 2026 a court opened bankruptcy proceedings against customer Kestrel Steel Works; the VND 1,450 million receivable arose in Nov 2025 and was not yet due, so no provision was made. The administrator expects to recover only 20%. Draft profit before tax is VND 5,800 million. Correct the VAS 23 treatment and the adjusted profit before tax, then write the sign-off memo."},reference_title:{vi:"Hồ sơ sự kiện sau ngày khóa sổ & đánh giá nợ · FS-2512",en:"Subsequent events & receivable assessment file · FS-2512"},fields:[{id:"EVENT_TYPE",label:{vi:"Xử lý sự kiện sau ngày kết thúc kỳ kế toán năm",en:"Treatment of the subsequent event"},initial:"DISCLOSE-ONLY",expected:"ADJUSTING",choices:["ADJUSTING","DISCLOSE-ONLY","IGNORE"],reference:"Hồ sơ sự kiện sau ngày khóa sổ - VAS 23",hint:{vi:"Hỏi: sự kiện này cung cấp thêm bằng chứng về tình trạng đã tồn tại tại ngày 31/12/2025 hay phát sinh hoàn toàn mới sau đó?",en:"Ask: does the event give more evidence about a condition that existed at 31 Dec 2025, or is it entirely new?"}},{id:"PBT_ADJ",label:{vi:"Lợi nhuận trước thuế sau điều chỉnh (VND)",en:"Adjusted profit before tax (VND)"},initial:"5800000000",expected:"4640000000",reference:"Biên bản đánh giá nợ phải thu",ref_value:{vi:"Phải thu Kestrel 1.450.000.000 đồng; dự kiến thu hồi 20%; LNTT nháp 5.800.000.000 đồng",en:"Kestrel receivable VND 1,450,000,000; expected recovery 20%; draft PBT VND 5,800,000,000"},hint:{vi:"Dự phòng bằng phần dự kiến không thu hồi được; khoản dự phòng làm tăng chi phí và giảm lợi nhuận trước thuế.",en:"The provision equals the part not expected to be recovered; it adds expense and reduces profit before tax."}}],sop32:{vi:"Với khách nợ đã mở thủ tục phá sản, dự phòng = nợ phải thu x (100% - tỷ lệ thu hồi ước tính); lợi nhuận trước thuế sau điều chỉnh = LNTT nháp - dự phòng bổ sung.",en:"For a debtor in bankruptcy proceedings, provision = receivable x (100% - estimated recovery rate); adjusted profit before tax = draft PBT - additional provision."},context:{label:"BCTC NHÁP 2025 / FS-2512",metrics:[{label:{vi:"LNTT bản nháp",en:"Draft PBT"},value:"5,800,000,000 VND"},{label:{vi:"Phải thu Kestrel",en:"Kestrel receivable"},value:"1,450,000,000 VND"},{label:{vi:"Tỷ lệ thu hồi ước tính",en:"Estimated recovery"},value:"20%"}]},crisis:{vi:"Tổng giám đốc nói: “Đừng điều chỉnh, ghi một dòng thuyết minh là đủ. Lợi nhuận phải giữ 5,8 tỷ để kịp hồ sơ vay vốn tuần sau. Kế toán trưởng cứ ký, có gì tôi chịu trách nhiệm.”",en:"The CEO says: “Do not adjust, one line in the notes is enough. Profit must stay at 5.8 billion for next week's loan file. Just sign it, I will take responsibility.”"},options:{safe:{vi:"Từ chối ký báo cáo chưa điều chỉnh, giải trình bằng văn bản theo VAS 23 và quy định trích lập dự phòng, báo chủ sở hữu hoặc Hội đồng quản trị và trao đổi với kiểm toán viên độc lập.",en:"Refuse to sign unadjusted statements, explain in writing under VAS 23 and provisioning rules, report to the owner or the Board and discuss with the external auditor."},shortcut:{vi:"Ký báo cáo như bản nháp vì tổng giám đốc đã nhận trách nhiệm, năm sau trích bù.",en:"Sign the draft because the CEO accepted responsibility and catch up the provision next year."},wait:{vi:"Không ký, không giải trình, để kiểm toán viên và tổng giám đốc tự giải quyết.",en:"Neither sign nor explain, and let the auditor and the CEO settle it."}},questions:{vi:["Vì sao quyết định mở thủ tục phá sản ngày 20/01/2026 là sự kiện cần điều chỉnh BCTC năm 2025? Trình bày cách bạn tính lại lợi nhuận trước thuế.","Kế toán trưởng có quyền và trách nhiệm gì khi bị yêu cầu ký báo cáo tài chính chưa trung thực? Bạn báo cáo cho ai?"],en:["Why is the bankruptcy decision of 20 Jan 2026 an adjusting event for the 2025 statements? Show how you recalculated profit before tax.","What rights and duties does a chief accountant have when asked to sign misleading statements? To whom do you report?"]},hints:{vi:["Đặt ngày xảy ra sự kiện cạnh ngày kết thúc kỳ và ngày phát hành báo cáo để xác định phạm vi VAS 23.","Tính phần nợ dự kiến không thu hồi trước khi trừ vào lợi nhuận ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không ký báo cáo sai lệch trọng yếu dù có cam kết miệng của lãnh đạo."],en:["Place the event date next to the year-end and issue dates to define the VAS 23 window.","Work out the unrecoverable amount before deducting it from profit in SOP 3.2.","Re-read SOP 4.2: never sign materially misstated statements, even with a verbal promise from management."]}},learning:{summary:{vi:"Kế toán trưởng tổ chức bộ máy và công tác kế toán, ban hành chính sách kế toán, kiểm soát thu chi, thuế, tài sản và chịu trách nhiệm về tính trung thực, hợp lý của báo cáo tài chính. Đây là người làm việc trực tiếp với kiểm toán, ngân hàng, cơ quan thuế và tham mưu tài chính cho ban lãnh đạo. Nghề đòi hỏi chứng chỉ kế toán trưởng, hiểu sâu chuẩn mực và pháp luật, năng lực quản lý đội ngũ và bản lĩnh độc lập chuyên môn.",en:"A chief accountant organizes the accounting function, sets accounting policies, controls receipts and payments, taxes and assets, and is responsible for the truth and fairness of the financial statements. The role works directly with auditors, banks and the tax authority and advises management on finance. It requires the chief accountant certificate, deep knowledge of standards and law, team leadership and the courage to stay professionally independent."},responsibilities:{vi:["Tổ chức bộ máy kế toán, phân công nhiệm vụ và kiểm soát chất lượng số liệu.","Ban hành, cập nhật chính sách kế toán và quy chế tài chính nội bộ.","Rà soát, ký báo cáo tài chính, báo cáo thuế và chịu trách nhiệm về tính trung thực.","Làm việc với kiểm toán độc lập, ngân hàng và cơ quan thuế, xử lý các vấn đề trọng yếu.","Tham mưu ban lãnh đạo về dòng tiền, vốn vay, rủi ro tài chính và tuân thủ."],en:["Organize the accounting team, assign duties and control data quality.","Issue and update accounting policies and internal financial rules.","Review and sign financial and tax reports and answer for their truthfulness.","Work with external auditors, banks and the tax authority on material issues.","Advise management on cash flow, borrowing, financial risk and compliance."]},competencies:[{name:{vi:"Chuẩn mực & chính sách kế toán",en:"Standards & policies"},desc:{vi:"Lựa chọn và áp dụng nhất quán chính sách kế toán, xét đoán các ước tính trọng yếu.",en:"Choose and consistently apply policies and judge significant estimates."}},{name:{vi:"Kiểm soát nội bộ tài chính",en:"Financial controls"},desc:{vi:"Thiết kế phân quyền, phê duyệt, đối chiếu để ngăn sai sót và gian lận.",en:"Design authorities, approvals and reconciliations to prevent errors and fraud."}},{name:{vi:"Quản lý đội ngũ",en:"Team leadership"},desc:{vi:"Đào tạo, phân công và đánh giá kế toán viên, giữ tiến độ khóa sổ và báo cáo.",en:"Train, assign and assess accountants and keep close and reporting on schedule."}},{name:{vi:"Giao tiếp với bên ngoài",en:"External relations"},desc:{vi:"Giải trình với kiểm toán, ngân hàng, cơ quan thuế bằng hồ sơ và lập luận chuyên môn.",en:"Explain positions to auditors, banks and tax officers with files and sound reasoning."}},{name:{vi:"Độc lập chuyên môn",en:"Professional independence"},desc:{vi:"Từ chối ký báo cáo sai, báo cáo bằng văn bản cho cấp có thẩm quyền khi bị áp lực.",en:"Refuse to sign misstated reports and escalate in writing to the proper body under pressure."}}],knowledge:{vi:["Luật Kế toán số 88/2015/QH13 và Nghị định 174/2016/NĐ-CP: tiêu chuẩn, trách nhiệm và quyền của kế toán trưởng.","Hệ thống 26 chuẩn mực kế toán Việt Nam (VAS), trong đó VAS 23 về sự kiện phát sinh sau ngày kết thúc kỳ kế toán năm.","VAS 29 về thay đổi chính sách kế toán, ước tính kế toán và các sai sót.","Thông tư 48/2019/TT-BTC về trích lập và xử lý các khoản dự phòng.","Đề án áp dụng chuẩn mực báo cáo tài chính quốc tế IFRS tại Việt Nam (Quyết định 345/QĐ-BTC năm 2020)."],en:["Accounting Law No. 88/2015/QH13 and Decree 174/2016/ND-CP: chief accountant criteria, duties and rights.","The 26 Vietnamese Accounting Standards (VAS), including VAS 23 on events after the reporting period.","VAS 29 on changes in accounting policies, estimates and errors.","Circular 48/2019/TT-BTC on making and using provisions.","Vietnam's IFRS adoption roadmap (Decision 345/QD-BTC of 2020)."]},tools:["Phần mềm kế toán (ERP)","Hệ thống hợp nhất & lập báo cáo tài chính","Cổng thuế điện tử","Ngân hàng điện tử","Microsoft Excel"],kpis:{vi:["Báo cáo tài chính phát hành đúng hạn với ý kiến kiểm toán chấp nhận toàn phần.","Số bút toán điều chỉnh trọng yếu do kiểm toán đề xuất (mục tiêu bằng 0).","Số tiền truy thu, phạt thuế sau thanh tra, kiểm tra.","Số ngày khóa sổ tháng của toàn bộ phòng kế toán."],en:["Statements issued on time with an unmodified audit opinion.","Material audit adjustments (target zero).","Back taxes and penalties after tax audits.","Days for the whole accounting team to close the month."]},day:[{time:"08:00",vi:"Họp nhanh với đội kế toán về tiến độ khóa sổ và các vướng mắc chứng từ.",en:"Hold a quick stand-up with the team on close progress and document issues."},{time:"10:00",vi:"Duyệt đề nghị thanh toán lớn, kiểm tra hồ sơ và hạn mức phê duyệt.",en:"Approve large payment requests, checking files and approval limits."},{time:"13:30",vi:"Làm việc với kiểm toán viên về ước tính dự phòng và sự kiện sau ngày khóa sổ.",en:"Meet the auditors on provision estimates and subsequent events."},{time:"15:30",vi:"Rà soát báo cáo dòng tiền và chỉ tiêu cam kết với ngân hàng cùng giám đốc tài chính.",en:"Review cash flow and bank covenant figures with the CFO."},{time:"17:00",vi:"Ký duyệt chứng từ, cập nhật chính sách kế toán và giao việc cho ngày mai.",en:"Sign documents, update policies and assign tomorrow's tasks."}],mistakes:{vi:["Chỉ thuyết minh sự kiện sau ngày khóa sổ trong khi đó là sự kiện cần điều chỉnh số liệu.","Ký báo cáo theo áp lực lãnh đạo mà không lưu văn bản giải trình, chịu trách nhiệm cá nhân.","Thay đổi chính sách kế toán giữa kỳ để làm đẹp lợi nhuận mà không áp dụng hồi tố và thuyết minh."],en:["Only disclosing a subsequent event that actually requires adjustment.","Signing under management pressure without a written record, taking personal liability.","Changing a policy mid-year to boost profit without retrospective application and disclosure."]},career:[{vi:"Kế toán tổng hợp",en:"General accountant"},{vi:"Phó phòng kế toán",en:"Deputy chief accountant"},{vi:"Kế toán trưởng",en:"Chief accountant"},{vi:"Giám đốc tài chính (CFO)",en:"Chief Financial Officer (CFO)"}],glossary:[{term:"Sự kiện cần điều chỉnh",vi:"Sự kiện sau ngày kết thúc kỳ cung cấp bằng chứng về tình trạng đã tồn tại tại ngày kết thúc kỳ, phải sửa số liệu.",en:"Adjusting event: evidence of conditions that existed at period end, requiring figures to be changed."},{term:"Sự kiện không cần điều chỉnh",vi:"Sự kiện phản ánh tình trạng phát sinh sau ngày kết thúc kỳ, chỉ thuyết minh nếu trọng yếu.",en:"Non-adjusting event: a condition arising after period end, disclosed only if material."},{term:"Hồi tố",vi:"Điều chỉnh số liệu so sánh và số dư đầu kỳ như thể chính sách mới hoặc số đúng đã luôn được áp dụng.",en:"Retrospective restatement: adjusting comparatives and opening balances as if the correct treatment always applied."},{term:"Thư giải trình",vi:"Văn bản ban giám đốc gửi kiểm toán viên xác nhận trách nhiệm và các thông tin đã cung cấp.",en:"Management representation letter confirming responsibilities and information given to the auditor."},{term:"Covenant",vi:"Cam kết tài chính trong hợp đồng vay, ví dụ tỷ lệ nợ trên EBITDA, mà doanh nghiệp phải duy trì.",en:"A financial undertaking in a loan agreement, such as a debt to EBITDA ratio, that must be maintained."}],quiz:[{q:{vi:"Khoản phải thu 800 triệu đồng, khách nợ đã mở thủ tục phá sản, ước tính thu hồi 25%. Mức dự phòng cần trích là bao nhiêu?",en:"A VND 800 million receivable is from a debtor in bankruptcy proceedings with 25% expected recovery. What provision is needed?"},options:{vi:["200 triệu đồng","600 triệu đồng","800 triệu đồng","0 đồng"],en:["VND 200 million","VND 600 million","VND 800 million","VND 0"]},answer:1,explain:{vi:"Dự phòng bằng phần dự kiến không thu hồi: 800 x (100% - 25%) = 600 triệu đồng.",en:"Provision is the unrecoverable part: 800 x (100% - 25%) = VND 600 million."}},{q:{vi:"Sự kiện nào sau ngày kết thúc kỳ kế toán năm là sự kiện KHÔNG cần điều chỉnh?",en:"Which event after the reporting period is a NON-adjusting event?"},options:{vi:["Bản án xác nhận nghĩa vụ bồi thường đã tồn tại tại ngày khóa sổ","Phát hiện gian lận làm báo cáo năm bị sai","Bán hàng tồn kho cuối năm với giá thấp hơn giá gốc","Hỏa hoạn thiêu hủy nhà xưởng vào tháng 2 năm sau"],en:["A court ruling confirming an obligation that existed at year end","Discovery of fraud that misstated the annual figures","Selling year-end inventory below cost","A fire destroying the factory in February of the next year"]},answer:3,explain:{vi:"Hỏa hoạn là tình trạng mới phát sinh sau ngày khóa sổ, chỉ thuyết minh nếu trọng yếu; ba sự kiện còn lại là bằng chứng của tình trạng đã có.",en:"The fire is a new condition after year end, disclosed if material; the other three evidence conditions that already existed."}},{q:{vi:"Tổng giám đốc yêu cầu ký báo cáo tài chính chưa ghi nhận khoản lỗ trọng yếu và hứa tự chịu trách nhiệm. Bạn làm gì?",en:"The CEO asks you to sign statements that omit a material loss and promises to take responsibility. What do you do?"},options:{vi:["Từ chối ký, giải trình bằng văn bản và báo chủ sở hữu hoặc Hội đồng quản trị","Ký vì đã có cam kết của tổng giám đốc","Ký nhưng ghi chú riêng trong sổ tay","Nghỉ phép để người khác ký thay"],en:["Refuse to sign, explain in writing and report to the owner or the Board","Sign because the CEO made a commitment","Sign but keep a private note","Take leave so someone else signs"]},answer:0,explain:{vi:"Kế toán trưởng độc lập về chuyên môn và chịu trách nhiệm về số liệu; cam kết miệng không miễn trách nhiệm.",en:"The chief accountant is professionally independent and answerable for the figures; a verbal promise removes no liability."}},{q:{vi:"Phát hiện sai sót trọng yếu của năm trước. Theo VAS 29, cách xử lý đúng là gì?",en:"A material prior-year error is found. Under VAS 29, what is the right treatment?"},options:{vi:["Ghi toàn bộ vào chi phí năm nay","Bỏ qua vì năm trước đã quyết toán","Điều chỉnh hồi tố số liệu so sánh và số dư đầu kỳ","Chỉ thông báo miệng cho kiểm toán viên"],en:["Expense it all this year","Ignore it since last year is closed","Restate comparatives and opening balances retrospectively","Only tell the auditor verbally"]},answer:2,explain:{vi:"Sai sót trọng yếu kỳ trước phải được điều chỉnh hồi tố và thuyết minh, không ghi vào kết quả kỳ hiện tại.",en:"Material prior-period errors are corrected retrospectively and disclosed, not through current profit."}}],tools_en:["Accounting software (ERP)","Financial consolidation & reporting system","E-tax portal","Online banking","Microsoft Excel"]}},"KK-116":{scenario:{company:"Mekong Breeze Foods",supervisor:{name:"Phan Thanh Tùng",role:{vi:"Trưởng bộ phận Kế toán Kho & Tài sản",en:"Inventory & Asset Accounting Lead"}},ref_code:"INV-2512",title:{vi:"Đếm đúng, ghi đúng, định giá thận trọng.",en:"Count right, record right, value prudently."},brief:{vi:"Kiểm kê kho thành phẩm ngày 31/12/2025 (biên bản INV-2512); công ty áp dụng Thông tư 200/2014/TT-BTC. Phát hiện thiếu 35 thùng sữa hạt trị giá 24,5 triệu đồng, chưa xác định nguyên nhân. Lô 1.200 hộp ngũ cốc có giá gốc 450.000 đồng/hộp; giá bán ước tính 420.000 đồng/hộp, chi phí bán ước tính 18.000 đồng/hộp (số liệu mô phỏng). Sửa tài khoản ghi nhận hàng thiếu và mức dự phòng giảm giá của lô ngũ cốc, rồi lập báo cáo có căn cứ.",en:"The finished goods count on 31 Dec 2025 (record INV-2512) is under review; the company applies Circular 200/2014/TT-BTC. 35 cartons of nut milk worth VND 24.5 million are missing with no known cause. A lot of 1,200 boxes of cereal costs VND 450,000 per box; the estimated selling price is VND 420,000 and estimated selling cost VND 18,000 per box (training data). Correct the shortage account and the write-down provision for the cereal lot, then report."},reference_title:{vi:"Biên bản kiểm kê & bảng đánh giá giá trị thuần · INV-2512",en:"Stock count record & net realizable value sheet · INV-2512"},fields:[{id:"SHORT_ACCT",label:{vi:"TK ghi nhận hàng thiếu chưa rõ nguyên nhân",en:"Account for unexplained shortage"},initial:"632",expected:"1381",choices:["632","1381","811"],reference:"Biên bản kiểm kê & quy chế xử lý",hint:{vi:"Khi chưa có quyết định xử lý của cấp có thẩm quyền, giá trị hàng thiếu phải được theo dõi chờ xử lý, chưa đưa vào chi phí.",en:"Until the authorized decision is made, the shortage value is held pending resolution, not expensed."}},{id:"NRV_PROV",label:{vi:"Dự phòng giảm giá lô ngũ cốc (VND)",en:"Write-down provision for cereal lot (VND)"},initial:"36000000",expected:"57600000",reference:"Bảng đánh giá giá trị thuần",ref_value:{vi:"1.200 hộp; giá gốc 450.000 đ/hộp; giá bán ước tính 420.000 đ/hộp; chi phí bán ước tính 18.000 đ/hộp",en:"1,200 boxes; cost VND 450,000 each; estimated price VND 420,000; estimated selling cost VND 18,000 each"},hint:{vi:"Giá trị thuần có thể thực hiện được không phải giá bán; phải trừ chi phí ước tính để bán được hàng.",en:"Net realizable value is not the selling price; deduct the estimated cost to make the sale."}}],sop32:{vi:"Giá trị thuần có thể thực hiện được = giá bán ước tính - chi phí ước tính để hoàn thành và bán; dự phòng = (giá gốc - giá trị thuần) x số lượng khi giá trị thuần thấp hơn giá gốc (VAS 02).",en:"Net realizable value = estimated selling price - estimated costs to complete and sell; provision = (cost - NRV) x quantity when NRV is below cost (VAS 02)."},context:{label:"BIÊN BẢN KIỂM KÊ NHÁP / INV-2512",metrics:[{label:{vi:"Hàng thiếu chưa rõ nguyên nhân",en:"Unexplained shortage"},value:"24,500,000 VND"},{label:{vi:"Số lượng lô ngũ cốc",en:"Cereal lot quantity"},value:"1,200"},{label:{vi:"Giá gốc mỗi hộp",en:"Cost per box"},value:"450,000 VND"}]},crisis:{vi:"Thủ kho nhắn: “Anh chị ghi giúp 35 thùng thiếu vào hao hụt luôn, đừng lập biên bản truy trách nhiệm. Tháng sau em nâng định mức hao hụt lên là bù được, trưởng kho cũng đồng ý rồi.”",en:"The storekeeper messages you: “Please book the 35 missing cartons as normal loss and skip the accountability record. Next month I will raise the loss allowance to cover it, the warehouse head already agreed.”"},options:{safe:{vi:"Ghi nhận hàng thiếu chờ xử lý, lập biên bản đầy đủ, báo kế toán trưởng và hội đồng kiểm kê để xác định nguyên nhân, trách nhiệm bồi thường; không sửa định mức để che giấu.",en:"Record the shortage as pending, complete the count record, report to the chief accountant and count committee to find cause and liability; never alter allowances to hide it."},shortcut:{vi:"Ghi thẳng vào giá vốn như hao hụt thông thường và bỏ qua biên bản truy trách nhiệm.",en:"Book it straight to cost of sales as normal loss and skip the accountability record."},wait:{vi:"Để nguyên chênh lệch trên sổ, chờ đợt kiểm kê sau xem hàng có xuất hiện lại không.",en:"Leave the difference on the books and wait for the next count to see if the goods reappear."}},questions:{vi:["Vì sao hàng thiếu chưa rõ nguyên nhân phải ghi vào TK 1381? Trình bày cách bạn tính lại dự phòng giảm giá của lô ngũ cốc.","Quy trình xử lý hàng thiếu sau kiểm kê gồm những bước nào và ai có thẩm quyền quyết định?"],en:["Why must an unexplained shortage go to account 1381? Show how you recalculated the cereal write-down.","What steps follow a stock count shortage, and who has the authority to decide?"]},hints:{vi:["Đặt biên bản kiểm kê nháp cạnh quy chế xử lý thừa thiếu và đánh dấu dòng chưa có quyết định xử lý.","Tính giá trị thuần của một hộp trước rồi mới nhân số lượng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi chênh lệch kiểm kê phải được lập biên bản, không điều chỉnh định mức để che giấu."],en:["Place the draft count record next to the shortage policy and flag lines without a decision.","Work out the NRV of one box before multiplying by quantity in SOP 3.2.","Re-read SOP 4.2: every count difference needs a record; never adjust allowances to hide it."]}},learning:{summary:{vi:"Kế toán tài sản cố định và hàng tồn kho quản lý toàn bộ vòng đời tài sản: xác định nguyên giá, mở thẻ và trích khấu hao, theo dõi điều chuyển, sửa chữa, thanh lý; đồng thời tính giá nhập xuất kho, tổ chức kiểm kê, xử lý thừa thiếu và lập dự phòng giảm giá hàng tồn kho. Giá trị tạo ra là tài sản trên sổ khớp với thực tế, được định giá thận trọng và có trách nhiệm rõ ràng. Nghề đòi hỏi tỉ mỉ, nắm chắc VAS 02, VAS 03, VAS 04 và quy định về khấu hao.",en:"A fixed asset and inventory accountant manages the full asset life cycle: determining cost, opening asset cards and depreciating, tracking transfers, repairs and disposals; and also costs stock movements, organizes counts, resolves differences and provides for inventory write-downs. The value is book assets that match reality, are prudently valued and have clear accountability. The role demands precision and solid command of VAS 02, VAS 03, VAS 04 and depreciation rules."},responsibilities:{vi:["Xác định nguyên giá, mở thẻ tài sản cố định và lập lịch khấu hao theo chính sách đã đăng ký.","Ghi nhận tăng, giảm, điều chuyển, sửa chữa lớn và thanh lý tài sản có đủ hồ sơ.","Tính giá xuất kho theo phương pháp đã chọn và đối chiếu thẻ kho với sổ kế toán.","Tổ chức kiểm kê định kỳ, lập biên bản và đề xuất xử lý chênh lệch thừa thiếu.","Đánh giá giá trị thuần có thể thực hiện được và trích lập dự phòng giảm giá hàng tồn kho."],en:["Determine cost, open asset cards and set depreciation schedules under the registered policy.","Record additions, disposals, transfers, major repairs and write-offs with full files.","Cost stock issues by the chosen method and reconcile stock cards with the books.","Run periodic counts, prepare records and propose how to resolve differences.","Assess net realizable value and provide for inventory write-downs."]},competencies:[{name:{vi:"Ghi nhận tài sản cố định",en:"Fixed asset recognition"},desc:{vi:"Phân biệt tài sản cố định với công cụ dụng cụ, tài sản hữu hình với vô hình, chi phí được vốn hóa.",en:"Separate fixed assets from tools, tangible from intangible, and capitalizable costs."}},{name:{vi:"Khấu hao",en:"Depreciation"},desc:{vi:"Chọn phương pháp và thời gian khấu hao phù hợp, trích theo ngày bắt đầu sử dụng.",en:"Choose suitable methods and useful lives and depreciate from the date of use."}},{name:{vi:"Tính giá hàng tồn kho",en:"Inventory costing"},desc:{vi:"Áp dụng nhất quán phương pháp đích danh, bình quân gia quyền hoặc nhập trước xuất trước.",en:"Apply specific identification, weighted average or FIFO consistently."}},{name:{vi:"Tổ chức kiểm kê",en:"Stock count control"},desc:{vi:"Lập kế hoạch kiểm kê, chốt chứng từ, kiểm đếm độc lập và xử lý chênh lệch có trách nhiệm.",en:"Plan counts, lock cut-off, count independently and resolve differences with accountability."}},{name:{vi:"Thận trọng & trung thực",en:"Prudence & honesty"},desc:{vi:"Không che giấu hàng thiếu, không trì hoãn dự phòng khi giá trị thuần giảm.",en:"Never hide shortages or delay write-downs when net realizable value falls."}}],knowledge:{vi:["VAS 02 Hàng tồn kho: giá gốc, giá trị thuần có thể thực hiện được, phương pháp tính giá xuất kho.","VAS 03 Tài sản cố định hữu hình và VAS 04 Tài sản cố định vô hình: điều kiện ghi nhận, nguyên giá.","Thông tư 45/2013/TT-BTC (sửa đổi, bổ sung): tài sản cố định có thời gian sử dụng trên 1 năm và nguyên giá từ 30 triệu đồng trở lên; khung thời gian và phương pháp khấu hao.","Thông tư 48/2019/TT-BTC về dự phòng giảm giá hàng tồn kho.","Thông tư 200/2014/TT-BTC: TK 1381, 3381 xử lý thừa thiếu, không còn áp dụng phương pháp nhập sau xuất trước (LIFO)."],en:["VAS 02 Inventories: cost, net realizable value and cost formulas for issues.","VAS 03 Tangible and VAS 04 Intangible fixed assets: recognition criteria and cost.","Circular 45/2013/TT-BTC (as amended): fixed assets last over 1 year and cost VND 30 million or more; useful life ranges and depreciation methods.","Circular 48/2019/TT-BTC on inventory write-down provisions.","Circular 200/2014/TT-BTC: accounts 1381 and 3381 for shortages and surpluses; LIFO is no longer allowed."]},tools:["Phần mềm ERP phân hệ tài sản & kho","Hệ thống quản lý kho (WMS)","Máy quét mã vạch / RFID","Microsoft Excel","Thẻ và sổ theo dõi tài sản cố định"],kpis:{vi:["Tỷ lệ chênh lệch giá trị kiểm kê so với sổ sách.","Tỷ lệ tài sản cố định được gắn mã và xác nhận hiện trạng hằng năm.","Số ngày hoàn tất xử lý chênh lệch sau kiểm kê.","Số điều chỉnh khấu hao hoặc dự phòng do kiểm toán đề xuất."],en:["Count value variance against book value.","Share of fixed assets tagged and physically verified each year.","Days to resolve count differences.","Depreciation or provision adjustments proposed by auditors."]},day:[{time:"08:00",vi:"Đối chiếu phiếu nhập xuất kho hôm trước với thẻ kho và hệ thống quản lý kho.",en:"Match yesterday's receipts and issues with stock cards and the WMS."},{time:"09:30",vi:"Lập hồ sơ tăng tài sản cho máy đóng gói mới: hóa đơn, biên bản nghiệm thu, chạy thử.",en:"Prepare the addition file for a new packing machine: invoice, acceptance and test-run records."},{time:"13:30",vi:"Chạy khấu hao tháng, rà soát tài sản đã khấu hao hết nhưng vẫn sử dụng.",en:"Run monthly depreciation and review fully depreciated assets still in use."},{time:"15:00",vi:"Kiểm kê chọn mẫu kho thành phẩm cùng thủ kho và kiểm soát nội bộ.",en:"Do a sample count of finished goods with the storekeeper and internal control."},{time:"16:30",vi:"Cập nhật bảng giá trị thuần cho hàng cận hạn và đề xuất dự phòng.",en:"Update the NRV sheet for near-expiry goods and propose provisions."}],mistakes:{vi:["Ghi thẳng hàng thiếu chưa rõ nguyên nhân vào giá vốn, bỏ qua bước xác định trách nhiệm.","Tính giá trị thuần bằng giá bán mà quên trừ chi phí bán hàng, làm thiếu dự phòng.","Ghi nhận tài sản dưới 30 triệu đồng thành tài sản cố định hoặc vốn hóa cả chi phí đào tạo, chạy thử không đạt."],en:["Expensing an unexplained shortage directly and skipping the accountability step.","Using selling price as NRV without deducting selling costs, under-providing.","Recording items under VND 30 million as fixed assets or capitalizing training and failed test costs."]},career:[{vi:"Nhân viên kế toán kho",en:"Inventory accounting clerk"},{vi:"Kế toán tài sản cố định & hàng tồn kho",en:"Fixed asset & inventory accountant"},{vi:"Trưởng nhóm kế toán tài sản & chuỗi cung ứng",en:"Asset & supply chain accounting lead"},{vi:"Kế toán tổng hợp / Kiểm soát viên tài chính",en:"General accountant / Financial controller"}],glossary:[{term:"Nguyên giá",vi:"Toàn bộ chi phí bỏ ra để có tài sản tính đến thời điểm đưa vào trạng thái sẵn sàng sử dụng.",en:"Historical cost: all costs to bring an asset to working condition for its intended use."},{term:"NRV",vi:"Giá trị thuần có thể thực hiện được: giá bán ước tính trừ chi phí hoàn thành và chi phí bán hàng ước tính.",en:"Net realizable value: estimated selling price less estimated costs to complete and sell."},{term:"Khấu hao đường thẳng",vi:"Phân bổ đều nguyên giá trừ giá trị thanh lý ước tính trong suốt thời gian sử dụng.",en:"Straight-line depreciation: spreading cost less residual value evenly over the useful life."},{term:"TK 1381",vi:"Tài sản thiếu chờ xử lý: giá trị tài sản thiếu khi kiểm kê chưa có quyết định xử lý.",en:"Assets missing pending resolution: shortages found at counts awaiting a decision."},{term:"Cut-off",vi:"Chốt chứng từ nhập xuất tại thời điểm kiểm kê để số liệu sổ và thực tế cùng một mốc.",en:"Locking receipt and issue documents at count time so book and physical figures share one point."}],quiz:[{q:{vi:"Máy nguyên giá 600 triệu đồng, khấu hao đường thẳng 5 năm, không có giá trị thanh lý, đưa vào sử dụng ngày 01/07. Khấu hao đến 31/12 cùng năm là bao nhiêu?",en:"A machine costs VND 600 million, straight-line over 5 years with no residual value, in use from 1 July. What is depreciation to 31 December of that year?"},options:{vi:["120 triệu đồng","60 triệu đồng","50 triệu đồng","100 triệu đồng"],en:["VND 120 million","VND 60 million","VND 50 million","VND 100 million"]},answer:1,explain:{vi:"Khấu hao năm 120 triệu đồng, mỗi tháng 10 triệu đồng; từ tháng 7 đến tháng 12 là 6 tháng nên bằng 60 triệu đồng.",en:"Annual depreciation is VND 120 million, VND 10 million a month; July to December is 6 months, so VND 60 million."}},{q:{vi:"Máy tính xách tay giá 26 triệu đồng, dùng 3 năm. Theo Thông tư 45/2013/TT-BTC, kế toán ghi nhận thế nào?",en:"A laptop costs VND 26 million and will be used for 3 years. Under Circular 45/2013/TT-BTC, how is it recorded?"},options:{vi:["Tài sản cố định hữu hình, khấu hao 3 năm","Chi phí toàn bộ trong tháng mua","Công cụ dụng cụ, phân bổ dần vào chi phí","Tài sản cố định vô hình"],en:["Tangible fixed asset depreciated over 3 years","Expensed fully in the month bought","Tools and supplies, allocated to expense over time","Intangible fixed asset"]},answer:2,explain:{vi:"Nguyên giá dưới 30 triệu đồng không đủ tiêu chuẩn tài sản cố định; dùng nhiều kỳ nên phân bổ dần như công cụ dụng cụ.",en:"Cost below VND 30 million fails the fixed asset test; used over several periods, it is allocated as a tool."}},{q:{vi:"Phương pháp tính giá xuất kho nào không còn được áp dụng theo Thông tư 200/2014/TT-BTC?",en:"Which inventory cost formula is no longer allowed under Circular 200/2014/TT-BTC?"},options:{vi:["Thực tế đích danh","Bình quân gia quyền","Nhập trước xuất trước (FIFO)","Nhập sau xuất trước (LIFO)"],en:["Specific identification","Weighted average","First in, first out (FIFO)","Last in, first out (LIFO)"]},answer:3,explain:{vi:"Thông tư 200/2014/TT-BTC đã bỏ phương pháp LIFO; doanh nghiệp chọn đích danh, bình quân gia quyền, FIFO hoặc giá bán lẻ phù hợp.",en:"Circular 200/2014/TT-BTC dropped LIFO; companies use specific identification, weighted average, FIFO or the retail method where suitable."}},{q:{vi:"Thủ kho đề nghị ghi hàng thiếu vào hao hụt và nâng định mức tháng sau để che giấu. Bạn làm gì?",en:"The storekeeper asks you to book a shortage as normal loss and raise next month's allowance to hide it. What do you do?"},options:{vi:["Từ chối, ghi nhận hàng thiếu chờ xử lý và báo kế toán trưởng, hội đồng kiểm kê","Đồng ý vì số tiền không lớn","Ghi một nửa vào hao hụt","Chờ kiểm kê năm sau"],en:["Refuse, record the shortage as pending and report to the chief accountant and count committee","Agree because the amount is small","Book half as normal loss","Wait for next year's count"]},answer:0,explain:{vi:"Che giấu hàng thiếu làm sai lệch sổ sách và có thể che giấu thất thoát; phải lập biên bản và xử lý theo thẩm quyền.",en:"Hiding shortages misstates the books and may conceal theft; record it and resolve it through the proper authority."}}],tools_en:["ERP fixed asset & inventory module","Warehouse management system (WMS)","Barcode / RFID scanners","Microsoft Excel","Fixed asset cards and registers"]}},"KK-141":{scenario:{company:"Vertex Assurance Partners",supervisor:{name:"Hoàng Đức Anh",role:{vi:"Chủ nhiệm kiểm toán",en:"Audit Manager"}},ref_code:"AUD-2512",title:{vi:"Ý kiến kiểm toán theo bằng chứng, không theo phí.",en:"Opinions follow evidence, not fees."},brief:{vi:"Bạn soát giấy làm việc AUD-2512 kiểm toán BCTC năm 2025 của khách hàng Silkwave Textiles. Lợi nhuận trước thuế 9.600 triệu đồng. Theo phương pháp của hãng (mô phỏng): mức trọng yếu tổng thể = 5% LNTT; mức trọng yếu thực hiện = 75% mức tổng thể do rủi ro được đánh giá thấp. Khách hàng từ chối điều chỉnh sai sót đánh giá cao hàng tồn kho 620 triệu đồng; sai sót chỉ giới hạn ở khoản mục này, không lan tỏa. Sửa dạng ý kiến kiểm toán dự kiến và mức trọng yếu thực hiện.",en:"You are reviewing working paper AUD-2512 for the 2025 audit of client Silkwave Textiles. Profit before tax is VND 9,600 million. Under the firm's method (training data): overall materiality = 5% of PBT; performance materiality = 75% of overall materiality as risk is assessed low. The client refuses to correct a VND 620 million inventory overstatement; it is confined to this line item and not pervasive. Correct the proposed opinion and the performance materiality."},reference_title:{vi:"Kế hoạch kiểm toán & tổng hợp sai sót đã duyệt · AUD-2512",en:"Approved audit plan & misstatement summary · AUD-2512"},fields:[{id:"OPINION",label:{vi:"Dạng ý kiến kiểm toán dự kiến",en:"Proposed audit opinion"},initial:"UNMODIFIED",expected:"QUALIFIED",choices:["UNMODIFIED","QUALIFIED","ADVERSE"],reference:"Tổng hợp sai sót chưa điều chỉnh",hint:{vi:"So sánh sai sót chưa điều chỉnh với mức trọng yếu tổng thể, rồi xét tính lan tỏa theo VSA 705.",en:"Compare the uncorrected misstatement with overall materiality, then consider pervasiveness under VSA 705."}},{id:"PERF_MAT",label:{vi:"Mức trọng yếu thực hiện (VND)",en:"Performance materiality (VND)"},initial:"480000000",expected:"360000000",reference:"Bảng xác lập mức trọng yếu",ref_value:{vi:"LNTT 9.600.000.000 đồng; tỷ lệ tổng thể 5%; hệ số thực hiện 75%",en:"PBT VND 9,600,000,000; overall rate 5%; performance factor 75%"},hint:{vi:"Mức trọng yếu thực hiện được đặt thấp hơn mức tổng thể để giảm rủi ro sai sót cộng dồn vượt ngưỡng.",en:"Performance materiality is set below overall materiality to reduce the risk that aggregated errors exceed it."}}],sop32:{vi:"Mức trọng yếu tổng thể = LNTT x 5%; mức trọng yếu thực hiện = mức trọng yếu tổng thể x 75%; ngưỡng sai sót không đáng kể = 5% mức tổng thể (phương pháp mô phỏng của hãng).",en:"Overall materiality = PBT x 5%; performance materiality = overall materiality x 75%; clearly trivial threshold = 5% of overall materiality (firm's training method)."},context:{label:"GIẤY LÀM VIỆC / AUD-2512",metrics:[{label:{vi:"Lợi nhuận trước thuế",en:"Profit before tax"},value:"9,600,000,000 VND"},{label:{vi:"Sai sót chưa điều chỉnh",en:"Uncorrected misstatement"},value:"620,000,000 VND"},{label:{vi:"Đánh giá rủi ro",en:"Risk assessment"},value:"LOW"}]},crisis:{vi:"Giám đốc tài chính của khách hàng gọi riêng: “Em ký chấp nhận toàn phần giúp anh, năm sau bên anh giao thêm hợp đồng tư vấn thuế. Phí năm nay anh trả thêm 20% nếu báo cáo xong trước 31/3.”",en:"The client's CFO calls you privately: “Sign an unmodified opinion for me and next year we will add a tax advisory contract. I will pay 20% more on this year's fee if the report is out before 31 March.”"},options:{safe:{vi:"Từ chối, giữ ý kiến theo bằng chứng và VSA 705, báo chủ nhiệm và thành viên Ban giám đốc phụ trách, tham vấn người soát xét chất lượng; ghi nhận nguy cơ tư lợi đe dọa tính độc lập.",en:"Refuse, keep the evidence-based opinion under VSA 705, inform the manager and engagement partner, consult the quality reviewer and document the self-interest threat to independence."},shortcut:{vi:"Đồng ý ký chấp nhận toàn phần vì sai sót “gần mức trọng yếu” và khách hàng quan trọng.",en:"Agree to an unmodified opinion since the error is “close to materiality” and the client matters."},wait:{vi:"Im lặng, để hồ sơ treo đến khi khách hàng tự điều chỉnh hoặc hết hạn phát hành.",en:"Stay silent and let the file hang until the client adjusts or the deadline passes."}},questions:{vi:["Vì sao ý kiến dự kiến là QUALIFIED chứ không phải UNMODIFIED hay ADVERSE? Trình bày cách bạn xác lập lại mức trọng yếu thực hiện.","Đề nghị tăng phí và giao thêm hợp đồng gây nguy cơ gì cho tính độc lập và bạn xử lý theo quy trình nào?"],en:["Why is the proposed opinion QUALIFIED rather than UNMODIFIED or ADVERSE? Show how you re-set performance materiality.","What independence threat does the fee and contract offer create, and which procedure do you follow?"]},hints:{vi:["Đặt tổng hợp sai sót chưa điều chỉnh cạnh bảng xác lập mức trọng yếu và so từng ngưỡng.","Tính mức trọng yếu tổng thể trước rồi áp hệ số thực hiện ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi lợi ích gắn với dạng ý kiến đều phải từ chối và báo cáo ngay cho người phụ trách hợp đồng."],en:["Place the misstatement summary next to the materiality sheet and compare each threshold.","Work out overall materiality first, then apply the performance factor in SOP 3.2.","Re-read SOP 4.2: any benefit linked to the opinion must be refused and reported at once to the engagement partner."]}},learning:{summary:{vi:"Kiểm toán viên độc lập lập kế hoạch, thực hiện thủ tục và thu thập bằng chứng để đưa ra ý kiến về việc báo cáo tài chính có được trình bày trung thực, hợp lý trên các khía cạnh trọng yếu hay không. Công việc gồm tìm hiểu đơn vị, đánh giá rủi ro, xác lập mức trọng yếu, kiểm tra kiểm soát, thủ tục cơ bản, tổng hợp sai sót và lập báo cáo kiểm toán. Nghề đòi hỏi hoài nghi nghề nghiệp, độc lập và tuân thủ chuẩn mực kiểm toán, đạo đức.",en:"An external auditor plans, performs procedures and gathers evidence to give an opinion on whether financial statements are presented fairly in all material respects. The work covers understanding the entity, assessing risk, setting materiality, testing controls, substantive procedures, summarizing misstatements and issuing the auditor's report. The role requires professional skepticism, independence and adherence to auditing and ethical standards."},responsibilities:{vi:["Tìm hiểu khách hàng, môi trường kiểm soát và đánh giá rủi ro có sai sót trọng yếu.","Xác lập mức trọng yếu tổng thể, mức trọng yếu thực hiện và ngưỡng sai sót không đáng kể.","Thực hiện thủ tục kiểm toán: xác nhận, quan sát kiểm kê, kiểm tra chi tiết, phân tích.","Lập giấy làm việc đầy đủ, tổng hợp sai sót và trao đổi bút toán điều chỉnh với khách hàng.","Đề xuất dạng ý kiến kiểm toán và soạn thư quản lý về khiếm khuyết kiểm soát."],en:["Understand the client and control environment and assess risks of material misstatement.","Set overall materiality, performance materiality and the clearly trivial threshold.","Perform procedures: confirmations, count observation, tests of details and analytics.","Keep complete working papers, summarize misstatements and discuss adjustments with the client.","Propose the audit opinion and draft the management letter on control deficiencies."]},competencies:[{name:{vi:"Đánh giá rủi ro",en:"Risk assessment"},desc:{vi:"Nhận diện rủi ro trọng yếu theo khoản mục và cơ sở dẫn liệu, kể cả rủi ro gian lận.",en:"Identify material risks by account and assertion, including fraud risk."}},{name:{vi:"Trọng yếu & lấy mẫu",en:"Materiality & sampling"},desc:{vi:"Xác lập ngưỡng trọng yếu, thiết kế cỡ mẫu và đánh giá kết quả lấy mẫu.",en:"Set materiality levels, design sample sizes and evaluate sample results."}},{name:{vi:"Thu thập bằng chứng",en:"Evidence gathering"},desc:{vi:"Chọn thủ tục phù hợp, đánh giá độ tin cậy của bằng chứng và lập tài liệu đầy đủ.",en:"Choose suitable procedures, judge evidence reliability and document fully."}},{name:{vi:"Hình thành ý kiến",en:"Forming the opinion"},desc:{vi:"Tổng hợp sai sót, đánh giá tính trọng yếu, lan tỏa và chọn dạng ý kiến đúng chuẩn mực.",en:"Aggregate errors, judge materiality and pervasiveness and pick the right opinion."}},{name:{vi:"Độc lập & hoài nghi",en:"Independence & skepticism"},desc:{vi:"Nhận diện nguy cơ tư lợi, bị đe dọa, quen thuộc và áp dụng biện pháp bảo vệ.",en:"Spot self-interest, intimidation and familiarity threats and apply safeguards."}}],knowledge:{vi:["Luật Kiểm toán độc lập số 67/2011/QH12.","Hệ thống chuẩn mực kiểm toán Việt Nam (VSA) ban hành theo Thông tư 214/2012/TT-BTC, tương thích chuẩn mực quốc tế ISA.","VSA 315, 320, 330 về đánh giá rủi ro, mức trọng yếu và biện pháp xử lý rủi ro; VSA 500, 505, 530 về bằng chứng, xác nhận và lấy mẫu.","VSA 700, 705, 706 về hình thành ý kiến, ý kiến không phải chấp nhận toàn phần và đoạn nhấn mạnh.","Chuẩn mực đạo đức nghề nghiệp kế toán, kiểm toán (Thông tư 70/2015/TT-BTC) và chuẩn mực kiểm soát chất lượng VSQC 1."],en:["Independent Audit Law No. 67/2011/QH12.","Vietnamese Standards on Auditing (VSA) issued under Circular 214/2012/TT-BTC, aligned with ISA.","VSA 315, 320 and 330 on risk assessment, materiality and responses; VSA 500, 505 and 530 on evidence, confirmations and sampling.","VSA 700, 705 and 706 on forming the opinion, modified opinions and emphasis of matter.","The accounting and auditing code of ethics (Circular 70/2015/TT-BTC) and the quality control standard VSQC 1."]},tools:["Phần mềm giấy làm việc kiểm toán điện tử","Công cụ kiểm toán có máy tính hỗ trợ (CAAT)","Microsoft Excel","Nền tảng gửi thư xác nhận điện tử","Chương trình kiểm toán mẫu của hãng"],kpis:{vi:["Tỷ lệ hồ sơ đạt yêu cầu khi soát xét chất lượng nội bộ và kiểm tra của cơ quan quản lý.","Tiến độ hoàn thành hợp đồng so với kế hoạch giờ công.","Tỷ lệ thư xác nhận thu về hoặc có thủ tục thay thế đầy đủ.","Số phát hiện trọng yếu bị bỏ sót được phát hiện ở bước soát xét (mục tiêu bằng 0)."],en:["Share of files passing internal quality review and regulator inspection.","Engagement completion against the budgeted hours.","Share of confirmations returned or covered by full alternative procedures.","Material findings missed and caught only at review (target zero)."]},day:[{time:"08:30",vi:"Họp nhóm kiểm toán tại khách hàng, phân công khoản mục và cập nhật rủi ro trọng yếu.",en:"Meet the audit team on site, assign areas and update significant risks."},{time:"10:00",vi:"Kiểm tra chi tiết doanh thu cuối năm và thủ tục chia cắt niên độ.",en:"Test year-end revenue details and cut-off procedures."},{time:"13:30",vi:"Theo dõi thư xác nhận ngân hàng, công nợ và thực hiện thủ tục thay thế.",en:"Chase bank and receivable confirmations and perform alternative procedures."},{time:"15:30",vi:"Tổng hợp sai sót, trao đổi bút toán điều chỉnh với kế toán trưởng khách hàng.",en:"Summarize misstatements and discuss adjustments with the client's chief accountant."},{time:"17:00",vi:"Hoàn thiện giấy làm việc, ghi lại xét đoán và gửi cho chủ nhiệm soát xét.",en:"Finalize working papers, record judgments and send them for manager review."}],mistakes:{vi:["Dùng mức trọng yếu tổng thể cho thủ tục chi tiết mà không xác lập mức trọng yếu thực hiện.","Để khách hàng tự gửi và nhận thư xác nhận, làm mất độ tin cậy của bằng chứng.","Chấp nhận giải trình của ban giám đốc mà không kiểm chứng, thiếu hoài nghi nghề nghiệp."],en:["Using overall materiality for detailed testing without setting performance materiality.","Letting the client send and receive confirmations, destroying evidence reliability.","Accepting management explanations without corroboration, lacking skepticism."]},career:[{vi:"Trợ lý kiểm toán",en:"Audit associate"},{vi:"Trưởng nhóm kiểm toán",en:"Audit senior"},{vi:"Chủ nhiệm kiểm toán",en:"Audit manager"},{vi:"Thành viên Ban giám đốc (kiểm toán viên hành nghề)",en:"Audit partner (licensed auditor)"}],glossary:[{term:"Materiality",vi:"Mức trọng yếu: ngưỡng mà sai sót vượt qua có thể ảnh hưởng tới quyết định của người sử dụng báo cáo.",en:"The threshold above which misstatements could influence users' decisions."},{term:"Performance materiality",vi:"Mức trọng yếu thực hiện: thấp hơn mức tổng thể, dùng thiết kế thủ tục để kiểm soát sai sót cộng dồn.",en:"A level below overall materiality used to design procedures and control aggregated errors."},{term:"Qualified opinion",vi:"Ý kiến ngoại trừ: báo cáo trung thực hợp lý trừ ảnh hưởng của vấn đề trọng yếu nhưng không lan tỏa.",en:"Fair presentation except for the effects of a matter that is material but not pervasive."},{term:"Assertion",vi:"Cơ sở dẫn liệu: hiện hữu, đầy đủ, quyền và nghĩa vụ, đánh giá, trình bày mà ban giám đốc khẳng định.",en:"Management's claims on existence, completeness, rights and obligations, valuation and presentation."},{term:"Professional skepticism",vi:"Hoài nghi nghề nghiệp: luôn đặt câu hỏi và đánh giá thận trọng bằng chứng kiểm toán.",en:"A questioning mind and critical assessment of audit evidence."}],quiz:[{q:{vi:"Mức trọng yếu tổng thể 800 triệu đồng, ngưỡng sai sót không đáng kể bằng 5% mức tổng thể. Ngưỡng này là bao nhiêu?",en:"Overall materiality is VND 800 million and the clearly trivial threshold is 5% of it. What is the threshold?"},options:{vi:["8 triệu đồng","80 triệu đồng","40 triệu đồng","600 triệu đồng"],en:["VND 8 million","VND 80 million","VND 40 million","VND 600 million"]},answer:2,explain:{vi:"800 x 5% = 40 triệu đồng; sai sót dưới ngưỡng này không cần tổng hợp.",en:"800 x 5% = VND 40 million; errors below it need not be accumulated."}},{q:{vi:"Ai nên kiểm soát việc gửi và nhận thư xác nhận số dư ngân hàng của khách hàng?",en:"Who should control sending and receiving bank balance confirmations?"},options:{vi:["Kiểm toán viên","Kế toán ngân hàng của khách hàng","Giám đốc tài chính khách hàng","Ngân hàng tự quyết định gửi cho ai"],en:["The auditor","The client's bank accountant","The client's CFO","The bank, sending to whomever it chooses"]},answer:0,explain:{vi:"Theo VSA 505, kiểm toán viên phải kiểm soát quá trình xác nhận để bằng chứng đáng tin cậy.",en:"Under VSA 505 the auditor must control the confirmation process so the evidence is reliable."}},{q:{vi:"Không thu thập được bằng chứng đầy đủ và ảnh hưởng có thể vừa trọng yếu vừa lan tỏa. Dạng ý kiến phù hợp là gì?",en:"Sufficient evidence cannot be obtained and the possible effects are both material and pervasive. Which opinion fits?"},options:{vi:["Chấp nhận toàn phần","Ngoại trừ","Trái ngược","Từ chối đưa ra ý kiến"],en:["Unmodified","Qualified","Adverse","Disclaimer of opinion"]},answer:3,explain:{vi:"VSA 705: giới hạn phạm vi có ảnh hưởng trọng yếu và lan tỏa dẫn đến từ chối đưa ra ý kiến.",en:"VSA 705: a scope limitation with material and pervasive possible effects leads to a disclaimer."}},{q:{vi:"Khách hàng hứa tăng phí nếu bạn ký ý kiến chấp nhận toàn phần. Bạn làm gì?",en:"The client offers a higher fee if you sign an unmodified opinion. What do you do?"},options:{vi:["Nhận vì phí kiểm toán là thỏa thuận thương mại","Từ chối, báo thành viên Ban giám đốc phụ trách và ghi nhận nguy cơ đối với tính độc lập","Nhận nhưng ghi đoạn nhấn mạnh","Chuyển hồ sơ cho đồng nghiệp ký"],en:["Accept since fees are commercial terms","Refuse, inform the engagement partner and document the independence threat","Accept but add an emphasis of matter","Hand the file to a colleague to sign"]},answer:1,explain:{vi:"Phí gắn với kết quả ý kiến là nguy cơ tư lợi nghiêm trọng; phải từ chối, báo cáo và áp dụng biện pháp bảo vệ.",en:"A fee tied to the opinion is a serious self-interest threat; refuse, report and apply safeguards."}}],tools_en:["Electronic audit working paper software","Computer-assisted audit tools (CAAT)","Microsoft Excel","Electronic audit confirmation platform","Firm audit program templates"]}},"KK-142":{scenario:{company:"Riverstone Distribution",supervisor:{name:"Bùi Thị Mai Phương",role:{vi:"Trưởng Kiểm toán nội bộ",en:"Chief Audit Executive"}},ref_code:"IA-2609",title:{vi:"Tách đơn không qua được dữ liệu.",en:"Split orders cannot hide from data."},brief:{vi:"Bạn kiểm thử tuân thủ ma trận phân quyền mua sắm quý 3/2026 (IA-2609). Hạn mức duyệt: đến 200 triệu đồng là Trưởng phòng Mua hàng (PROC-HEAD); trên 200 triệu đến 1 tỷ đồng là Giám đốc Tài chính (CFO); trên 1 tỷ đồng là Tổng giám đốc (CEO). Các PO sau cùng hạng mục, đều do PROC-HEAD duyệt: V1 có 4 PO 190, 185, 195, 180 triệu đồng trong 5 ngày; V2 có 2 PO 120 và 95 triệu đồng cách 3 ngày; V3 có 2 PO 150 và 140 triệu đồng cách 9 ngày. Sửa cấp duyệt đúng của nhóm V1 và tổng giá trị ngoại lệ.",en:"You are testing the purchasing delegation of authority for Q3 2026 (IA-2609). Limits: up to VND 200 million by the Procurement Head (PROC-HEAD); above 200 million to 1 billion by the CFO; above 1 billion by the CEO. These POs share one category and were all approved by PROC-HEAD: V1 has 4 POs of 190, 185, 195 and 180 million within 5 days; V2 has 2 POs of 120 and 95 million 3 days apart; V3 has 2 POs of 150 and 140 million 9 days apart. Correct the V1 approver and the total exception value."},reference_title:{vi:"Ma trận phân quyền & trích xuất PO đã duyệt · IA-2609",en:"Approved delegation matrix & PO extract · IA-2609"},fields:[{id:"V1_APPROVER",label:{vi:"Cấp duyệt đúng cho nhóm PO của V1",en:"Correct approver for the V1 PO group"},initial:"PROC-HEAD",expected:"CFO",choices:["PROC-HEAD","CFO","CEO"],reference:"Ma trận phân quyền (DOA)",hint:{vi:"Cộng gộp các PO cùng nhà cung cấp, cùng hạng mục trong cửa sổ quy định rồi mới đối chiếu với hạn mức.",en:"Aggregate POs with the same supplier and category within the set window before checking limits."}},{id:"EXC_VALUE",label:{vi:"Tổng giá trị PO ngoại lệ (VND)",en:"Total exception PO value (VND)"},initial:"1255000000",expected:"965000000",reference:"Trích xuất PO quý 3/2026",ref_value:{vi:"V1: 190+185+195+180 triệu trong 5 ngày; V2: 120+95 triệu cách 3 ngày; V3: 150+140 triệu cách 9 ngày",en:"V1: 190+185+195+180 million in 5 days; V2: 120+95 million 3 days apart; V3: 150+140 million 9 days apart"},hint:{vi:"Chỉ PO trong cùng cửa sổ 7 ngày mới cộng gộp; nhóm hoặc PO không vượt hạn mức của người duyệt thì không phải ngoại lệ.",en:"Only POs within the same 7-day window are aggregated; groups or POs within the approver's limit are not exceptions."}}],sop32:{vi:"PO cùng nhà cung cấp, cùng hạng mục, phát sinh trong 7 ngày được cộng gộp để xác định cấp duyệt; giá trị ngoại lệ = tổng giá trị các nhóm gộp vượt hạn mức của người đã duyệt.",en:"POs with the same supplier and category raised within 7 days are aggregated to set the approval level; exception value = total value of aggregated groups above the actual approver's limit."},context:{label:"PHÂN TÍCH DỮ LIỆU / IA-2609",metrics:[{label:{vi:"Hạn mức PROC-HEAD",en:"PROC-HEAD limit"},value:"200,000,000 VND"},{label:{vi:"Cửa sổ cộng gộp (ngày)",en:"Aggregation window (days)"},value:"7"},{label:{vi:"Số PO cần kiểm tra",en:"POs to test"},value:"8"}]},crisis:{vi:"Giám đốc Mua hàng gặp riêng bạn: “Tách PO là để kịp hàng mùa Tết, tôi đã báo miệng Tổng giám đốc rồi. Bỏ phát hiện này khỏi báo cáo đi, tôi sẽ đề cử bạn vào vị trí quản lý mua hàng đang tuyển.”",en:"The Purchasing Director meets you privately: “We split the POs to get Tet stock in time, and I told the CEO verbally. Drop this finding from the report and I will nominate you for the open purchasing manager role.”"},options:{safe:{vi:"Giữ nguyên phát hiện có bằng chứng, đưa giải trình của quản lý vào báo cáo, báo Trưởng KTNB và Ủy ban Kiểm toán về áp lực; đề xuất kiểm soát hệ thống chặn tách PO.",en:"Keep the evidenced finding, include management's response in the report, tell the CAE and the Audit Committee about the pressure, and propose a system control to block split POs."},shortcut:{vi:"Bỏ phát hiện khỏi báo cáo vì đã có báo miệng và nhận lời đề cử.",en:"Drop the finding since the CEO was told verbally and accept the nomination."},wait:{vi:"Tạm gác phát hiện sang đợt kiểm toán năm sau để tránh căng thẳng.",en:"Park the finding until next year's audit to avoid tension."}},questions:{vi:["Vì sao nhóm PO của V1 phải do CFO duyệt và vì sao V3 không bị tính là ngoại lệ? Trình bày cách bạn tính tổng giá trị ngoại lệ.","Lời đề nghị đề cử vị trí đe dọa tính độc lập, khách quan thế nào và bạn báo cáo cho ai theo điều lệ kiểm toán nội bộ?"],en:["Why must the V1 PO group be approved by the CFO and why is V3 not an exception? Show how you computed the total exception value.","How does the job nomination offer threaten independence and objectivity, and to whom do you report under the internal audit charter?"]},hints:{vi:["Sắp xếp PO theo nhà cung cấp và ngày tạo, đánh dấu các PO nằm trong cùng cửa sổ 7 ngày.","Cộng giá trị từng nhóm gộp rồi so với hạn mức của PROC-HEAD theo SOP mục 3.2.","Đọc lại SOP mục 4.2: phát hiện có bằng chứng không được gỡ bỏ theo đề nghị của bên bị kiểm toán."],en:["Sort POs by supplier and creation date and mark those within the same 7-day window.","Sum each aggregated group and compare with the PROC-HEAD limit in SOP 3.2.","Re-read SOP 4.2: evidenced findings are never removed at the auditee's request."]}},learning:{summary:{vi:"Kiểm toán viên nội bộ đánh giá độc lập, khách quan về quản trị, quản lý rủi ro và kiểm soát nội bộ của tổ chức: lập kế hoạch kiểm toán dựa trên rủi ro, kiểm thử thiết kế và vận hành kiểm soát, phân tích dữ liệu toàn bộ giao dịch, đưa ra phát hiện và khuyến nghị, theo dõi khắc phục. Giá trị tạo ra là ngăn ngừa thất thoát, gian lận và giúp ban lãnh đạo ra quyết định an toàn. Nghề đòi hỏi tư duy rủi ro, kỹ năng dữ liệu và tính độc lập cao.",en:"An internal auditor provides independent, objective assurance on governance, risk management and internal control: planning risk-based audits, testing control design and operation, analyzing full transaction data, raising findings and recommendations and tracking remediation. The value is preventing losses and fraud and helping management decide safely. The role requires risk thinking, data skills and strong independence."},responsibilities:{vi:["Lập kế hoạch kiểm toán nội bộ năm dựa trên đánh giá rủi ro và trình Ủy ban Kiểm toán.","Tìm hiểu quy trình, vẽ lưu đồ và nhận diện điểm kiểm soát then chốt.","Kiểm thử thiết kế và hiệu quả vận hành của kiểm soát bằng mẫu hoặc toàn bộ dữ liệu.","Lập báo cáo phát hiện, xếp hạng rủi ro, khuyến nghị và ý kiến phản hồi của quản lý.","Theo dõi việc khắc phục và báo cáo định kỳ cho Hội đồng quản trị, Ủy ban Kiểm toán."],en:["Build the annual risk-based internal audit plan and submit it to the Audit Committee.","Walk through processes, draw flowcharts and identify key controls.","Test control design and operating effectiveness using samples or full data.","Report findings with risk ratings, recommendations and management responses.","Track remediation and report regularly to the Board and Audit Committee."]},competencies:[{name:{vi:"Kiểm toán dựa trên rủi ro",en:"Risk-based auditing"},desc:{vi:"Xếp hạng rủi ro theo tác động và khả năng xảy ra, tập trung nguồn lực vào vùng trọng yếu.",en:"Rank risks by impact and likelihood and focus resources on key areas."}},{name:{vi:"Đánh giá kiểm soát",en:"Control evaluation"},desc:{vi:"Phân biệt khiếm khuyết thiết kế với khiếm khuyết vận hành và đề xuất kiểm soát bù đắp.",en:"Separate design from operating deficiencies and propose compensating controls."}},{name:{vi:"Phân tích dữ liệu kiểm toán",en:"Audit analytics"},desc:{vi:"Dùng SQL, công cụ phân tích để phát hiện tách đơn, trùng thanh toán, bất thường.",en:"Use SQL and analytics tools to detect split orders, duplicate payments and anomalies."}},{name:{vi:"Viết báo cáo & thuyết phục",en:"Reporting & influence"},desc:{vi:"Trình bày phát hiện theo cấu trúc tiêu chí, thực trạng, nguyên nhân, ảnh hưởng, khuyến nghị.",en:"Present findings as criteria, condition, cause, effect and recommendation."}},{name:{vi:"Độc lập & khách quan",en:"Independence & objectivity"},desc:{vi:"Từ chối lợi ích, báo cáo áp lực và giữ đường báo cáo trực tiếp lên Ủy ban Kiểm toán.",en:"Decline benefits, report pressure and keep a direct line to the Audit Committee."}}],knowledge:{vi:["Nghị định 05/2019/NĐ-CP về kiểm toán nội bộ: đối tượng áp dụng, nguyên tắc độc lập và quy chế kiểm toán nội bộ.","Chuẩn mực Kiểm toán nội bộ toàn cầu của IIA (Global Internal Audit Standards, ban hành 2024).","Khung kiểm soát nội bộ COSO 2013 với 5 thành phần và 17 nguyên tắc.","Mô hình Ba tuyến của IIA (2020) về vai trò quản lý, quản trị rủi ro và kiểm toán nội bộ.","Quản trị rủi ro doanh nghiệp theo COSO ERM 2017 và ISO 31000:2018."],en:["Decree 05/2019/ND-CP on internal audit: scope, independence principles and the internal audit charter.","The IIA Global Internal Audit Standards (issued 2024).","The COSO 2013 internal control framework with 5 components and 17 principles.","The IIA Three Lines Model (2020) on management, risk and internal audit roles.","Enterprise risk management under COSO ERM 2017 and ISO 31000:2018."]},tools:["SQL / Python phân tích dữ liệu","Phần mềm quản lý kiểm toán và giấy làm việc","Công cụ phân tích dữ liệu kiểm toán (CAAT)","Microsoft Excel","Bảng điều khiển theo dõi khắc phục phát hiện"],kpis:{vi:["Tỷ lệ hoàn thành kế hoạch kiểm toán năm đã phê duyệt.","Tỷ lệ khuyến nghị được khắc phục đúng hạn.","Mức độ hài lòng của Ủy ban Kiểm toán và đơn vị được kiểm toán.","Tỷ lệ cuộc kiểm toán có sử dụng phân tích toàn bộ dữ liệu."],en:["Completion of the approved annual audit plan.","Share of recommendations remediated on time.","Satisfaction of the Audit Committee and auditees.","Share of audits using full-population data analytics."]},day:[{time:"08:30",vi:"Rà soát danh sách khuyến nghị quá hạn và nhắc các đơn vị cập nhật tiến độ.",en:"Review overdue recommendations and remind units to update progress."},{time:"10:00",vi:"Chạy truy vấn phát hiện PO tách đơn và thanh toán trùng trên dữ liệu ERP.",en:"Run queries for split POs and duplicate payments on ERP data."},{time:"13:30",vi:"Phỏng vấn trưởng phòng mua hàng và kiểm tra hồ sơ phê duyệt của mẫu chọn.",en:"Interview the procurement head and inspect approval files for selected samples."},{time:"15:30",vi:"Viết phát hiện theo cấu trúc tiêu chí, thực trạng, nguyên nhân, ảnh hưởng, khuyến nghị.",en:"Write findings as criteria, condition, cause, effect and recommendation."},{time:"17:00",vi:"Họp kết thúc với đơn vị được kiểm toán để thống nhất kế hoạch khắc phục.",en:"Hold the closing meeting with the auditee to agree remediation plans."}],mistakes:{vi:["Kiểm tra từng PO riêng lẻ mà không cộng gộp, bỏ sót hành vi tách đơn né hạn mức.","Chỉ kiểm tra thiết kế kiểm soát trên giấy mà không kiểm thử vận hành thực tế.","Gỡ hoặc làm nhẹ phát hiện theo đề nghị của bên bị kiểm toán, mất tính độc lập."],en:["Testing POs one by one without aggregation, missing split orders that dodge limits.","Checking control design on paper without testing real operation.","Removing or softening findings at the auditee's request, losing independence."]},career:[{vi:"Chuyên viên kiểm toán nội bộ",en:"Internal audit associate"},{vi:"Kiểm toán viên nội bộ chính",en:"Senior internal auditor"},{vi:"Quản lý kiểm toán nội bộ",en:"Internal audit manager"},{vi:"Trưởng Kiểm toán nội bộ (CAE)",en:"Chief Audit Executive (CAE)"}],glossary:[{term:"DOA",vi:"Ma trận phân quyền: quy định ai được phê duyệt loại giao dịch nào, đến hạn mức bao nhiêu.",en:"Delegation of authority: who may approve which transactions and up to what limit."},{term:"Split purchase",vi:"Tách đơn mua: chia một nhu cầu thành nhiều PO nhỏ để né hạn mức phê duyệt hoặc đấu thầu.",en:"Splitting one need into several small POs to dodge approval or tender limits."},{term:"Operating deficiency",vi:"Khiếm khuyết vận hành: kiểm soát được thiết kế đúng nhưng không được thực hiện như quy định.",en:"A well-designed control that is not performed as intended."},{term:"Three Lines Model",vi:"Mô hình Ba tuyến: quản lý vận hành, chức năng rủi ro tuân thủ và kiểm toán nội bộ độc lập.",en:"Operational management, risk and compliance functions, and independent internal audit."},{term:"Management response",vi:"Ý kiến phản hồi của quản lý về phát hiện, gồm hành động khắc phục, người phụ trách và thời hạn.",en:"Management's reply to a finding with actions, owner and deadline."}],quiz:[{q:{vi:"Kiểm thử 60 mẫu phát hiện 3 ngoại lệ; tỷ lệ sai lệch chấp nhận được là 4%. Kết luận nào đúng?",en:"Testing 60 samples finds 3 exceptions; the tolerable deviation rate is 4%. Which conclusion is right?"},options:{vi:["Tỷ lệ 3%, kiểm soát hữu hiệu","Tỷ lệ 4%, vừa đạt ngưỡng","Tỷ lệ 5%, vượt ngưỡng nên kiểm soát không hữu hiệu","Không kết luận được vì mẫu nhỏ"],en:["Rate 3%, control effective","Rate 4%, just at the limit","Rate 5%, above the limit so the control is not effective","No conclusion because the sample is small"]},answer:2,explain:{vi:"3 / 60 = 5%, cao hơn 4% chấp nhận được nên kết luận kiểm soát vận hành không hữu hiệu.",en:"3 / 60 = 5%, above the 4% tolerable rate, so the control is not operating effectively."}},{q:{vi:"Theo Mô hình Ba tuyến của IIA, kiểm toán nội bộ giữ vai trò nào?",en:"In the IIA Three Lines Model, what role does internal audit play?"},options:{vi:["Cung cấp đảm bảo độc lập, khách quan cho cơ quan quản trị","Trực tiếp vận hành kiểm soát hằng ngày","Thay ban điều hành ra quyết định rủi ro","Phê duyệt giao dịch mua sắm lớn"],en:["Provide independent, objective assurance to the governing body","Run daily controls directly","Make risk decisions instead of management","Approve large purchases"]},answer:0,explain:{vi:"Kiểm toán nội bộ độc lập với quản lý, báo cáo cho cơ quan quản trị và không làm thay chức năng vận hành.",en:"Internal audit is independent of management, reports to the governing body and does not perform operational roles."}},{q:{vi:"Thành phần nào KHÔNG thuộc 5 thành phần của khung kiểm soát nội bộ COSO 2013?",en:"Which is NOT one of the five components of the COSO 2013 framework?"},options:{vi:["Môi trường kiểm soát","Đánh giá rủi ro","Thông tin và truyền thông","Kiểm toán độc lập"],en:["Control environment","Risk assessment","Information and communication","External audit"]},answer:3,explain:{vi:"Năm thành phần là môi trường kiểm soát, đánh giá rủi ro, hoạt động kiểm soát, thông tin và truyền thông, giám sát.",en:"The five are control environment, risk assessment, control activities, information and communication, and monitoring."}},{q:{vi:"Người bị kiểm toán đề nghị đề cử bạn vào vị trí mới nếu bỏ một phát hiện. Bạn làm gì?",en:"An auditee offers to nominate you for a new role if you drop a finding. What do you do?"},options:{vi:["Nhận lời vì phát hiện không quá lớn","Từ chối, giữ phát hiện và báo Trưởng KTNB, Ủy ban Kiểm toán về áp lực","Làm nhẹ mức xếp hạng rủi ro","Chuyển phát hiện sang năm sau"],en:["Accept since the finding is small","Refuse, keep the finding and report the pressure to the CAE and Audit Committee","Lower the risk rating","Move the finding to next year"]},answer:1,explain:{vi:"Lợi ích cá nhân đổi lấy việc bỏ phát hiện đe dọa nghiêm trọng tính độc lập; phải từ chối và báo cáo.",en:"Personal benefits for dropping findings seriously threaten independence; refuse and report."}}],tools_en:["SQL / Python for data analytics","Audit management and workpaper software","Computer-assisted audit tools (CAAT)","Microsoft Excel","Audit finding remediation dashboard"]}},"KK-143":{scenario:{company:"Cloudberry Consumer Goods",supervisor:{name:"Ngô Gia Bảo",role:{vi:"Trưởng nhóm Kế hoạch & Phân tích Tài chính",en:"FP&A Manager"}},ref_code:"BV-2609",title:{vi:"So đúng thước đo trước khi kết luận.",en:"Use the right yardstick before concluding."},brief:{vi:"Bạn soát báo cáo chênh lệch ngân sách quý 3/2026 (BV-2609) gửi Ban điều hành. Ngân sách tĩnh: 40.000 đơn hàng, chi phí giao hàng 2.000 triệu đồng. Hợp đồng logistics tính theo đơn giá cho từng đơn hàng giao, không có phí thuê bao hằng tháng. Thực tế: 46.000 đơn hàng, chi phí giao hàng 2.185 triệu đồng. Bản nháp so thực tế với ngân sách tĩnh và kết luận vượt chi 185 triệu đồng. Sửa phân loại hành vi chi phí và ngân sách linh hoạt, rồi viết bình luận có căn cứ.",en:"You are reviewing the Q3 2026 budget variance report (BV-2609) for the executive team. Static budget: 40,000 orders and delivery cost of VND 2,000 million. The logistics contract charges a unit rate per delivered order with no monthly subscription fee. Actual: 46,000 orders and delivery cost of VND 2,185 million. The draft compares actuals with the static budget and reports a VND 185 million overspend. Correct the cost behavior and the flexed budget, then write an evidence-based commentary."},reference_title:{vi:"Hợp đồng logistics & mô hình động lực đã duyệt · BV-2609",en:"Logistics contract & approved driver model · BV-2609"},fields:[{id:"COST_BEHAV",label:{vi:"Hành vi của chi phí giao hàng",en:"Delivery cost behavior"},initial:"FIXED",expected:"VARIABLE",choices:["FIXED","VARIABLE","STEP-FIXED"],reference:"Hợp đồng logistics - điều khoản giá",hint:{vi:"Đọc điều khoản giá: tổng chi phí thay đổi tỷ lệ thuận với số đơn hàng hay giữ nguyên khi sản lượng thay đổi?",en:"Read the pricing clause: does total cost move in proportion to orders or stay flat when volume changes?"}},{id:"FLEX_BUDGET",label:{vi:"Ngân sách linh hoạt chi phí giao hàng (VND)",en:"Flexed delivery cost budget (VND)"},initial:"2000000000",expected:"2300000000",reference:"Mô hình động lực chi phí giao hàng",ref_value:{vi:"Ngân sách 2.000 triệu đồng cho 40.000 đơn; thực tế 46.000 đơn; chi phí thực tế 2.185 triệu đồng",en:"Budget VND 2,000 million for 40,000 orders; actual 46,000 orders; actual cost VND 2,185 million"},hint:{vi:"Ngân sách linh hoạt dùng đơn giá ngân sách nhân với sản lượng thực tế, không dùng tổng ngân sách tĩnh.",en:"A flexed budget applies the budgeted unit rate to actual volume, not the static total."}}],sop32:{vi:"Ngân sách linh hoạt = đơn giá ngân sách (chi phí ngân sách / sản lượng ngân sách) x sản lượng thực tế; chênh lệch chi tiêu = thực tế - ngân sách linh hoạt (số âm là thuận lợi).",en:"Flexed budget = budgeted unit rate (budget cost / budget volume) x actual volume; spending variance = actual - flexed budget (negative is favorable)."},context:{label:"BÁO CÁO CHÊNH LỆCH NHÁP / BV-2609",metrics:[{label:{vi:"Đơn hàng ngân sách",en:"Budgeted orders"},value:"40,000"},{label:{vi:"Đơn hàng thực tế",en:"Actual orders"},value:"46,000"},{label:{vi:"Chi phí giao hàng thực tế",en:"Actual delivery cost"},value:"2,185,000,000 VND"}]},crisis:{vi:"Giám đốc Kinh doanh nhắn: “Nâng dự báo doanh thu quý 4 thêm 15% trong bản gửi ngân hàng để giữ cam kết tỷ lệ nợ trên EBITDA. Chưa có đơn hàng thì tính sau. CFO đang đi công tác, cứ gửi trước đi.”",en:"The Sales Director messages you: “Raise the Q4 revenue forecast by 15% in the bank pack so we keep the debt to EBITDA covenant. No orders yet, we will sort it later. The CFO is travelling, just send it.”"},options:{safe:{vi:"Không đưa số liệu thiếu cơ sở; giữ kịch bản cơ sở có bằng chứng, lập thêm kịch bản tăng và giảm ghi rõ giả định, báo CFO và chỉ gửi ngân hàng bản đã được phê duyệt.",en:"Use no unsupported figures; keep an evidenced base case, add upside and downside scenarios with clear assumptions, inform the CFO and send the bank only the approved version."},shortcut:{vi:"Nâng dự báo 15% theo yêu cầu và gửi ngân hàng ngay, giải thích với CFO sau.",en:"Raise the forecast by 15% as asked and send it to the bank now, explain to the CFO later."},wait:{vi:"Không gửi gì, chờ CFO về rồi tính dù hạn nộp hồ sơ ngân hàng đã đến.",en:"Send nothing and wait for the CFO even though the bank deadline has arrived."}},questions:{vi:["Vì sao chi phí giao hàng là VARIABLE và kết luận vượt chi 185 triệu đồng là sai? Trình bày ngân sách linh hoạt và chênh lệch chi tiêu bạn tính lại.","Bạn xử lý yêu cầu nâng dự báo gửi ngân hàng thế nào để vừa giữ quan hệ tín dụng vừa không làm sai lệch thông tin?"],en:["Why is delivery cost VARIABLE and why is the VND 185 million overspend conclusion wrong? Show the flexed budget and spending variance you recalculated.","How do you handle the request to inflate the bank forecast while protecting the credit relationship and the integrity of information?"]},hints:{vi:["Đặt báo cáo chênh lệch nháp cạnh hợp đồng logistics và gạch chân cơ sở tính phí.","Tính đơn giá ngân sách cho mỗi đơn hàng trước rồi áp sản lượng thực tế theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dự báo gửi bên ngoài phải có giả định kiểm chứng được và được CFO phê duyệt."],en:["Place the draft variance report next to the logistics contract and underline the pricing basis.","Compute the budgeted rate per order first, then apply actual volume in SOP 3.2.","Re-read SOP 4.2: external forecasts need verifiable assumptions and CFO approval."]}},learning:{summary:{vi:"Chuyên viên kế hoạch và phân tích tài chính (FP&A) xây dựng ngân sách, dự báo cuốn chiếu, mô hình tài chính và phân tích chênh lệch giữa thực tế với kế hoạch để giải thích nguyên nhân, đề xuất hành động cho ban điều hành. Giá trị tạo ra là quyết định dựa trên số liệu về giá bán, chi phí, đầu tư và dòng tiền. Nghề đòi hỏi tư duy kinh doanh, kỹ năng mô hình hóa trên bảng tính, hiểu báo cáo tài chính và trung thực với giả định.",en:"An FP&A analyst builds budgets, rolling forecasts and financial models and analyzes actual versus plan variances to explain causes and propose actions to executives. The value is data-driven decisions on pricing, cost, investment and cash flow. The role requires business sense, spreadsheet modeling skills, understanding of financial statements and honesty about assumptions."},responsibilities:{vi:["Điều phối lập ngân sách năm theo động lực kinh doanh cùng các phòng ban.","Cập nhật dự báo cuốn chiếu hằng tháng hoặc hằng quý và kịch bản độ nhạy.","Phân tích chênh lệch giá, lượng, cơ cấu và chi tiêu, viết bình luận cho ban điều hành.","Xây dựng mô hình đánh giá dự án đầu tư bằng NPV, IRR, thời gian hoàn vốn.","Theo dõi KPI tài chính, vốn lưu động và các chỉ tiêu cam kết với ngân hàng."],en:["Coordinate the driver-based annual budget with business units.","Update monthly or quarterly rolling forecasts and sensitivity scenarios.","Analyze price, volume, mix and spending variances and write executive commentary.","Build investment appraisal models using NPV, IRR and payback.","Track financial KPIs, working capital and bank covenants."]},competencies:[{name:{vi:"Mô hình tài chính",en:"Financial modeling"},desc:{vi:"Xây mô hình ba báo cáo liên kết, tách giả định, có kiểm tra lỗi và dễ kiểm toán.",en:"Build linked three-statement models with separate assumptions, error checks and audit trails."}},{name:{vi:"Phân tích chênh lệch",en:"Variance analysis"},desc:{vi:"Dùng ngân sách linh hoạt và phân tích giá, lượng, cơ cấu để tìm nguyên nhân thật.",en:"Use flexed budgets and price, volume and mix analysis to find real causes."}},{name:{vi:"Hiểu kinh doanh",en:"Business partnering"},desc:{vi:"Nắm động lực doanh thu, chi phí của từng mảng và đối thoại với quản lý kinh doanh.",en:"Understand revenue and cost drivers of each unit and engage business managers."}},{name:{vi:"Trực quan hóa & kể chuyện số liệu",en:"Data storytelling"},desc:{vi:"Trình bày ngắn gọn điều gì đã xảy ra, vì sao và cần làm gì bằng biểu đồ rõ ràng.",en:"Show what happened, why and what to do with clear charts and concise text."}},{name:{vi:"Liêm chính trong dự báo",en:"Forecast integrity"},desc:{vi:"Không thổi phồng hay làm nhẹ số liệu; tách rõ kịch bản cơ sở và kịch bản mục tiêu.",en:"Never inflate or soften numbers; separate base case from target scenarios."}}],knowledge:{vi:["Các loại ngân sách: tĩnh, linh hoạt, từ số không (zero-based) và dự báo cuốn chiếu.","Phân tích chênh lệch giá - lượng - cơ cấu, chênh lệch chi tiêu và hiệu suất.","Hành vi chi phí: biến đổi, cố định, bán biến đổi, cố định theo bậc; điểm hòa vốn.","Đánh giá dự án bằng NPV, IRR, thời gian hoàn vốn và chi phí vốn bình quân (WACC).","Vốn lưu động (DSO, DIO, DPO) và các chỉ tiêu cam kết vay như nợ trên EBITDA, khả năng trả lãi."],en:["Budget types: static, flexible, zero-based and rolling forecasts.","Price - volume - mix variance, spending and efficiency variances.","Cost behavior: variable, fixed, semi-variable and step-fixed; break-even.","Project appraisal with NPV, IRR, payback and weighted average cost of capital (WACC).","Working capital (DSO, DIO, DPO) and loan covenants such as debt to EBITDA and interest cover."]},tools:["Microsoft Excel (mô hình tài chính)","Phần mềm lập kế hoạch & ngân sách (EPM)","Công cụ BI và bảng điều khiển","Phần mềm kế toán (ERP)","SQL truy vấn dữ liệu"],kpis:{vi:["Sai số dự báo doanh thu và EBITDA so với thực tế.","Thời gian phát hành báo cáo quản trị sau ngày khóa sổ.","Tỷ lệ chênh lệch lớn có giải thích nguyên nhân và hành động cụ thể.","Mức độ hài lòng của ban điều hành với chất lượng phân tích."],en:["Revenue and EBITDA forecast error versus actuals.","Time to publish management reports after the close.","Share of large variances explained with causes and actions.","Executive satisfaction with analysis quality."]},day:[{time:"08:30",vi:"Tải số liệu thực tế từ ERP, kiểm tra khớp với sổ cái sau khóa sổ.",en:"Pull actuals from the ERP and check they tie to the ledger after close."},{time:"10:00",vi:"Phân tích chênh lệch chi phí giao hàng và doanh thu theo kênh bằng ngân sách linh hoạt.",en:"Analyze delivery cost and channel revenue variances with flexed budgets."},{time:"13:30",vi:"Làm việc với trưởng ngành hàng để cập nhật giả định dự báo quý tới.",en:"Work with category heads to update next quarter's forecast assumptions."},{time:"15:30",vi:"Chạy kịch bản độ nhạy giá nguyên liệu và tỷ giá trong mô hình tài chính.",en:"Run raw material price and FX sensitivities in the financial model."},{time:"17:00",vi:"Viết bình luận chênh lệch và gửi bộ báo cáo cho CFO duyệt.",en:"Write variance commentary and send the pack to the CFO for approval."}],mistakes:{vi:["So chi phí biến đổi thực tế với ngân sách tĩnh, kết luận sai về hiệu quả chi tiêu.","Để công thức và giả định lẫn lộn, mô hình không kiểm tra lỗi và khó kiểm chứng.","Điều chỉnh dự báo theo mong muốn của bộ phận kinh doanh thay vì theo bằng chứng."],en:["Comparing actual variable costs with the static budget and misjudging spending.","Mixing formulas and assumptions in models with no error checks.","Bending forecasts to Sales' wishes instead of the evidence."]},career:[{vi:"Chuyên viên phân tích tài chính",en:"Financial analyst"},{vi:"Chuyên viên FP&A cấp cao",en:"Senior FP&A analyst"},{vi:"Quản lý FP&A",en:"FP&A manager"},{vi:"Giám đốc tài chính (CFO)",en:"Chief Financial Officer (CFO)"}],glossary:[{term:"Flexed budget",vi:"Ngân sách linh hoạt: ngân sách được điều chỉnh theo sản lượng thực tế để so sánh công bằng.",en:"A budget restated at actual volume for a fair comparison."},{term:"Rolling forecast",vi:"Dự báo cuốn chiếu: cập nhật định kỳ, luôn nhìn trước một số kỳ cố định, ví dụ 12 tháng tới.",en:"A forecast updated regularly that always looks a fixed number of periods ahead."},{term:"Price-volume-mix",vi:"Phân tích tách chênh lệch doanh thu thành phần do giá bán, sản lượng và cơ cấu sản phẩm.",en:"Splitting revenue variance into price, volume and product mix effects."},{term:"EBITDA",vi:"Lợi nhuận trước lãi vay, thuế và khấu hao, thường dùng đo hiệu quả hoạt động và cam kết vay.",en:"Earnings before interest, tax, depreciation and amortization, used for performance and covenants."},{term:"Driver-based planning",vi:"Lập kế hoạch dựa trên động lực như số đơn hàng, số khách, năng suất thay vì cộng thêm phần trăm.",en:"Planning from drivers such as orders, customers and productivity rather than flat percentages."}],quiz:[{q:{vi:"Ngân sách: 10.000 sản phẩm giá 50.000 đồng. Thực tế: 11.000 sản phẩm giá 48.000 đồng. Chênh lệch giá bán là bao nhiêu?",en:"Budget: 10,000 units at VND 50,000. Actual: 11,000 units at VND 48,000. What is the price variance?"},options:{vi:["50 triệu đồng thuận lợi","28 triệu đồng thuận lợi","20 triệu đồng bất lợi","22 triệu đồng bất lợi"],en:["VND 50 million favorable","VND 28 million favorable","VND 20 million unfavorable","VND 22 million unfavorable"]},answer:3,explain:{vi:"Chênh lệch giá = (48.000 - 50.000) x 11.000 = -22 triệu đồng, bất lợi; chênh lệch lượng là 50 triệu đồng thuận lợi.",en:"Price variance = (48,000 - 50,000) x 11,000 = VND -22 million, unfavorable; volume variance is VND 50 million favorable."}},{q:{vi:"Đặc điểm của dự báo cuốn chiếu (rolling forecast) là gì?",en:"What characterizes a rolling forecast?"},options:{vi:["Lập một lần đầu năm và giữ nguyên","Cập nhật định kỳ và luôn nhìn trước một số kỳ cố định","Chỉ dùng cho báo cáo thuế","Chỉ ghi nhận số liệu thực tế đã xảy ra"],en:["Set once at the start of the year and frozen","Updated regularly, always looking a fixed horizon ahead","Used only for tax reporting","Records only past actuals"]},answer:1,explain:{vi:"Dự báo cuốn chiếu bổ sung kỳ mới khi một kỳ kết thúc, giúp kế hoạch bám sát thực tế.",en:"A rolling forecast adds a new period as one ends, keeping plans close to reality."}},{q:{vi:"Trong lập kế hoạch theo động lực, chi phí giao hàng tính theo đơn giá mỗi đơn nên gắn với động lực nào?",en:"In driver-based planning, delivery cost charged per order should be tied to which driver?"},options:{vi:["Diện tích văn phòng","Số nhân viên kế toán","Số đơn hàng giao","Doanh thu năm trước"],en:["Office floor area","Number of accountants","Number of delivered orders","Last year's revenue"]},answer:2,explain:{vi:"Chi phí phát sinh theo từng đơn giao nên động lực hợp lý nhất là số đơn hàng giao.",en:"The cost arises per delivered order, so the delivered order count is the right driver."}},{q:{vi:"Giám đốc Kinh doanh yêu cầu nâng dự báo gửi ngân hàng mà không có cơ sở. Bạn làm gì?",en:"The Sales Director asks you to raise the bank forecast without support. What do you do?"},options:{vi:["Từ chối số liệu thiếu cơ sở, trình bày kịch bản có giả định rõ và báo CFO trước khi gửi","Nâng theo yêu cầu vì ngân hàng ít kiểm tra","Nâng một nửa cho an toàn","Gửi bản cũ mà không cập nhật"],en:["Refuse unsupported figures, present scenarios with clear assumptions and inform the CFO before sending","Raise it since banks rarely check","Raise it halfway to be safe","Send the old version without updating"]},answer:0,explain:{vi:"Cung cấp dự báo sai lệch cho bên cho vay gây rủi ro pháp lý và uy tín; phải dựa trên giả định kiểm chứng được.",en:"Misleading lenders creates legal and reputational risk; forecasts must rest on verifiable assumptions."}}],tools_en:["Microsoft Excel (financial modeling)","Planning & budgeting software (EPM)","BI tools and dashboards","Accounting software (ERP)","SQL for data queries"]}},"KK-144":{scenario:{company:"Lantern Peak Securities",supervisor:{name:"Đinh Quốc Việt",role:{vi:"Trưởng phòng Phân tích",en:"Head of Equity Research"}},ref_code:"ER-2611",title:{vi:"Từ giá trị doanh nghiệp đến giá trị mỗi cổ phiếu.",en:"From enterprise value to value per share."},brief:{vi:"Bạn soát mô hình định giá ER-2611 cho cổ phiếu Frostline Logistics (dữ liệu mô phỏng). Mô hình chiết khấu dòng tiền tự do của doanh nghiệp (FCFF); sau khi dùng đúng tỷ lệ chiết khấu, giá trị doanh nghiệp (EV) là 12.600 tỷ đồng. Nợ vay 3.100 tỷ đồng, tiền và tương đương tiền 900 tỷ đồng, lợi ích cổ đông không kiểm soát 200 tỷ đồng, 250 triệu cổ phiếu đang lưu hành. Bản nháp chia thẳng EV cho số cổ phiếu. Sửa tỷ lệ chiết khấu và giá trị nội tại mỗi cổ phiếu.",en:"You are reviewing valuation model ER-2611 for Frostline Logistics shares (training data). The model discounts free cash flow to the firm (FCFF); with the correct discount rate, enterprise value (EV) is VND 12,600 billion. Debt is VND 3,100 billion, cash and equivalents VND 900 billion, non-controlling interests VND 200 billion, and 250 million shares are outstanding. The draft divides EV directly by the share count. Correct the discount rate and the intrinsic value per share."},reference_title:{vi:"Hướng dẫn định giá & bảng cân đối đã kiểm toán · ER-2611",en:"Valuation manual & audited balance sheet · ER-2611"},fields:[{id:"DISC_RATE",label:{vi:"Tỷ lệ chiết khấu cho FCFF",en:"Discount rate for FCFF"},initial:"KE",expected:"WACC",choices:["KE","WACC","KD"],reference:"Hướng dẫn định giá nội bộ",hint:{vi:"Dòng tiền thuộc về cả chủ nợ và cổ đông phải chiết khấu bằng chi phí vốn của toàn bộ nguồn tài trợ.",en:"Cash flow belonging to both lenders and shareholders is discounted at the cost of all funding sources."}},{id:"VALUE_PS",label:{vi:"Giá trị nội tại mỗi cổ phiếu (VND)",en:"Intrinsic value per share (VND)"},initial:"50400",expected:"40800",reference:"Cầu nối từ EV đến giá trị vốn chủ",ref_value:{vi:"EV 12.600 tỷ; nợ vay 3.100 tỷ; tiền 900 tỷ; lợi ích CĐ không kiểm soát 200 tỷ; 250 triệu cổ phiếu",en:"EV VND 12,600 bn; debt 3,100 bn; cash 900 bn; non-controlling interests 200 bn; 250 million shares"},hint:{vi:"Từ giá trị doanh nghiệp đi tới giá trị vốn chủ phải xử lý các khoản không thuộc cổ đông công ty mẹ và tiền dư.",en:"Going from EV to equity value requires handling claims outside parent shareholders and surplus cash."}}],sop32:{vi:"Giá trị vốn chủ = EV - nợ vay + tiền và tương đương tiền - lợi ích cổ đông không kiểm soát; giá trị mỗi cổ phiếu = giá trị vốn chủ / số cổ phiếu lưu hành, làm tròn đến đồng.",en:"Equity value = EV - debt + cash and equivalents - non-controlling interests; value per share = equity value / shares outstanding, rounded to the nearest dong."},context:{label:"MÔ HÌNH ĐỊNH GIÁ NHÁP / ER-2611",metrics:[{label:{vi:"Giá trị doanh nghiệp (EV)",en:"Enterprise value (EV)"},value:"12,600 bn VND"},{label:{vi:"Nợ vay ròng",en:"Net debt"},value:"2,200 bn VND"},{label:{vi:"Cổ phiếu lưu hành",en:"Shares outstanding"},value:"250,000,000"}]},crisis:{vi:"Một người quen làm ở phòng tài chính Frostline nhắn riêng: lợi nhuận quý 3 chưa công bố tăng gấp đôi. Trưởng bộ phận môi giới đề nghị bạn nâng khuyến nghị lên MUA và gửi trước cho nhóm khách hàng tổ chức ngay sáng nay.",en:"An acquaintance in Frostline's finance team privately tells you that unpublished Q3 profit doubled. The head of brokerage asks you to upgrade to BUY and send it to institutional clients first this morning."},options:{safe:{vi:"Không sử dụng hay chia sẻ thông tin chưa công bố, báo ngay bộ phận Tuân thủ để xử lý và đưa mã vào danh sách hạn chế; khuyến nghị chỉ dựa trên thông tin công khai và phát hành đồng thời cho mọi khách hàng.",en:"Neither use nor share the unpublished information, report it to Compliance at once so the stock goes on the restricted list; base ratings on public data only and release to all clients at the same time."},shortcut:{vi:"Nâng khuyến nghị lên MUA và gửi trước cho khách hàng tổ chức, ghi lý do là “triển vọng tích cực”.",en:"Upgrade to BUY and send it to institutional clients first, citing a “positive outlook”."},wait:{vi:"Giữ im lặng, không báo ai và tiếp tục làm như chưa nhận được tin nhắn.",en:"Stay silent, tell no one and carry on as if the message never arrived."}},questions:{vi:["Vì sao FCFF phải chiết khấu bằng WACC? Trình bày cầu nối từ EV đến giá trị mỗi cổ phiếu mà bạn đã tính lại.","Thông tin lợi nhuận chưa công bố là loại thông tin gì, sử dụng nó gây rủi ro pháp lý nào và bạn báo cáo cho ai?"],en:["Why must FCFF be discounted at WACC? Show the bridge from EV to value per share that you recalculated.","What kind of information is the unpublished profit, what legal risk comes from using it, and whom do you report to?"]},hints:{vi:["Đặt mô hình nháp cạnh hướng dẫn định giá và kiểm tra dòng tiền nào đang được chiết khấu bằng tỷ lệ nào.","Lập cầu nối từng bước từ EV sang giá trị vốn chủ trước khi chia cho số cổ phiếu ở SOP mục 3.2.","Đọc lại SOP mục 4.2: thông tin trọng yếu chưa công bố phải được báo bộ phận Tuân thủ, không dùng cho khuyến nghị."],en:["Place the draft model next to the valuation manual and check which cash flow uses which rate.","Build the EV to equity bridge step by step before dividing by shares in SOP 3.2.","Re-read SOP 4.2: material nonpublic information goes to Compliance and is never used for ratings."]}},learning:{summary:{vi:"Chuyên viên phân tích đầu tư cổ phiếu nghiên cứu ngành và doanh nghiệp niêm yết, xây dựng mô hình dự phóng tài chính, định giá bằng chiết khấu dòng tiền và so sánh bội số, rồi đưa ra khuyến nghị và giá mục tiêu cho nhà đầu tư. Giá trị tạo ra là thông tin độc lập, có cơ sở giúp thị trường định giá hiệu quả. Nghề đòi hỏi kỹ năng đọc báo cáo tài chính, mô hình hóa, viết báo cáo và tuân thủ nghiêm quy định về thông tin nội bộ, xung đột lợi ích.",en:"An equity research analyst studies industries and listed companies, builds financial forecast models, values shares with discounted cash flow and multiples, and issues ratings and target prices for investors. The value is independent, well-grounded information that helps markets price efficiently. The role requires financial statement analysis, modeling and writing skills, and strict compliance with insider information and conflict of interest rules."},responsibilities:{vi:["Theo dõi ngành, doanh nghiệp được phân công và cập nhật tin tức, kết quả kinh doanh công bố.","Xây dựng và cập nhật mô hình dự phóng doanh thu, lợi nhuận, dòng tiền.","Định giá bằng DCF và bội số so sánh, xác định giá mục tiêu và khuyến nghị.","Viết báo cáo phân tích, trình bày với nhà đầu tư tổ chức và đội môi giới.","Tuân thủ quy định về thông tin nội bộ, danh sách hạn chế và công bố xung đột lợi ích."],en:["Cover assigned sectors and companies and track news and published results.","Build and update forecast models for revenue, profit and cash flow.","Value shares with DCF and peer multiples and set target prices and ratings.","Write research reports and present to institutional investors and the sales team.","Follow insider information rules, the restricted list and conflict disclosures."]},competencies:[{name:{vi:"Phân tích báo cáo tài chính",en:"Financial statement analysis"},desc:{vi:"Chuẩn hóa số liệu, nhận diện khoản bất thường và chất lượng lợi nhuận.",en:"Normalize figures and spot one-offs and earnings quality issues."}},{name:{vi:"Định giá doanh nghiệp",en:"Equity valuation"},desc:{vi:"Áp dụng đúng FCFF với WACC, FCFE với chi phí vốn chủ và bội số P/E, EV/EBITDA.",en:"Apply FCFF with WACC, FCFE with cost of equity and P/E or EV/EBITDA multiples correctly."}},{name:{vi:"Hiểu ngành",en:"Industry insight"},desc:{vi:"Nắm động lực cung cầu, cạnh tranh, chính sách và chu kỳ của ngành theo dõi.",en:"Understand supply, demand, competition, policy and cycles of the covered sector."}},{name:{vi:"Viết & thuyết trình",en:"Writing & presenting"},desc:{vi:"Trình bày luận điểm đầu tư, rủi ro và giả định rõ ràng, ngắn gọn.",en:"Present the investment thesis, risks and assumptions clearly and briefly."}},{name:{vi:"Đạo đức & tuân thủ",en:"Ethics & compliance"},desc:{vi:"Không dùng thông tin trọng yếu chưa công bố, công bố xung đột lợi ích và giữ độc lập.",en:"Never use material nonpublic information, disclose conflicts and stay independent."}}],knowledge:{vi:["Luật Chứng khoán số 54/2019/QH14 và Nghị định 155/2020/NĐ-CP: cấm giao dịch nội gián, thao túng thị trường.","Thông tư 96/2020/TT-BTC hướng dẫn công bố thông tin trên thị trường chứng khoán.","Bộ Quy tắc đạo đức và Chuẩn mực hành nghề của CFA Institute về thông tin trọng yếu chưa công bố và cơ sở hợp lý của khuyến nghị.","Định giá DCF: FCFF chiết khấu bằng WACC, FCFE chiết khấu bằng chi phí vốn chủ theo CAPM, giá trị cuối kỳ.","Định giá so sánh P/E, P/B, EV/EBITDA và chuẩn hóa số liệu theo VAS, IFRS."],en:["Securities Law No. 54/2019/QH14 and Decree 155/2020/ND-CP: bans on insider trading and market manipulation.","Circular 96/2020/TT-BTC on information disclosure in the securities market.","The CFA Institute Code of Ethics and Standards on material nonpublic information and reasonable basis.","DCF valuation: FCFF at WACC, FCFE at the CAPM cost of equity, and terminal value.","Relative valuation with P/E, P/B and EV/EBITDA and normalizing data under VAS and IFRS."]},tools:["Microsoft Excel (mô hình định giá)","Hệ thống dữ liệu thị trường tài chính","Cổng công bố thông tin của sở giao dịch","Công cụ BI và trực quan hóa","Phần mềm soạn và phát hành báo cáo phân tích"],kpis:{vi:["Độ chính xác dự phóng lợi nhuận so với kết quả công bố.","Hiệu quả khuyến nghị so với chỉ số tham chiếu trong 12 tháng.","Số báo cáo phát hành đúng hạn sau khi doanh nghiệp công bố kết quả.","Xếp hạng đánh giá của khách hàng tổ chức."],en:["Earnings forecast accuracy versus reported results.","Rating performance against the benchmark over 12 months.","Reports published on time after results releases.","Institutional client rankings."]},day:[{time:"07:30",vi:"Đọc tin tức, công bố thông tin qua đêm và cập nhật nhanh cho đội môi giới.",en:"Read overnight news and disclosures and brief the sales team."},{time:"09:30",vi:"Cập nhật mô hình sau kết quả kinh doanh mới công bố của doanh nghiệp theo dõi.",en:"Update the model after a covered company's newly published results."},{time:"13:30",vi:"Tham gia buổi gặp nhà đầu tư do doanh nghiệp tổ chức, chỉ ghi nhận thông tin công khai.",en:"Join the company's investor meeting and record public information only."},{time:"15:30",vi:"Viết báo cáo cập nhật, rà soát giả định định giá với trưởng phòng.",en:"Write an update report and review valuation assumptions with the head of research."},{time:"17:00",vi:"Gửi báo cáo qua bộ phận Tuân thủ duyệt trước khi phát hành đồng thời cho khách hàng.",en:"Send the report through Compliance before simultaneous release to clients."}],mistakes:{vi:["Chiết khấu FCFF bằng chi phí vốn chủ hoặc FCFE bằng WACC, làm sai lệch giá trị.","Chia EV cho số cổ phiếu mà quên trừ nợ, cộng tiền và trừ lợi ích cổ đông không kiểm soát.","Dùng tin đồn hoặc thông tin nội bộ chưa công bố để thay đổi khuyến nghị."],en:["Discounting FCFF at the cost of equity or FCFE at WACC, distorting value.","Dividing EV by shares without subtracting debt, adding cash and removing non-controlling interests.","Changing ratings based on rumors or unpublished inside information."]},career:[{vi:"Trợ lý phân tích",en:"Research associate"},{vi:"Chuyên viên phân tích cổ phiếu",en:"Equity research analyst"},{vi:"Chuyên viên phân tích cấp cao / Trưởng nhóm ngành",en:"Senior analyst / Sector head"},{vi:"Giám đốc phân tích",en:"Director of research"}],glossary:[{term:"FCFF",vi:"Dòng tiền tự do của doanh nghiệp, dành cho cả chủ nợ và cổ đông sau đầu tư và vốn lưu động.",en:"Free cash flow to the firm, available to lenders and shareholders after capex and working capital."},{term:"WACC",vi:"Chi phí vốn bình quân gia quyền của vốn chủ và nợ vay sau thuế theo tỷ trọng thị trường.",en:"Weighted average cost of equity and after-tax debt at market weights."},{term:"Enterprise value",vi:"Giá trị doanh nghiệp: giá trị hoạt động kinh doanh cốt lõi thuộc về mọi nhà cung cấp vốn.",en:"The value of core operations belonging to all capital providers."},{term:"MNPI",vi:"Thông tin trọng yếu chưa công bố, có thể ảnh hưởng đến giá chứng khoán, bị cấm sử dụng để giao dịch.",en:"Material nonpublic information that could move prices and must not be used for trading."},{term:"Target price",vi:"Giá mục tiêu: giá trị dự kiến của cổ phiếu trong khoảng thời gian xác định, thường 12 tháng.",en:"The expected share value over a set horizon, usually 12 months."}],quiz:[{q:{vi:"EPS dự phóng 3.200 đồng, P/E mục tiêu 12,5 lần. Giá mục tiêu là bao nhiêu?",en:"Forecast EPS is VND 3,200 and the target P/E is 12.5x. What is the target price?"},options:{vi:["32.000 đồng","38.400 đồng","40.000 đồng","44.800 đồng"],en:["VND 32,000","VND 38,400","VND 40,000","VND 44,800"]},answer:2,explain:{vi:"Giá mục tiêu = EPS x P/E = 3.200 x 12,5 = 40.000 đồng.",en:"Target price = EPS x P/E = 3,200 x 12.5 = VND 40,000."}},{q:{vi:"Lãi suất phi rủi ro 4%, beta 1,2, phần bù rủi ro thị trường 7%. Chi phí vốn chủ theo CAPM là bao nhiêu?",en:"Risk-free rate 4%, beta 1.2, equity risk premium 7%. What is the CAPM cost of equity?"},options:{vi:["12,4%","11,0%","8,4%","13,2%"],en:["12.4%","11.0%","8.4%","13.2%"]},answer:0,explain:{vi:"Chi phí vốn chủ Ke = 4% + 1,2 x 7% = 12,4%.",en:"Ke = 4% + 1.2 x 7% = 12.4%."}},{q:{vi:"Bội số nào phù hợp hơn để so sánh các doanh nghiệp có cơ cấu nợ vay rất khác nhau?",en:"Which multiple is better for comparing companies with very different leverage?"},options:{vi:["P/E","EV/EBITDA","Tỷ suất cổ tức","P/B"],en:["P/E","EV/EBITDA","Dividend yield","P/B"]},answer:1,explain:{vi:"EV/EBITDA đo trên toàn bộ nguồn vốn trước chi phí lãi vay nên ít bị ảnh hưởng bởi cơ cấu vốn.",en:"EV/EBITDA works at the whole-capital level before interest, so leverage distorts it less."}},{q:{vi:"Bạn tình cờ nhận được kết quả kinh doanh chưa công bố của doanh nghiệp đang theo dõi. Bạn làm gì?",en:"You accidentally receive unpublished results of a covered company. What do you do?"},options:{vi:["Nâng khuyến nghị ngay để khách hàng có lợi","Chia sẻ cho trưởng bộ phận môi giới","Mua cổ phiếu cho tài khoản cá nhân","Không sử dụng, báo bộ phận Tuân thủ và chờ thông tin được công bố"],en:["Upgrade the rating at once to benefit clients","Share it with the head of brokerage","Buy the shares for your own account","Do not use it, report to Compliance and wait for public release"]},answer:3,explain:{vi:"Sử dụng thông tin nội bộ chưa công bố là hành vi bị cấm; phải báo Tuân thủ và chỉ dựa vào thông tin công khai.",en:"Using inside information is prohibited; report to Compliance and rely only on public information."}}],tools_en:["Microsoft Excel (valuation models)","Financial market data system","Stock exchange disclosure portal","BI and visualization tools","Research report authoring and publishing tool"]}},"KK-145":{scenario:{company:"Lam Kinh Finance",supervisor:{name:"Đặng Thu Trang",role:{vi:"Giám đốc Quản trị Rủi ro",en:"Chief Risk Officer"}},ref_code:"ECL-4518",title:{vi:"Đúng giai đoạn. Đúng PD. Đúng dự phòng.",en:"Right stage. Right PD. Right provision."},brief:{vi:"Bạn rà soát hồ sơ ECL-4518 tính tổn thất tín dụng dự kiến theo IFRS 9 cho một khoản vay doanh nghiệp đang quá hạn 45 ngày, chưa có bằng chứng suy giảm giá trị tín dụng. EAD 8000 triệu đồng, PD 12 tháng 4%, PD toàn thời hạn 18%, LGD 45% (số liệu mô phỏng). Bản nháp xếp khoản vay ở giai đoạn 1 và dùng PD 12 tháng. Hãy sửa giai đoạn và số ECL, rồi lập báo cáo có căn cứ gửi Ủy ban Rủi ro.",en:"You are reviewing file ECL-4518, the IFRS 9 expected credit loss for a corporate loan that is 45 days past due with no evidence of credit impairment. EAD 8000 million VND, 12-month PD 4%, lifetime PD 18%, LGD 45% (training data). The draft keeps the loan in Stage 1 and uses the 12-month PD. Correct the stage and the ECL amount, then write an evidence-based report for the Risk Committee."},reference_title:{vi:"Chính sách phân giai đoạn & tham số ECL đã duyệt · ECL-4518",en:"Approved staging policy & ECL parameters · ECL-4518"},fields:[{id:"IFRS9_STAGE",label:{vi:"Giai đoạn IFRS 9",en:"IFRS 9 stage"},initial:"STAGE 1",expected:"STAGE 2",choices:["STAGE 1","STAGE 2","STAGE 3"],reference:"Chính sách phân giai đoạn tín dụng",ref_value:{vi:"Quá hạn trên 30 ngày: tăng đáng kể rủi ro tín dụng (SICR); trên 90 ngày hoặc đã suy giảm giá trị: vỡ nợ",en:"Over 30 days past due: significant increase in credit risk (SICR); over 90 days or credit-impaired: default"},hint:{vi:"Đặt 45 ngày quá hạn cạnh hai ngưỡng 30 và 90 ngày; khoản vay chưa có bằng chứng suy giảm giá trị.",en:"Place 45 days past due against the 30 and 90 day thresholds; the loan shows no evidence of impairment."}},{id:"ECL_MVND",label:{vi:"ECL (triệu đồng)",en:"ECL (million VND)"},initial:"144",expected:"648",reference:"Bảng tham số rủi ro đã kiểm định",ref_value:{vi:"EAD 8000 triệu; PD 12 tháng 4%; PD toàn thời hạn 18%; LGD 45%",en:"EAD 8000 million; 12-month PD 4%; lifetime PD 18%; LGD 45%"},hint:{vi:"Giai đoạn 2 phải dùng PD toàn thời hạn; nhân đủ ba tham số PD, LGD và EAD.",en:"Stage 2 requires the lifetime PD; multiply all three parameters PD, LGD and EAD."}}],sop32:{vi:"Giai đoạn 1: ECL = PD 12 tháng x LGD x EAD; giai đoạn 2 và 3: ECL = PD toàn thời hạn x LGD x EAD (bài mô phỏng bỏ qua chiết khấu dòng tiền).",en:"Stage 1: ECL = 12-month PD x LGD x EAD; Stages 2 and 3: ECL = lifetime PD x LGD x EAD (the training case ignores discounting)."},context:{label:"ECL ENGINE / ECL-4518",metrics:[{label:{vi:"Số ngày quá hạn",en:"Days past due"},value:"45 DPD"},{label:{vi:"Dư nợ rủi ro EAD",en:"Exposure at default"},value:"8,000,000,000 VND"},{label:{vi:"LGD đã kiểm định",en:"Validated LGD"},value:"45%"}]},crisis:{vi:"Giám đốc khối kinh doanh nhắn: “Cứ để khoản này ở giai đoạn 1. Tuần sau tôi cho khách cơ cấu lại kỳ hạn là về trong hạn. Trích thêm 504 triệu thì quý này hụt chỉ tiêu lợi nhuận.”",en:"The business head messages you: “Keep this loan in Stage 1. Next week I will restructure the schedule so it looks current. An extra 504 million provision would miss this quarter's profit target.”"},options:{safe:{vi:"Giữ giai đoạn 2 và ECL 648 triệu theo chính sách, lưu bằng chứng ngày quá hạn, báo Giám đốc Rủi ro; khoản cơ cấu lại phải qua thời gian thử thách mới được xét chuyển giai đoạn.",en:"Keep Stage 2 and the 648 million ECL per policy, file the past-due evidence and inform the CRO; a restructured loan must pass a probation period before any stage transfer."},shortcut:{vi:"Giữ giai đoạn 1 theo đề nghị, chờ cơ cấu lại xong rồi điều chỉnh dự phòng sau.",en:"Keep Stage 1 as asked and adjust the provision after the restructuring."},wait:{vi:"Không ghi nhận gì, chờ khối kinh doanh và Ủy ban Rủi ro tự thống nhất.",en:"Record nothing and wait for the business line and the Risk Committee to agree."}},questions:{vi:["Vì sao khoản vay quá hạn 45 ngày thuộc giai đoạn 2 mà không phải giai đoạn 1 hay 3? Dữ liệu nào chứng minh nhận định của bạn?","Trình bày cách tính ECL 648 triệu đồng và rủi ro kiểm toán nếu dùng cơ cấu lại nợ để né chuyển giai đoạn."],en:["Why is a loan 45 days past due in Stage 2 rather than Stage 1 or 3? Which data supports your conclusion?","Explain how you calculated the 648 million VND ECL and the audit risk of using a restructuring to avoid a stage transfer."]},hints:{vi:["Đặt số ngày quá hạn cạnh hai ngưỡng 30 và 90 ngày trong chính sách phân giai đoạn.","Chọn đúng loại PD theo giai đoạn rồi mới nhân với LGD và EAD ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi đề nghị né chuyển giai đoạn phải báo Giám đốc Rủi ro và lưu hồ sơ."],en:["Place the days past due against the 30 and 90 day thresholds in the staging policy.","Pick the PD type for the stage before multiplying by LGD and EAD in SOP 3.2.","Re-read SOP 4.2: any request to avoid a stage transfer must be escalated to the CRO and documented."]}},learning:{summary:{vi:"Chuyên viên quản trị rủi ro tài chính nhận diện, đo lường và giám sát rủi ro tín dụng, thị trường, thanh khoản và hoạt động; xây dựng, vận hành mô hình PD, LGD, EAD, tính tổn thất tín dụng dự kiến (ECL) theo IFRS 9, giá trị chịu rủi ro (VaR) và kiểm định sức chịu đựng. Nghề tạo ra cảnh báo sớm, hạn mức hợp lý và số dự phòng đáng tin cậy, đòi hỏi tư duy định lượng, hiểu chuẩn mực và bản lĩnh độc lập trước áp lực kinh doanh.",en:"A financial risk analyst identifies, measures and monitors credit, market, liquidity and operational risk; builds and runs PD, LGD and EAD models, calculates IFRS 9 expected credit loss (ECL), value at risk (VaR) and stress tests. The role delivers early warnings, sound limits and reliable provisions, and requires quantitative thinking, command of the standards and independence under business pressure."},responsibilities:{vi:["Phân giai đoạn danh mục tín dụng theo IFRS 9 và tính ECL hằng tháng.","Xây dựng, kiểm định và hiệu chỉnh mô hình PD, LGD, EAD cùng kịch bản vĩ mô.","Đo lường rủi ro thị trường và thanh khoản: VaR, độ nhạy lãi suất, khe hở kỳ hạn.","Thực hiện kiểm định sức chịu đựng và báo cáo khẩu vị rủi ro cho Ủy ban Rủi ro.","Giám sát hạn mức, cảnh báo vi phạm và đề xuất biện pháp xử lý."],en:["Stage the credit portfolio under IFRS 9 and calculate ECL every month.","Build, validate and recalibrate PD, LGD and EAD models with macro scenarios.","Measure market and liquidity risk: VaR, interest rate sensitivity, maturity gaps.","Run stress tests and report risk appetite to the Risk Committee.","Monitor limits, flag breaches and propose remediation."]},competencies:[{name:{vi:"Mô hình định lượng",en:"Quantitative modelling"},desc:{vi:"Ước lượng PD, LGD, EAD bằng thống kê, kiểm định ngược và giải thích được giới hạn của mô hình.",en:"Estimate PD, LGD and EAD with statistics, backtest them and explain each model's limits."}},{name:{vi:"Chuẩn mực IFRS 9",en:"IFRS 9 expertise"},desc:{vi:"Áp dụng tiêu chí SICR, định nghĩa vỡ nợ, thông tin dự báo tương lai và ECL ba giai đoạn.",en:"Apply SICR criteria, the default definition, forward-looking information and three-stage ECL."}},{name:{vi:"Phân tích dữ liệu rủi ro",en:"Risk data analysis"},desc:{vi:"Làm sạch, đối chiếu dữ liệu khoản vay, ngày quá hạn, tài sản bảo đảm trước khi chạy mô hình.",en:"Clean and reconcile loan, past-due and collateral data before running models."}},{name:{vi:"Độc lập & liêm chính",en:"Independence & integrity"},desc:{vi:"Giữ kết quả mô hình và chính sách trước áp lực lợi nhuận, báo cáo trung thực lên cấp có thẩm quyền.",en:"Defend model results and policy against profit pressure and report honestly to the proper authority."}},{name:{vi:"Truyền đạt rủi ro",en:"Risk communication"},desc:{vi:"Biến con số phức tạp thành thông điệp rõ ràng cho Ban điều hành và Ủy ban Rủi ro.",en:"Turn complex numbers into clear messages for executives and the Risk Committee."}}],knowledge:{vi:["IFRS 9 Công cụ tài chính: mô hình ECL ba giai đoạn, tiêu chí tăng đáng kể rủi ro tín dụng (SICR) và định nghĩa vỡ nợ.","Khung Basel II/III của Ủy ban Basel: vốn tối thiểu, đệm vốn, tỷ lệ đòn bẩy, LCR và NSFR.","Thông tư 41/2016/TT-NHNN về tỷ lệ an toàn vốn và Thông tư 11/2021/TT-NHNN về phân loại nợ, trích lập dự phòng rủi ro.","Thông tư 13/2018/TT-NHNN về hệ thống kiểm soát nội bộ và mô hình ba tuyến bảo vệ.","Đo lường rủi ro thị trường: VaR tham số, lịch sử, Monte Carlo và kiểm định ngược.","Kiểm định sức chịu đựng và xây dựng kịch bản vĩ mô cho dự báo có tính đến tương lai."],en:["IFRS 9 Financial Instruments: the three-stage ECL model, significant increase in credit risk (SICR) and the default definition.","The Basel II/III framework: minimum capital, buffers, leverage ratio, LCR and NSFR.","Circular 41/2016/TT-NHNN on capital adequacy and Circular 11/2021/TT-NHNN on loan classification and provisioning.","Circular 13/2018/TT-NHNN on internal control systems and the three lines of defence.","Market risk measurement: parametric, historical and Monte Carlo VaR with backtesting.","Stress testing and building macro scenarios for forward-looking estimates."]},tools:["Python / R","SQL risk data mart","ECL calculation engine","Stress testing model","Spreadsheet models","BI risk dashboard"],tools_en:["Python / R","SQL risk data mart","ECL calculation engine","Stress testing model","Spreadsheet models","BI risk dashboard"],kpis:{vi:["Tỷ lệ báo cáo ECL nộp đúng hạn và không phải điều chỉnh sau kiểm toán.","Sai số dự báo PD so với tỷ lệ vỡ nợ thực tế trong kiểm định ngược.","Số vi phạm hạn mức được phát hiện và báo cáo trong 24 giờ.","Số phát hiện trọng yếu của kiểm toán về mô hình rủi ro (mục tiêu bằng 0)."],en:["Share of ECL reports filed on time with no post-audit adjustments.","PD forecast error versus actual default rates in backtesting.","Limit breaches detected and reported within 24 hours.","Material audit findings on risk models (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra dữ liệu dư nợ, ngày quá hạn tải về từ hệ thống lõi qua đêm.",en:"Check overnight exposure and past-due data loaded from the core system."},{time:"09:30",vi:"Chạy phân giai đoạn IFRS 9 và rà soát các khoản chuyển giai đoạn bất thường.",en:"Run IFRS 9 staging and review unusual stage transfers."},{time:"11:00",vi:"Cập nhật VaR danh mục kinh doanh và đối chiếu với hạn mức đã duyệt.",en:"Update trading book VaR and compare it with approved limits."},{time:"14:00",vi:"Họp với khối kinh doanh giải trình kết quả ECL và các khoản cần theo dõi.",en:"Meet the business line to explain ECL results and watch-list loans."},{time:"16:30",vi:"Soạn báo cáo rủi ro tuần và đề xuất kịch bản kiểm định sức chịu đựng.",en:"Draft the weekly risk report and propose stress test scenarios."}],mistakes:{vi:["Giữ khoản vay quá hạn trên 30 ngày ở giai đoạn 1 mà không có lý do bác bỏ hợp lệ.","Dùng PD 12 tháng cho khoản vay giai đoạn 2, làm thiếu dự phòng.","Chấp nhận cơ cấu lại nợ để đưa khoản vay về giai đoạn 1 ngay, bỏ qua thời gian thử thách."],en:["Keeping a loan over 30 days past due in Stage 1 without a valid rebuttal.","Using the 12-month PD for a Stage 2 loan, leaving the provision short.","Accepting a restructuring to move a loan straight back to Stage 1, skipping the probation period."]},career:[{vi:"Chuyên viên phân tích rủi ro",en:"Risk analyst"},{vi:"Chuyên viên cao cấp mô hình rủi ro",en:"Senior risk modelling specialist"},{vi:"Trưởng phòng Quản lý rủi ro tín dụng / thị trường",en:"Head of credit or market risk"},{vi:"Giám đốc Quản trị Rủi ro (CRO)",en:"Chief Risk Officer (CRO)"}],glossary:[{term:"PD",vi:"Xác suất vỡ nợ của khách hàng trong 12 tháng hoặc toàn thời hạn khoản vay.",en:"Probability that a borrower defaults over 12 months or the loan lifetime."},{term:"LGD",vi:"Tỷ lệ tổn thất khi vỡ nợ: phần dư nợ không thu hồi được sau khi xử lý tài sản bảo đảm.",en:"Loss given default: the share of exposure not recovered after collateral is realised."},{term:"EAD",vi:"Dư nợ rủi ro tại thời điểm vỡ nợ, gồm dư nợ hiện tại và phần hạn mức dự kiến được rút.",en:"Exposure at default, including the drawn balance and expected future drawdowns."},{term:"SICR",vi:"Tăng đáng kể rủi ro tín dụng kể từ ghi nhận ban đầu, căn cứ chuyển sang giai đoạn 2.",en:"Significant increase in credit risk since initial recognition, the trigger for Stage 2."},{term:"VaR",vi:"Giá trị chịu rủi ro: mức lỗ tối đa ước tính trong một kỳ ở một độ tin cậy cho trước.",en:"Value at risk: the estimated maximum loss over a horizon at a given confidence level."}],quiz:[{q:{vi:"Theo IFRS 9, giả định có thể bác bỏ về tăng đáng kể rủi ro tín dụng áp dụng khi khoản vay quá hạn bao lâu?",en:"Under IFRS 9, the rebuttable presumption of a significant increase in credit risk applies after how many days past due?"},options:{vi:["Trên 10 ngày","Trên 60 ngày","Trên 30 ngày","Trên 180 ngày"],en:["More than 10 days","More than 60 days","More than 30 days","More than 180 days"]},answer:2,explain:{vi:"IFRS 9 giả định rủi ro tín dụng tăng đáng kể khi khoản thanh toán quá hạn trên 30 ngày, trừ khi có bằng chứng hợp lý bác bỏ.",en:"IFRS 9 presumes a significant increase in credit risk when payments are more than 30 days past due, unless reasonable evidence rebuts it."}},{q:{vi:"Khoản vay giai đoạn 2 có EAD 5000 triệu, PD toàn thời hạn 10%, LGD 40%. ECL là bao nhiêu?",en:"A Stage 2 loan has EAD 5000 million, lifetime PD 10% and LGD 40%. What is the ECL?"},options:{vi:["200 triệu","500 triệu","2000 triệu","20 triệu"],en:["200 million","500 million","2000 million","20 million"]},answer:0,explain:{vi:"ECL = 10% x 40% x 5000 = 200 triệu đồng (bỏ qua chiết khấu).",en:"ECL = 10% x 40% x 5000 = 200 million (ignoring discounting)."}},{q:{vi:"VaR 1 ngày ở độ tin cậy 99% bằng 2 tỷ đồng nghĩa là gì?",en:"What does a 1-day 99% VaR of 2 billion VND mean?"},options:{vi:["Lỗ tối đa chắc chắn là 2 tỷ","Lãi kỳ vọng mỗi ngày là 2 tỷ","Hạn mức đầu tư là 2 tỷ","Chỉ có 1% khả năng lỗ một ngày vượt 2 tỷ trong điều kiện thị trường bình thường"],en:["The loss can never exceed 2 billion","Expected daily profit is 2 billion","The investment limit is 2 billion","There is only a 1% chance a daily loss exceeds 2 billion in normal markets"]},answer:3,explain:{vi:"VaR là ngưỡng lỗ ở độ tin cậy cho trước, không phải mức lỗ tối đa tuyệt đối; cần bổ sung kiểm định sức chịu đựng.",en:"VaR is a loss threshold at a confidence level, not an absolute maximum; stress tests are still needed."}},{q:{vi:"Khối kinh doanh đề nghị chỉnh tham số PD để giảm dự phòng cho kịp chỉ tiêu. Bạn làm gì?",en:"The business line asks you to tweak the PD to cut provisions and hit targets. What do you do?"},options:{vi:["Chỉnh nhẹ vì khó bị phát hiện","Giữ tham số đã kiểm định, ghi nhận đề nghị và báo Giám đốc Rủi ro","Chờ kiểm toán tự phát hiện","Chuyển việc cho đồng nghiệp"],en:["Tweak it slightly since it is hard to detect","Keep the validated parameters, record the request and inform the CRO","Wait for the auditors to notice","Hand the task to a colleague"]},answer:1,explain:{vi:"Chức năng rủi ro phải độc lập; mọi thay đổi tham số chỉ theo quy trình kiểm định và phê duyệt chính thức.",en:"The risk function must be independent; parameters change only through formal validation and approval."}}]}},"KK-146":{scenario:{company:"Silverleaf Packaging JSC",supervisor:{name:"Lương Bích Ngọc",role:{vi:"Giám đốc Tài chính",en:"Chief Financial Officer"}},ref_code:"CFW-2647",title:{vi:"Tiền thật. Dòng tiền thật. Phê duyệt thật.",en:"Real cash. Real flows. Real approvals."},brief:{vi:"Bạn lập dự báo dòng tiền tuần 47 (hồ sơ CFW-2647). Số dư tiền và tương đương tiền đầu tuần 18400 triệu đồng, chưa gồm hợp đồng tiền gửi TD-608 trị giá 10000 triệu đồng, kỳ hạn gốc 6 tháng, còn 5 tháng. Thu dự kiến 26350 triệu, chi dự kiến 41200 triệu; số dư tối thiểu theo chính sách 5000 triệu đồng. Bản nháp tính TD-608 là tiền khả dụng. Hãy sửa phân loại TD-608 và số tiền cần rút hạn mức tín dụng, rồi lập báo cáo.",en:"You are building the week 47 cash forecast (file CFW-2647). Opening cash and cash equivalents are 18400 million VND, excluding term deposit TD-608 of 10000 million VND with a 6-month original term and 5 months left. Expected receipts 26350 million, expected payments 41200 million; the policy minimum balance is 5000 million VND. The draft counts TD-608 as available cash. Correct the TD-608 classification and the credit line drawdown, then report."},reference_title:{vi:"Chính sách ngân quỹ & mẫu dự báo đã duyệt · CFW-2647",en:"Approved treasury policy & forecast template · CFW-2647"},fields:[{id:"TD608_CLASS",label:{vi:"Phân loại tiền gửi TD-608",en:"TD-608 classification"},initial:"CASH_EQ",expected:"HTM",choices:["CASH","CASH_EQ","HTM"],reference:"Chính sách phân loại tiền và đầu tư",ref_value:{vi:"Tương đương tiền: kỳ hạn gốc không quá 3 tháng; dài hơn: đầu tư nắm giữ đến ngày đáo hạn (HTM)",en:"Cash equivalent: original maturity of 3 months or less; longer: held-to-maturity investment (HTM)"},hint:{vi:"Xét kỳ hạn gốc tại ngày gửi, không xét thời gian còn lại của hợp đồng.",en:"Look at the original term on the placement date, not the time left on the contract."}},{id:"DRAWDOWN",label:{vi:"Số tiền rút hạn mức (triệu đồng)",en:"Credit line drawdown (million VND)"},initial:"0",expected:"1450",reference:"Mẫu dự báo dòng tiền 13 tuần",ref_value:{vi:"Tiền khả dụng đầu tuần 18400; thu 26350; chi 41200; số dư tối thiểu 5000 (triệu đồng)",en:"Available opening cash 18400; receipts 26350; payments 41200; minimum balance 5000 (million VND)"},hint:{vi:"Chỉ cộng tiền khả dụng; phần thiếu so với số dư tối thiểu là số cần rút hạn mức.",en:"Add only available cash; the shortfall against the minimum balance is the drawdown."}}],sop32:{vi:"Số dư cuối tuần = tiền khả dụng đầu tuần + thu - chi; nếu thấp hơn số dư tối thiểu thì rút hạn mức đúng bằng phần thiếu, không tất toán trước hạn tiền gửi có kỳ hạn.",en:"Closing balance = available opening cash + receipts - payments; if below the minimum balance, draw the credit line by exactly the shortfall and do not break term deposits."},context:{label:"TMS / CFW-2647",metrics:[{label:{vi:"Tiền khả dụng đầu tuần",en:"Available opening cash"},value:"18,400,000,000 VND"},{label:{vi:"Chi dự kiến",en:"Expected payments"},value:"41,200,000,000 VND"},{label:{vi:"Số dư tối thiểu",en:"Minimum balance"},value:"5,000,000,000 VND"}]},crisis:{vi:"Một email từ địa chỉ trông giống hệt của Tổng giám đốc: “Chuyển gấp 3 tỷ đồng sang tài khoản mới của nhà cung cấp ở nước ngoài trước 15:00. Giao dịch bảo mật, không cần chờ phê duyệt kép, tôi sẽ ký bù sau.”",en:"An email from an address that looks exactly like the CEO's: “Urgently wire 3 billion VND to the supplier's new overseas account before 15:00. It is confidential, skip dual approval, I will sign afterwards.”"},options:{safe:{vi:"Không chuyển tiền; gọi lại Tổng giám đốc và nhà cung cấp qua số điện thoại đã lưu, giữ phê duyệt kép, báo Giám đốc Tài chính và bộ phận an ninh thông tin.",en:"Do not pay; call the CEO and the supplier back on numbers on file, keep dual approval, and alert the CFO and the information security team."},shortcut:{vi:"Chuyển ngay cho kịp giờ vì email ghi rõ là lệnh của Tổng giám đốc.",en:"Pay now to meet the deadline because the email says it is the CEO's order."},wait:{vi:"Để email đó lại, không xác minh và không báo cho ai.",en:"Leave the email alone, neither verify it nor tell anyone."}},questions:{vi:["Vì sao TD-608 không được tính vào tiền khả dụng và số rút hạn mức 1450 triệu đồng được tính như thế nào?","Nêu các bước kiểm soát để phòng lừa đảo email giả mạo lãnh đạo (BEC) trong quy trình thanh toán."],en:["Why is TD-608 excluded from available cash and how did you calculate the 1450 million VND drawdown?","List the controls that prevent business email compromise (BEC) fraud in the payment process."]},hints:{vi:["Đối chiếu kỳ hạn gốc của TD-608 với định nghĩa tương đương tiền trong chính sách.","Tính số dư cuối tuần chỉ với tiền khả dụng, rồi so với số dư tối thiểu ở SOP mục 3.2.","Đọc SOP mục 4.2: lệnh chuyển tiền bất thường phải được xác minh qua kênh độc lập trước khi thực hiện."],en:["Compare TD-608's original term with the cash equivalent definition in the policy.","Compute the closing balance with available cash only, then compare it with the minimum balance in SOP 3.2.","Re-read SOP 4.2: unusual payment orders must be verified through an independent channel before execution."]}},learning:{summary:{vi:"Chuyên viên quản lý ngân quỹ và dòng tiền bảo đảm doanh nghiệp luôn đủ tiền thanh toán với chi phí vốn thấp nhất: dự báo dòng tiền, quản lý số dư tài khoản ngân hàng, hạn mức tín dụng, tiền gửi có kỳ hạn, rủi ro tỷ giá và lãi suất, đồng thời kiểm soát quy trình thanh toán an toàn. Nghề đòi hỏi độ chính xác, kỷ luật phê duyệt và luôn cảnh giác với gian lận.",en:"A treasury and cash management specialist keeps the company able to pay its obligations at the lowest cost of funds: forecasting cash, managing bank balances, credit lines, term deposits, FX and interest rate risk, and controlling a secure payment process. The role requires accuracy, approval discipline and constant alertness to fraud."},responsibilities:{vi:["Lập và cập nhật dự báo dòng tiền 13 tuần, đối chiếu thực tế với kế hoạch.","Quản lý số dư tài khoản, gom vốn và điều chuyển tiền giữa các ngân hàng.","Sử dụng hạn mức tín dụng, gửi tiền có kỳ hạn tối ưu chi phí và lợi suất.","Đo lường và phòng ngừa rủi ro tỷ giá, lãi suất theo chính sách đã duyệt.","Kiểm soát lệnh thanh toán, phân quyền ký duyệt và phòng chống gian lận."],en:["Build and update the 13-week cash forecast and compare actuals with plan.","Manage account balances, pool and move cash between banks.","Use credit lines and term deposits to optimise cost and yield.","Measure and hedge FX and interest rate risk under the approved policy.","Control payment orders, signing authorities and fraud prevention."]},competencies:[{name:{vi:"Dự báo dòng tiền",en:"Cash forecasting"},desc:{vi:"Ước tính thu chi theo tuần từ công nợ, đơn hàng, lịch trả nợ và giải thích chênh lệch.",en:"Estimate weekly receipts and payments from receivables, orders and debt schedules and explain variances."}},{name:{vi:"Quản lý thanh khoản",en:"Liquidity management"},desc:{vi:"Giữ số dư tối thiểu, chọn đúng nguồn bù thiếu hụt và đầu tư phần tiền nhàn rỗi.",en:"Hold the minimum balance, pick the right funding source and invest idle cash."}},{name:{vi:"Phòng ngừa rủi ro tài chính",en:"Financial risk hedging"},desc:{vi:"Dùng hợp đồng kỳ hạn, hoán đổi để cố định chi phí tỷ giá, lãi suất khi cần.",en:"Use forwards and swaps to fix FX and interest costs when needed."}},{name:{vi:"Kiểm soát thanh toán",en:"Payment control"},desc:{vi:"Áp dụng phê duyệt kép, xác minh độc lập và phát hiện dấu hiệu lừa đảo email.",en:"Apply dual approval, independent verification and spot email fraud red flags."}},{name:{vi:"Quan hệ ngân hàng",en:"Bank relationships"},desc:{vi:"Đàm phán hạn mức, phí, lãi suất và theo dõi cam kết tín dụng với các ngân hàng.",en:"Negotiate lines, fees and rates and track loan covenants with banks."}}],knowledge:{vi:["VAS 24 và IAS 7 về báo cáo lưu chuyển tiền tệ, định nghĩa tiền và các khoản tương đương tiền.","Thông tư 200/2014/TT-BTC về chế độ kế toán doanh nghiệp: tiền gửi ngân hàng, tiền gửi có kỳ hạn, đầu tư nắm giữ đến ngày đáo hạn.","Quản trị vốn lưu động: chu kỳ chuyển đổi tiền mặt (CCC), DSO, DIO, DPO.","Công cụ phòng ngừa rủi ro tỷ giá, lãi suất: hợp đồng kỳ hạn, hoán đổi, quyền chọn.","Quy định quản lý ngoại hối hiện hành khi thanh toán cho đối tác nước ngoài.","Kiểm soát thanh toán: phân quyền, phê duyệt kép, xác minh độc lập và phòng chống lừa đảo BEC."],en:["VAS 24 and IAS 7 on cash flow statements and the definition of cash and cash equivalents.","Circular 200/2014/TT-BTC on corporate accounting: bank deposits, term deposits and held-to-maturity investments.","Working capital management: cash conversion cycle (CCC), DSO, DIO, DPO.","FX and interest rate hedging tools: forwards, swaps and options.","Current foreign exchange rules for payments to overseas counterparties.","Payment controls: authority matrix, dual approval, independent verification and BEC fraud prevention."]},tools:["Treasury Management System (TMS)","Corporate e-banking","ERP cash & AP/AR modules","Bank statement feeds (MT940)","Spreadsheet cash models","FX dealing platform"],tools_en:["Treasury Management System (TMS)","Corporate e-banking","ERP cash & AP/AR modules","Bank statement feeds (MT940)","Spreadsheet cash models","FX dealing platform"],kpis:{vi:["Sai số dự báo dòng tiền tuần so với thực tế.","Số ngày số dư thấp hơn mức tối thiểu (mục tiêu bằng 0).","Chi phí vốn bình quân và lợi suất tiền nhàn rỗi.","Số lệnh thanh toán sai hoặc bị lừa đảo (mục tiêu bằng 0)."],en:["Weekly cash forecast error versus actuals.","Days below the minimum balance (target zero).","Average cost of funds and yield on idle cash.","Erroneous or fraudulent payments (target zero)."]},day:[{time:"08:00",vi:"Tải sao kê ngân hàng, đối chiếu số dư thực tế với dự báo hôm qua.",en:"Load bank statements and reconcile actual balances with yesterday's forecast."},{time:"09:30",vi:"Cập nhật dự báo dòng tiền tuần, quyết định rút hạn mức hoặc gửi tiền.",en:"Update the weekly forecast and decide on drawdowns or deposits."},{time:"11:00",vi:"Lấy báo giá tỷ giá kỳ hạn cho khoản phải trả ngoại tệ sắp đến hạn.",en:"Get forward FX quotes for upcoming foreign currency payables."},{time:"14:00",vi:"Kiểm tra và trình duyệt lô lệnh thanh toán nhà cung cấp theo phân quyền.",en:"Check and submit the supplier payment batch under the authority matrix."},{time:"16:30",vi:"Báo cáo vị thế tiền cuối ngày cho Giám đốc Tài chính.",en:"Report the end-of-day cash position to the CFO."}],mistakes:{vi:["Tính tiền gửi kỳ hạn trên 3 tháng vào tiền khả dụng, che giấu thiếu hụt thanh khoản.","Quên số dư tối thiểu và các khoản chi cố định khi tính nhu cầu vốn.","Thực hiện lệnh chuyển tiền gấp qua email mà không xác minh qua kênh độc lập."],en:["Counting term deposits over 3 months as available cash, hiding a liquidity gap.","Forgetting the minimum balance and fixed payments when sizing funding needs.","Executing an urgent email payment order without independent verification."]},career:[{vi:"Nhân viên ngân quỹ",en:"Treasury assistant"},{vi:"Chuyên viên quản lý ngân quỹ & dòng tiền",en:"Treasury & cash management specialist"},{vi:"Trưởng phòng Ngân quỹ",en:"Treasury manager"},{vi:"Giám đốc Ngân quỹ / Giám đốc Tài chính",en:"Group treasurer / CFO"}],glossary:[{term:"Cash equivalent",vi:"Khoản đầu tư ngắn hạn, dễ chuyển đổi thành tiền, ít rủi ro, thường có kỳ hạn gốc không quá 3 tháng.",en:"A short-term, highly liquid investment with insignificant risk, usually with an original maturity of 3 months or less."},{term:"Cash forecast",vi:"Bảng dự báo thu chi và số dư tiền theo ngày, tuần hoặc tháng.",en:"A projection of receipts, payments and cash balances by day, week or month."},{term:"Revolving credit line",vi:"Hạn mức tín dụng quay vòng cho phép rút, trả và rút lại trong thời hạn hạn mức.",en:"A credit facility that can be drawn, repaid and redrawn during its term."},{term:"CCC",vi:"Chu kỳ chuyển đổi tiền mặt = DSO + DIO - DPO, thời gian vốn bị giữ trong vòng kinh doanh.",en:"Cash conversion cycle = DSO + DIO - DPO, the time cash is tied up in operations."},{term:"BEC",vi:"Lừa đảo xâm phạm email doanh nghiệp: giả danh lãnh đạo hoặc nhà cung cấp để yêu cầu chuyển tiền.",en:"Business email compromise: impersonating executives or suppliers to request payments."}],quiz:[{q:{vi:"Khoản nào được coi là tương đương tiền?",en:"Which item qualifies as a cash equivalent?"},options:{vi:["Tiền gửi kỳ hạn gốc 6 tháng","Cổ phiếu niêm yết","Khoản phải thu khách hàng","Tiền gửi kỳ hạn gốc 2 tháng, dễ chuyển đổi, ít rủi ro"],en:["A deposit with a 6-month original term","Listed shares","Trade receivables","A deposit with a 2-month original term, liquid and low risk"]},answer:3,explain:{vi:"Tương đương tiền thường có kỳ hạn gốc không quá 3 tháng và rủi ro thay đổi giá trị không đáng kể.",en:"Cash equivalents usually have an original maturity of 3 months or less and insignificant risk of value change."}},{q:{vi:"Tiền khả dụng 12000, thu 8000, chi 17000, số dư tối thiểu 4000 (triệu đồng). Cần rút hạn mức bao nhiêu?",en:"Available cash 12000, receipts 8000, payments 17000, minimum balance 4000 (million VND). How much must be drawn?"},options:{vi:["1000 triệu","3000 triệu","Không cần rút","4000 triệu"],en:["1000 million","3000 million","No drawdown","4000 million"]},answer:0,explain:{vi:"Số dư cuối = 12000 + 8000 - 17000 = 3000; thiếu 4000 - 3000 = 1000 triệu đồng.",en:"Closing = 12000 + 8000 - 17000 = 3000; shortfall 4000 - 3000 = 1000 million."}},{q:{vi:"Doanh nghiệp có khoản phải trả 500000 USD sau 3 tháng và muốn cố định chi phí VND. Công cụ phù hợp là gì?",en:"The company owes 500000 USD in 3 months and wants to fix the VND cost. Which tool fits?"},options:{vi:["Bán kỳ hạn USD","Gửi tiết kiệm VND","Mua kỳ hạn USD giao sau 3 tháng","Không làm gì"],en:["Sell USD forward","Place a VND deposit","Buy USD forward for delivery in 3 months","Do nothing"]},answer:2,explain:{vi:"Khoản phải trả ngoại tệ được phòng ngừa bằng hợp đồng mua kỳ hạn ngoại tệ đúng kỳ hạn thanh toán.",en:"A foreign currency payable is hedged by buying that currency forward for the payment date."}},{q:{vi:"Nhận email “lãnh đạo” yêu cầu chuyển tiền gấp sang tài khoản mới. Bước đúng đầu tiên là gì?",en:"An “executive” email asks for an urgent transfer to a new account. What is the right first step?"},options:{vi:["Chuyển ngay để tránh bị phê bình","Xác minh qua số điện thoại đã lưu và giữ phê duyệt kép","Trả lời chính email đó để hỏi lại","Chuyển một nửa trước"],en:["Pay at once to avoid criticism","Verify via the phone number on file and keep dual approval","Reply to the same email to ask","Pay half first"]},answer:1,explain:{vi:"Kẻ gian kiểm soát email nên phải xác minh qua kênh độc lập đã lưu sẵn và không bỏ phê duyệt kép.",en:"Fraudsters control the email thread, so verify through an independent channel on file and never skip dual approval."}}]}},"KK-171":{scenario:{company:"Jadeport Commercial Bank",supervisor:{name:"Trịnh Quốc Bảo",role:{vi:"Giám đốc Chi nhánh",en:"Branch Director"}},ref_code:"CP-7316",title:{vi:"Đúng tài sản. Đúng tỷ lệ. Đúng hạn mức.",en:"Right collateral. Right ratio. Right limit."},brief:{vi:"Khách hàng doanh nghiệp đề nghị hạn mức vay vốn lưu động 9000 triệu đồng, bảo đảm bằng dây chuyền máy móc đã qua sử dụng 3 năm. Khách tự báo giá thị trường 15000 triệu đồng; Phòng Định giá độc lập định giá 12400 triệu đồng. Bản nháp tờ trình CP-7316 áp tỷ lệ cho vay tối đa trên tài sản bảo đảm (LTV) của bất động sản và dùng giá khách báo. Hãy sửa LTV và mức cấp tín dụng tối đa theo tài sản, rồi lập báo cáo có căn cứ.",en:"A corporate client requests a 9000 million VND working capital line secured by a used machinery line that is 3 years old. The client quotes a market value of 15000 million VND; the independent Valuation Unit appraised it at 12400 million VND. Draft proposal CP-7316 applies the real estate loan-to-value (LTV) ratio and the client's quote. Correct the LTV and the maximum collateral-based limit, then write an evidence-based report."},reference_title:{vi:"Chính sách TSBĐ & chứng thư định giá đã duyệt · CP-7316",en:"Approved collateral policy & valuation report · CP-7316"},fields:[{id:"LTV_RATE",label:{vi:"Tỷ lệ LTV áp dụng",en:"Applied LTV ratio"},initial:"70%",expected:"50%",choices:["70%","50%","40%"],reference:"Chính sách tài sản bảo đảm",ref_value:{vi:"LTV tối đa: bất động sản 70%; máy móc thiết bị 50%; hàng tồn kho 40% (mô phỏng)",en:"Max LTV: real estate 70%; machinery and equipment 50%; inventory 40% (training data)"},hint:{vi:"Tỷ lệ LTV đi theo loại tài sản bảo đảm thực tế của khoản vay, không theo loại tài sản khách quen thế chấp.",en:"The LTV follows the actual collateral of this loan, not the type the client usually pledges."}},{id:"MAX_LIMIT",label:{vi:"Mức cấp tín dụng tối đa (triệu đồng)",en:"Maximum credit limit (million VND)"},initial:"10500",expected:"6200",reference:"Chứng thư định giá tài sản bảo đảm",ref_value:{vi:"Giá khách báo 15000; giá Phòng Định giá độc lập 12400 (triệu đồng)",en:"Client quote 15000; independent Valuation Unit value 12400 (million VND)"},hint:{vi:"Chỉ dùng giá trị do bộ phận định giá độc lập xác định, rồi nhân với LTV đúng loại tài sản.",en:"Use only the value set by the independent valuation unit, then apply the correct LTV."}}],sop32:{vi:"Mức cấp tín dụng tối đa theo tài sản = giá trị định giá độc lập x LTV theo loại tài sản; không dùng giá khách hàng tự báo hoặc giá chào bán.",en:"Maximum collateral-based limit = independent appraised value x LTV for the collateral type; never use the client's own quote or asking price."},context:{label:"LOS / CP-7316",metrics:[{label:{vi:"Hạn mức khách đề nghị",en:"Requested line"},value:"9,000,000,000 VND"},{label:{vi:"Giá định giá độc lập",en:"Independent appraisal"},value:"12,400,000,000 VND"},{label:{vi:"LTV trên bản nháp",en:"Draft LTV"},value:"70%"}]},crisis:{vi:"Giám đốc tài chính của khách hàng gọi riêng: “Em cứ lấy giá 15000 triệu cho đủ hạn mức 9000. Xong việc anh gửi em 1% giá trị khoản vay. Ngân hàng bên cạnh sẵn sàng làm ngay nếu em chậm.”",en:"The client's CFO calls you privately: “Just use the 15000 million value so the 9000 line fits. Once it is approved I will give you 1% of the loan. The bank next door will do it right away if you are slow.”"},options:{safe:{vi:"Từ chối lợi ích cá nhân, dùng giá định giá độc lập và mức 6200 triệu, báo Giám đốc chi nhánh và Tuân thủ; đề xuất khách bổ sung tài sản bảo đảm hoặc giảm hạn mức.",en:"Decline the personal benefit, use the independent value and the 6200 million limit, report to the branch director and Compliance; propose extra collateral or a smaller line."},shortcut:{vi:"Dùng giá khách báo để giữ khách và coi khoản 1% là phí chăm sóc khách hàng.",en:"Use the client's quote to keep the client and treat the 1% as a relationship fee."},wait:{vi:"Không trả lời khách, để hồ sơ nằm đó đến khi khách tự rút.",en:"Do not reply and let the file sit until the client walks away."}},questions:{vi:["Vì sao mức cấp tín dụng tối đa là 6200 triệu chứ không phải 10500 triệu? Hãy dẫn chứng thư định giá và chính sách LTV.","Bạn xử lý đề nghị 1% của khách thế nào theo quy định về quà tặng, xung đột lợi ích và phòng chống tham nhũng?"],en:["Why is the maximum limit 6200 million rather than 10500 million? Cite the valuation report and the LTV policy.","How do you handle the client's 1% offer under the gifts, conflict of interest and anti-corruption rules?"]},hints:{vi:["Xác định loại tài sản bảo đảm thực tế rồi tra bảng LTV trong chính sách.","Lấy đúng giá trị định giá độc lập trước khi nhân với LTV ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi đề nghị lợi ích cá nhân từ khách hàng phải từ chối và báo cáo bằng văn bản."],en:["Identify the actual collateral type, then look up the LTV table in the policy.","Take the independent appraised value before applying the LTV in SOP 3.2.","Re-read SOP 4.2: any personal benefit offered by a client must be refused and reported in writing."]}},learning:{summary:{vi:"Chuyên viên quan hệ khách hàng (RM) phát triển và chăm sóc danh mục khách hàng cá nhân, doanh nghiệp: tìm hiểu nhu cầu, tư vấn sản phẩm tín dụng, tiền gửi, thanh toán, lập tờ trình cấp tín dụng sơ bộ và theo dõi khách hàng sau giải ngân. RM tạo doanh thu bền vững cho ngân hàng khi cân bằng được chỉ tiêu kinh doanh với khẩu vị rủi ro, tuân thủ KYC và đạo đức nghề nghiệp.",en:"A relationship manager (RM) grows and serves a portfolio of retail or corporate clients: understanding needs, advising on credit, deposit and payment products, preparing preliminary credit proposals and monitoring clients after disbursement. An RM builds sustainable revenue by balancing sales targets with risk appetite, KYC compliance and professional ethics."},responsibilities:{vi:["Tìm kiếm, tiếp cận và phát triển khách hàng mới theo phân khúc được giao.","Tìm hiểu nhu cầu, tư vấn gói sản phẩm tín dụng, tiền gửi, thanh toán phù hợp.","Thu thập hồ sơ, thực hiện KYC và lập tờ trình cấp tín dụng sơ bộ.","Phối hợp thẩm định, định giá, phê duyệt và giải ngân đúng điều kiện.","Theo dõi khách hàng sau giải ngân, nhắc nợ và phát hiện sớm dấu hiệu rủi ro."],en:["Prospect, approach and grow new clients in the assigned segment.","Understand needs and advise on suitable credit, deposit and payment packages.","Collect documents, perform KYC and prepare preliminary credit proposals.","Coordinate underwriting, valuation, approval and compliant disbursement.","Monitor clients after disbursement, follow up repayments and spot early risk signals."]},competencies:[{name:{vi:"Tư vấn giải pháp",en:"Solution advisory"},desc:{vi:"Đặt câu hỏi đúng, hiểu dòng tiền khách hàng và đề xuất sản phẩm phù hợp thay vì bán ép.",en:"Ask the right questions, understand client cash flows and propose fitting products instead of pushing."}},{name:{vi:"Phân tích tín dụng cơ bản",en:"Basic credit analysis"},desc:{vi:"Đọc báo cáo tài chính, đánh giá nguồn trả nợ và tài sản bảo đảm trước khi trình.",en:"Read financial statements and assess repayment sources and collateral before proposing."}},{name:{vi:"Đàm phán & giữ chân",en:"Negotiation & retention"},desc:{vi:"Đàm phán lãi suất, phí trong khung phê duyệt và giữ khách bằng chất lượng dịch vụ.",en:"Negotiate rates and fees within approved bands and retain clients through service quality."}},{name:{vi:"Tuân thủ & liêm chính",en:"Compliance & integrity"},desc:{vi:"Thực hiện KYC đầy đủ, từ chối quà tặng, lợi ích vi phạm quy định và báo cáo xung đột lợi ích.",en:"Complete KYC, refuse improper gifts or benefits and report conflicts of interest."}},{name:{vi:"Quản lý danh mục",en:"Portfolio management"},desc:{vi:"Theo dõi dư nợ, huy động, thu nhập và chất lượng nợ của từng khách hàng.",en:"Track loans, deposits, revenue and asset quality for each client."}}],knowledge:{vi:["Luật Các tổ chức tín dụng số 32/2024/QH15 và quy định của NHNN về hoạt động cho vay.","Bộ luật Dân sự 2015 và Nghị định 21/2021/NĐ-CP về bảo đảm thực hiện nghĩa vụ.","Phân tích báo cáo tài chính doanh nghiệp: thanh khoản, đòn bẩy, khả năng trả nợ, dòng tiền.","Nhận biết khách hàng và chủ sở hữu hưởng lợi theo Luật Phòng, chống rửa tiền 2022.","Chuẩn mực tư vấn bán hàng: phù hợp nhu cầu, minh bạch phí, không gắn sản phẩm không bắt buộc với khoản vay."],en:["The Law on Credit Institutions No. 32/2024/QH15 and State Bank rules on lending.","The 2015 Civil Code and Decree 21/2021/ND-CP on securing obligations.","Corporate financial statement analysis: liquidity, leverage, debt service capacity and cash flow.","Customer and beneficial owner identification under the 2022 Anti-Money Laundering Law.","Sales advisory standards: needs-based, transparent fees and no tying of optional products to loans."]},tools:["Bank CRM","Loan Origination System (LOS)","Core Banking","CIC credit report","Pricing & RAROC calculator","Digital onboarding (eKYC)"],tools_en:["Bank CRM","Loan Origination System (LOS)","Core Banking","CIC credit report","Pricing & RAROC calculator","Digital onboarding (eKYC)"],kpis:{vi:["Tăng trưởng dư nợ và huy động ròng của danh mục khách hàng.","Thu nhập thuần từ khách hàng, gồm lãi và phí dịch vụ.","Tỷ lệ nợ quá hạn của danh mục phụ trách.","Tỷ lệ hồ sơ KYC đầy đủ, không bị Tuân thủ trả lại."],en:["Loan and net deposit growth of the client portfolio.","Net revenue per client, including interest and fees.","Past-due ratio of the managed portfolio.","Share of complete KYC files not returned by Compliance."]},day:[{time:"08:00",vi:"Xem báo cáo dư nợ, khoản đến hạn và cảnh báo quá hạn của danh mục.",en:"Review loan balances, upcoming maturities and past-due alerts for the portfolio."},{time:"09:30",vi:"Thăm nhà máy khách hàng, khảo sát tài sản bảo đảm và nhu cầu vốn.",en:"Visit a client's plant to inspect collateral and discuss funding needs."},{time:"13:30",vi:"Hoàn thiện tờ trình tín dụng, gửi Phòng Định giá và Thẩm định.",en:"Finalise the credit proposal and send it to Valuation and Underwriting."},{time:"15:30",vi:"Gọi điện chăm sóc khách hàng, giới thiệu dịch vụ thanh toán phù hợp.",en:"Call clients and introduce suitable payment services."},{time:"17:00",vi:"Cập nhật CRM, ghi nhận cơ hội và rủi ro mới phát hiện.",en:"Update the CRM with new opportunities and risks spotted."}],mistakes:{vi:["Dùng giá khách tự báo thay vì giá định giá độc lập để tính hạn mức.","Áp LTV của bất động sản cho máy móc, hàng tồn kho có rủi ro giảm giá cao hơn.","Nhận quà, hoa hồng từ khách hoặc ép khách mua sản phẩm kèm để đạt chỉ tiêu."],en:["Using the client's own quote instead of the independent appraisal to size the limit.","Applying the real estate LTV to machinery or inventory that lose value faster.","Taking gifts or commissions from clients or forcing add-on products to hit targets."]},career:[{vi:"Chuyên viên hỗ trợ quan hệ khách hàng",en:"Relationship support officer"},{vi:"Chuyên viên quan hệ khách hàng (RM)",en:"Relationship manager (RM)"},{vi:"Trưởng phòng Khách hàng doanh nghiệp / cá nhân",en:"Head of corporate or retail banking"},{vi:"Giám đốc Chi nhánh",en:"Branch director"}],glossary:[{term:"RM",vi:"Chuyên viên quan hệ khách hàng, đầu mối phục vụ và phát triển một danh mục khách hàng.",en:"Relationship manager, the single point of contact who serves and grows a client portfolio."},{term:"LTV",vi:"Tỷ lệ dư nợ tối đa trên giá trị tài sản bảo đảm, khác nhau theo loại tài sản.",en:"Loan-to-value: maximum loan as a share of collateral value, set by collateral type."},{term:"KYC",vi:"Nhận biết khách hàng: xác minh danh tính, chủ sở hữu hưởng lợi, ngành nghề và nguồn tiền.",en:"Know your customer: verifying identity, beneficial owners, business and source of funds."},{term:"RAROC",vi:"Lợi nhuận điều chỉnh theo rủi ro trên vốn, dùng để định giá khoản vay.",en:"Risk-adjusted return on capital, used to price loans."},{term:"Cross-sell",vi:"Bán chéo sản phẩm phù hợp nhu cầu cho khách hàng hiện hữu, trên cơ sở tự nguyện.",en:"Selling additional suitable products to existing clients on a voluntary basis."}],quiz:[{q:{vi:"Tài sản bảo đảm là hàng tồn kho định giá 5000 triệu, LTV hàng tồn kho 40%. Mức cấp tín dụng tối đa theo tài sản là bao nhiêu?",en:"Collateral is inventory appraised at 5000 million with a 40% inventory LTV. What is the maximum collateral-based limit?"},options:{vi:["5000 triệu","3500 triệu","2000 triệu","2500 triệu"],en:["5000 million","3500 million","2000 million","2500 million"]},answer:2,explain:{vi:"Mức tối đa = 5000 x 40% = 2000 triệu đồng.",en:"Maximum = 5000 x 40% = 2000 million."}},{q:{vi:"Căn cứ giá trị tài sản bảo đảm khi lập tờ trình là gì?",en:"Which collateral value should a credit proposal use?"},options:{vi:["Giá khách hàng tự báo","Giá trị do bộ phận định giá độc lập hoặc tổ chức thẩm định giá được chấp thuận xác định","Giá mua ban đầu trên hóa đơn","Giá cao nhất tìm được trên mạng"],en:["The client's own quote","The value set by the independent valuation unit or an approved appraiser","The original purchase invoice price","The highest price found online"]},answer:1,explain:{vi:"Giá trị tài sản phải được định giá độc lập để tránh xung đột lợi ích và đánh giá quá cao.",en:"Collateral must be valued independently to avoid conflicts of interest and overvaluation."}},{q:{vi:"Chi nhánh yêu cầu RM buộc khách mua bảo hiểm nhân thọ mới được giải ngân khoản vay. Cách làm đúng là gì?",en:"The branch tells RMs to make life insurance a condition of loan disbursement. What is right?"},options:{vi:["Chỉ giới thiệu, để khách tự nguyện, không gắn với điều kiện giải ngân và báo cáo nếu bị ép","Làm theo vì là chỉ tiêu","Giải ngân trước rồi tự trừ phí bảo hiểm","Ký hộ khách hợp đồng bảo hiểm"],en:["Only introduce it, keep it voluntary, never tie it to disbursement and report the pressure","Comply because it is a target","Disburse first and deduct the premium","Sign the policy on the client's behalf"]},answer:0,explain:{vi:"Quy định hiện hành cấm gắn việc mua bảo hiểm không bắt buộc với việc cung cấp dịch vụ ngân hàng.",en:"Current rules prohibit tying optional insurance to the provision of banking services."}},{q:{vi:"Khi KYC khách hàng doanh nghiệp, RM bắt buộc phải xác định ai?",en:"In corporate KYC, whom must the RM identify?"},options:{vi:["Chỉ kế toán trưởng","Chỉ người đến giao dịch","Đối tác lớn nhất của khách","Người đại diện theo pháp luật và chủ sở hữu hưởng lợi"],en:["Only the chief accountant","Only the person at the counter","The client's largest partner","The legal representative and the beneficial owners"]},answer:3,explain:{vi:"Pháp luật phòng chống rửa tiền yêu cầu xác định người đại diện và cá nhân thực sự sở hữu, kiểm soát doanh nghiệp.",en:"AML law requires identifying the representative and the individuals who truly own or control the company."}}]}},"KK-172":{scenario:{company:"Riverbend Commercial Bank",supervisor:{name:"Hoàng Thị Lan Anh",role:{vi:"Trưởng phòng Thẩm định Tín dụng",en:"Head of Credit Underwriting"}},ref_code:"UW-5521",title:{vi:"Đọc đủ CIC. Tính đúng nhu cầu vốn.",en:"Read the full CIC. Size the real need."},brief:{vi:"Bạn thẩm định hồ sơ UW-5521: doanh nghiệp sản xuất đồ gỗ xin hạn mức vốn lưu động. Báo cáo CIC có một khoản vay tại ngân hàng khác quá hạn 40 ngày. Kế hoạch năm tới: chi phí sản xuất kinh doanh (không gồm khấu hao) 98400 triệu đồng, vòng quay vốn lưu động 4 vòng, vốn lưu động ròng tự có 7350 triệu, vay ngắn hạn tại tổ chức tín dụng khác 5150 triệu. Bản nháp ghi CIC-1 và hạn mức bằng toàn bộ nhu cầu vốn. Hãy sửa hai trường và lập báo cáo.",en:"You are underwriting file UW-5521: a furniture manufacturer requests a working capital line. The CIC report shows a loan at another bank 40 days past due. Next year's plan: operating costs excluding depreciation 98400 million VND, working capital turnover 4 times, own net working capital 7350 million, short-term loans at other credit institutions 5150 million. The draft records CIC-1 and a limit equal to the full need. Correct both fields and report."},reference_title:{vi:"Báo cáo CIC & bảng tính nhu cầu vốn đã duyệt · UW-5521",en:"Approved CIC report & working capital worksheet · UW-5521"},fields:[{id:"CIC_GROUP",label:{vi:"Nhóm nợ theo CIC",en:"CIC debt group"},initial:"CIC-1",expected:"CIC-2",choices:["CIC-1","CIC-2","CIC-3"],reference:"Báo cáo CIC & quy tắc phân nhóm nợ",ref_value:{vi:"Nhóm 1: quá hạn dưới 10 ngày; nhóm 2: từ 10 đến 90 ngày; nhóm 3: từ 91 đến 180 ngày",en:"Group 1: under 10 days past due; group 2: 10 to 90 days; group 3: 91 to 180 days"},hint:{vi:"Đọc chi tiết từng khoản vay trên CIC, không chỉ dòng tổng hợp; xếp theo số ngày quá hạn lớn nhất.",en:"Read each facility on the CIC report, not just the summary line; classify by the longest days past due."}},{id:"WC_LIMIT",label:{vi:"Hạn mức vốn lưu động (triệu đồng)",en:"Working capital limit (million VND)"},initial:"24600",expected:"12100",reference:"Bảng tính nhu cầu vốn lưu động",ref_value:{vi:"Chi phí 98400; vòng quay 4; VLĐ ròng tự có 7350; vay TCTD khác 5150 (triệu đồng)",en:"Costs 98400; turnover 4; own net working capital 7350; other lenders 5150 (million VND)"},hint:{vi:"Nhu cầu vốn lưu động chưa phải là hạn mức: phải trừ phần vốn tự có và phần vay ở nơi khác.",en:"The working capital need is not the limit: deduct own funds and borrowings elsewhere."}}],sop32:{vi:"Nhu cầu vốn lưu động = chi phí sản xuất kinh doanh (không gồm khấu hao) / vòng quay vốn lưu động; hạn mức = nhu cầu - vốn lưu động ròng tự có - vay ngắn hạn tại tổ chức tín dụng khác.",en:"Working capital need = operating costs excluding depreciation / working capital turnover; limit = need - own net working capital - short-term loans at other credit institutions."},context:{label:"LOS / UW-5521",metrics:[{label:{vi:"Chi phí kế hoạch",en:"Planned costs"},value:"98,400,000,000 VND"},{label:{vi:"Vòng quay vốn lưu động",en:"Working capital turnover"},value:"4.0x"},{label:{vi:"Quá hạn trên CIC",en:"CIC past due"},value:"40 DPD"}]},crisis:{vi:"RM gửi thêm một bộ báo cáo tài chính có doanh thu cao hơn 35% so với bản đã nộp cơ quan thuế và nhắn: “Dùng bộ này cho hồ sơ đẹp, giám đốc chi nhánh đã đồng ý miệng. Chiều nay phải trình hội đồng tín dụng.”",en:"The RM sends a second set of financial statements with revenue 35% higher than the version filed with the tax authority: “Use this set so the file looks better. The branch director agreed verbally and it goes to the credit committee this afternoon.”"},options:{safe:{vi:"Chỉ dùng báo cáo đã nộp thuế hoặc đã kiểm toán, ghi nhận chênh lệch là dấu hiệu rủi ro, yêu cầu khách giải trình bằng văn bản và báo Trưởng phòng Thẩm định.",en:"Use only the tax-filed or audited statements, record the gap as a red flag, request a written explanation from the client and inform the Head of Underwriting."},shortcut:{vi:"Dùng bộ báo cáo đẹp hơn vì đã có giám đốc chi nhánh đồng ý miệng.",en:"Use the better-looking set because the branch director agreed verbally."},wait:{vi:"Hoãn trình hồ sơ, không ghi nhận chênh lệch và không báo cho ai.",en:"Delay the file without recording the gap or telling anyone."}},questions:{vi:["Vì sao khách hàng thuộc nhóm CIC-2 và hạn mức chỉ là 12100 triệu đồng? Trình bày dữ liệu và công thức.","Hai bộ báo cáo tài chính khác nhau báo hiệu rủi ro gì và bạn xử lý theo quy trình nào?"],en:["Why is the client in CIC-2 and why is the limit only 12100 million VND? Show the data and the formula.","What risk do two different sets of financial statements signal and which procedure do you follow?"]},hints:{vi:["Rà từng dòng chi tiết trên báo cáo CIC và tìm số ngày quá hạn lớn nhất.","Tính nhu cầu vốn lưu động trước, rồi trừ hai nguồn vốn khác theo SOP mục 3.2.","Đọc SOP mục 4.2: số liệu tài chính không nhất quán phải được ghi nhận và báo cáo, không tự chọn bản đẹp."],en:["Scan each detail line of the CIC report and find the longest days past due.","Compute the working capital need first, then deduct the two other funding sources in SOP 3.2.","Re-read SOP 4.2: inconsistent financial data must be recorded and escalated, never cherry-picked."]}},learning:{summary:{vi:"Chuyên viên thẩm định tín dụng đánh giá độc lập hồ sơ vay: tư cách pháp lý, lịch sử tín dụng trên CIC, năng lực tài chính, phương án kinh doanh, dòng tiền trả nợ và tài sản bảo đảm, từ đó đề xuất cấp, điều chỉnh hoặc từ chối tín dụng kèm điều kiện kiểm soát. Nghề bảo vệ chất lượng tài sản của ngân hàng, đòi hỏi kỹ năng phân tích tài chính, hoài nghi nghề nghiệp và tính độc lập với bộ phận kinh doanh.",en:"A credit underwriter independently assesses loan applications: legal standing, CIC credit history, financial capacity, business plan, repayment cash flow and collateral, then recommends approval, restructuring or rejection with control conditions. The role protects the bank's asset quality and requires financial analysis skills, professional scepticism and independence from the sales function."},responsibilities:{vi:["Kiểm tra tư cách pháp lý, mục đích vay và tính hợp pháp của phương án.","Phân tích báo cáo tài chính, dòng tiền và khả năng trả nợ của khách hàng.","Tra cứu, đánh giá lịch sử tín dụng trên CIC và quan hệ với các tổ chức tín dụng khác.","Xác định nhu cầu vốn, hạn mức, kỳ hạn và điều kiện cấp tín dụng.","Lập báo cáo thẩm định độc lập, nêu rõ rủi ro và biện pháp kiểm soát."],en:["Check legal standing, loan purpose and the legality of the business plan.","Analyse financial statements, cash flow and debt service capacity.","Pull and assess CIC credit history and relationships with other lenders.","Size the funding need, limit, tenor and credit conditions.","Write an independent underwriting report stating risks and mitigants."]},competencies:[{name:{vi:"Phân tích báo cáo tài chính",en:"Financial statement analysis"},desc:{vi:"Đánh giá thanh khoản, đòn bẩy, hiệu quả, chất lượng lợi nhuận và phát hiện số liệu bất thường.",en:"Assess liquidity, leverage, efficiency and earnings quality, and spot unusual figures."}},{name:{vi:"Đánh giá dòng tiền trả nợ",en:"Repayment cash flow"},desc:{vi:"Dự phóng dòng tiền, tính DSCR và nhu cầu vốn lưu động sát thực tế.",en:"Project cash flows, calculate DSCR and a realistic working capital need."}},{name:{vi:"Đọc lịch sử tín dụng",en:"Credit history review"},desc:{vi:"Đọc chi tiết CIC, nhận diện nợ quá hạn, nợ cơ cấu và quan hệ với nhiều ngân hàng.",en:"Read the CIC in detail and identify past-due, restructured and multi-bank exposures."}},{name:{vi:"Hoài nghi nghề nghiệp",en:"Professional scepticism"},desc:{vi:"Đối chiếu chéo báo cáo thuế, kiểm toán, sao kê ngân hàng trước khi tin số liệu.",en:"Cross-check tax filings, audits and bank statements before trusting figures."}},{name:{vi:"Độc lập & chính trực",en:"Independence & integrity"},desc:{vi:"Đưa kết luận dựa trên bằng chứng dù chịu áp lực từ kinh doanh hay lãnh đạo chi nhánh.",en:"Base conclusions on evidence despite pressure from sales or branch management."}}],knowledge:{vi:["Thông tư 11/2021/TT-NHNN về phân loại nợ, trích lập dự phòng và việc điều chỉnh nhóm nợ theo thông tin từ CIC.","Phương pháp xác định nhu cầu vốn lưu động theo vòng quay và hạn mức tín dụng.","Phân tích báo cáo tài chính: thanh khoản, đòn bẩy, hiệu quả hoạt động, DSCR và lưu chuyển tiền.","Mô hình 5C trong tín dụng: tư cách, năng lực, vốn, tài sản bảo đảm và điều kiện.","Quy định hiện hành về giới hạn cấp tín dụng đối với một khách hàng và người có liên quan."],en:["Circular 11/2021/TT-NHNN on loan classification, provisioning and aligning debt groups with CIC data.","The turnover method for sizing working capital needs and credit limits.","Financial statement analysis: liquidity, leverage, efficiency, DSCR and cash flow.","The 5C credit model: character, capacity, capital, collateral and conditions.","Current single-borrower and related-party lending limits."]},tools:["CIC credit report","Loan Origination System (LOS)","Internal credit rating model","Financial spreading tool","Cash flow projection model","Collateral management system"],tools_en:["CIC credit report","Loan Origination System (LOS)","Internal credit rating model","Financial spreading tool","Cash flow projection model","Collateral management system"],kpis:{vi:["Tỷ lệ nợ xấu phát sinh từ các khoản đã thẩm định sau 12 tháng.","Thời gian thẩm định trung bình mỗi hồ sơ.","Tỷ lệ hồ sơ bị kiểm toán nội bộ phát hiện sai sót trọng yếu.","Tỷ lệ cảnh báo rủi ro được nêu trong báo cáo và xác nhận về sau."],en:["Non-performing ratio of underwritten loans after 12 months.","Average underwriting time per file.","Share of files with material errors found by internal audit.","Share of flagged risks later confirmed."]},day:[{time:"08:00",vi:"Nhận hồ sơ mới, kiểm tra danh mục chứng từ còn thiếu.",en:"Receive new files and list missing documents."},{time:"09:30",vi:"Tra cứu CIC, đối chiếu dư nợ và nhóm nợ tại các ngân hàng khác.",en:"Pull the CIC report and match balances and debt groups at other banks."},{time:"11:00",vi:"Nhập và phân tích báo cáo tài chính, tính nhu cầu vốn lưu động.",en:"Spread and analyse financial statements and size the working capital need."},{time:"14:00",vi:"Khảo sát thực tế cơ sở sản xuất, kho hàng và tài sản bảo đảm.",en:"Visit the production site, warehouse and collateral."},{time:"16:30",vi:"Hoàn thiện báo cáo thẩm định và trình hội đồng tín dụng.",en:"Finalise the underwriting report and submit it to the credit committee."}],mistakes:{vi:["Chỉ đọc dòng tổng hợp trên CIC, bỏ sót khoản quá hạn tại ngân hàng khác.","Lấy nhu cầu vốn lưu động làm hạn mức mà không trừ vốn tự có và vay nơi khác.","Tin báo cáo tài chính do khách tự lập mà không đối chiếu với bản nộp thuế hoặc kiểm toán."],en:["Reading only the CIC summary and missing a past-due loan at another bank.","Using the working capital need as the limit without deducting own funds and other loans.","Trusting client-prepared statements without checking tax-filed or audited versions."]},career:[{vi:"Chuyên viên thẩm định tín dụng",en:"Credit underwriter"},{vi:"Chuyên viên thẩm định cao cấp",en:"Senior credit underwriter"},{vi:"Trưởng phòng Thẩm định / Phê duyệt tín dụng",en:"Head of underwriting or credit approval"},{vi:"Giám đốc Khối Quản lý tín dụng",en:"Chief Credit Officer"}],glossary:[{term:"CIC",vi:"Trung tâm Thông tin tín dụng Quốc gia, cung cấp lịch sử vay và nhóm nợ của khách hàng.",en:"Vietnam's National Credit Information Centre, which reports borrowers' credit history and debt groups."},{term:"DSCR",vi:"Hệ số khả năng trả nợ: dòng tiền dành trả nợ chia cho gốc và lãi phải trả trong kỳ.",en:"Debt service coverage ratio: cash flow available for debt service divided by principal and interest due."},{term:"Working capital turnover",vi:"Số vòng quay vốn lưu động trong năm, bằng doanh thu thuần chia vốn lưu động bình quân.",en:"Times working capital turns over in a year, net revenue divided by average working capital."},{term:"5C",vi:"Năm tiêu chí đánh giá tín dụng: tư cách, năng lực, vốn, tài sản bảo đảm, điều kiện.",en:"Five credit criteria: character, capacity, capital, collateral and conditions."},{term:"Covenant",vi:"Cam kết tài chính hoặc hành vi khách hàng phải duy trì trong suốt thời gian vay.",en:"A financial or behavioural undertaking the borrower must maintain during the loan."}],quiz:[{q:{vi:"Khoản vay quá hạn 120 ngày được xếp nhóm nợ nào theo quy định phân loại nợ hiện hành?",en:"Under current classification rules, which debt group applies to a loan 120 days past due?"},options:{vi:["Nhóm 2","Nhóm 4","Nhóm 3","Nhóm 5"],en:["Group 2","Group 4","Group 3","Group 5"]},answer:2,explain:{vi:"Nợ quá hạn từ 91 đến 180 ngày thuộc nhóm 3 (nợ dưới tiêu chuẩn).",en:"Loans 91 to 180 days past due are group 3 (substandard)."}},{q:{vi:"Chi phí sản xuất kinh doanh 60000 triệu, vòng quay vốn lưu động 5, vốn tự có 4000, vay nơi khác 2000. Hạn mức là bao nhiêu?",en:"Operating costs 60000 million, turnover 5, own funds 4000, other loans 2000. What is the limit?"},options:{vi:["6000 triệu","12000 triệu","8000 triệu","10000 triệu"],en:["6000 million","12000 million","8000 million","10000 million"]},answer:0,explain:{vi:"Nhu cầu = 60000 / 5 = 12000; hạn mức = 12000 - 4000 - 2000 = 6000 triệu đồng.",en:"Need = 60000 / 5 = 12000; limit = 12000 - 4000 - 2000 = 6000 million."}},{q:{vi:"Hệ số DSCR dưới 1 cho biết điều gì?",en:"What does a DSCR below 1 indicate?"},options:{vi:["Doanh nghiệp có lãi cao","Tài sản bảo đảm đủ","Vòng quay hàng tồn kho nhanh","Dòng tiền không đủ trả gốc và lãi đến hạn"],en:["High profitability","Sufficient collateral","Fast inventory turnover","Cash flow cannot cover principal and interest due"]},answer:3,explain:{vi:"DSCR dưới 1 nghĩa là dòng tiền tạo ra nhỏ hơn nghĩa vụ trả nợ trong kỳ.",en:"A DSCR below 1 means generated cash flow is less than debt service due."}},{q:{vi:"Khách hàng có hai bộ báo cáo tài chính khác nhau. Bạn nên làm gì?",en:"A client has two different sets of financial statements. What should you do?"},options:{vi:["Dùng bộ có số liệu tốt hơn","Ghi nhận chênh lệch, dùng bản đã nộp thuế hoặc kiểm toán và báo cáo cấp trên","Lấy trung bình hai bộ","Bỏ qua vì RM đã xác nhận"],en:["Use the better set","Record the gap, use the tax-filed or audited set and escalate","Average the two sets","Ignore it because the RM confirmed"]},answer:1,explain:{vi:"Chênh lệch số liệu là dấu hiệu gian lận; phải dùng nguồn tin cậy, yêu cầu giải trình và báo cáo.",en:"Inconsistent figures are a fraud red flag; use reliable sources, request explanations and escalate."}}]}},"KK-173":{scenario:{company:"Goldhorn Bank",supervisor:{name:"Vũ Đức Thịnh",role:{vi:"Trưởng phòng Thanh toán Quốc tế",en:"Head of Trade Finance"}},ref_code:"LC-8834",title:{vi:"Đúng điều kiện L/C. Đúng ký quỹ. Đúng UCP.",en:"Right L/C terms. Right margin. Right UCP."},brief:{vi:"Bạn soạn điện MT700 phát hành L/C LC-8834 cho khách nhập khẩu thiết bị. Hợp đồng: trị giá 236500 USD, dung sai số tiền +/-10%, người bán ký phát hối phiếu kỳ hạn 90 ngày kể từ ngày vận đơn đòi tiền ngân hàng phát hành. Ngân hàng yêu cầu ký quỹ 30% trên nghĩa vụ tối đa (số liệu mô phỏng). Bản nháp chọn trường 41a là BY PAYMENT và tính ký quỹ trên trị giá gốc. Hãy sửa hai trường và lập báo cáo có căn cứ.",en:"You are drafting the MT700 to issue L/C LC-8834 for an equipment importer. Contract: value 236500 USD, amount tolerance +/-10%, the seller draws a draft at 90 days after B/L date on the issuing bank. The bank requires a 30% margin on the maximum liability (training data). The draft sets field 41a to BY PAYMENT and computes the margin on the base value. Correct both fields and write an evidence-based report."},reference_title:{vi:"Hợp đồng, đơn mở L/C & quy định ký quỹ đã duyệt · LC-8834",en:"Approved contract, L/C application & margin rule · LC-8834"},fields:[{id:"AVAIL_BY",label:{vi:"Trường 41a - Hình thức sử dụng L/C",en:"Field 41a - Available by"},initial:"BY PAYMENT",expected:"BY ACCEPTANCE",choices:["BY PAYMENT","BY DEF PAYMENT","BY ACCEPTANCE"],reference:"Hợp đồng ngoại thương & đơn mở L/C",ref_value:{vi:"Trả chậm 90 ngày sau ngày vận đơn, có hối phiếu kỳ hạn ký phát đòi ngân hàng phát hành",en:"Payment 90 days after B/L date against a usance draft drawn on the issuing bank"},hint:{vi:"L/C trả chậm có hối phiếu kỳ hạn là thanh toán bằng chấp nhận; trả chậm không có hối phiếu mới là deferred payment.",en:"A usance credit with a time draft is acceptance; deferred payment applies only when no draft is drawn."}},{id:"MARGIN_USD",label:{vi:"Số tiền ký quỹ (USD)",en:"Margin deposit (USD)"},initial:"70950",expected:"78045",reference:"Quy định ký quỹ L/C nhập khẩu",ref_value:{vi:"Trị giá L/C 236500 USD; dung sai +/-10%; tỷ lệ ký quỹ 30% (mô phỏng)",en:"L/C value 236500 USD; tolerance +/-10%; margin rate 30% (training data)"},hint:{vi:"Nghĩa vụ tối đa của ngân hàng phát hành gồm cả dung sai dương của số tiền L/C.",en:"The issuing bank's maximum liability includes the positive amount tolerance."}}],sop32:{vi:"Nghĩa vụ tối đa = trị giá L/C x (1 + dung sai dương); số tiền ký quỹ = nghĩa vụ tối đa x tỷ lệ ký quỹ theo phê duyệt (bài mô phỏng 30%).",en:"Maximum liability = L/C amount x (1 + positive tolerance); margin = maximum liability x approved margin rate (training rate 30%)."},context:{label:"SWIFT MT700 / LC-8834",metrics:[{label:{vi:"Trị giá L/C (32B)",en:"L/C amount (32B)"},value:"236,500 USD"},{label:{vi:"Dung sai (39A)",en:"Tolerance (39A)"},value:"10/10"},{label:{vi:"Tỷ lệ ký quỹ mô phỏng",en:"Training margin rate"},value:"30%"}]},crisis:{vi:"Khách hàng nhắn: “Hàng sẽ chuyển tải qua một cảng nằm trong danh sách trừng phạt. Anh đừng ghi cảng chuyển tải vào L/C và bỏ qua bước sàng lọc cho nhanh, tuần này tôi phải mở được L/C.”",en:"The client messages: “The goods will be transshipped via a port on a sanctions list. Do not mention the transshipment port in the L/C and skip screening to save time, I must have the L/C this week.”"},options:{safe:{vi:"Giữ nguyên thông tin chuyển tải, chuyển hồ sơ cho Tuân thủ sàng lọc cấm vận, báo Trưởng phòng; chỉ phát hành L/C khi rủi ro được xử lý hoặc khách đổi tuyến hợp lệ.",en:"Keep the transshipment details, refer the file to Compliance for sanctions screening and inform the manager; issue only once the risk is cleared or the client uses a compliant route."},shortcut:{vi:"Bỏ cảng chuyển tải khỏi L/C và phát hành ngay để giữ khách.",en:"Remove the transshipment port from the L/C and issue now to keep the client."},wait:{vi:"Treo hồ sơ, không trả lời khách và không báo Tuân thủ.",en:"Park the file, neither answer the client nor alert Compliance."}},questions:{vi:["Vì sao trường 41a phải là BY ACCEPTANCE và số ký quỹ đúng là 78045 USD? Hãy dẫn điều khoản hợp đồng và quy định ký quỹ.","Ngân hàng chịu rủi ro pháp lý, uy tín gì nếu phát hành L/C liên quan cảng bị trừng phạt và bạn xử lý theo quy trình nào?"],en:["Why must field 41a be BY ACCEPTANCE and why is the correct margin 78045 USD? Cite the contract clause and the margin rule.","What legal and reputational risk does the bank face if it issues an L/C involving a sanctioned port, and which procedure do you follow?"]},hints:{vi:["Đọc điều khoản thanh toán: có hối phiếu kỳ hạn hay không, ký phát đòi tiền ai.","Cộng dung sai dương vào trị giá L/C trước khi nhân tỷ lệ ký quỹ ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi dấu hiệu liên quan cấm vận phải chuyển Tuân thủ sàng lọc trước khi phát hành."],en:["Read the payment clause: is there a time draft and on whom is it drawn?","Add the positive tolerance to the L/C amount before applying the margin rate in SOP 3.2.","Re-read SOP 4.2: any sanctions red flag must go to Compliance for screening before issuance."]}},learning:{summary:{vi:"Chuyên viên thanh toán quốc tế và tài trợ thương mại xử lý thư tín dụng (L/C), nhờ thu, chuyển tiền quốc tế, bảo lãnh và tài trợ xuất nhập khẩu: soạn và kiểm tra điện SWIFT, kiểm tra bộ chứng từ theo UCP 600 và ISBP, quản lý ký quỹ, hạn mức và rủi ro cấm vận. Nghề giúp doanh nghiệp giao thương an toàn, đòi hỏi tiếng Anh thương mại, tỉ mỉ từng chi tiết và tuân thủ nghiêm.",en:"A trade finance specialist handles letters of credit (L/C), collections, international transfers, guarantees and import-export financing: drafting and checking SWIFT messages, examining documents under UCP 600 and ISBP, and managing margins, limits and sanctions risk. The role helps businesses trade safely and requires business English, attention to detail and strict compliance."},responsibilities:{vi:["Tiếp nhận đơn mở L/C, đối chiếu hợp đồng và soạn điện MT700, MT707.","Kiểm tra bộ chứng từ xuất trình theo UCP 600, ISBP và điều kiện L/C.","Tính và thu ký quỹ, phí, theo dõi hạn mức tài trợ thương mại của khách hàng.","Xử lý nhờ thu, chuyển tiền quốc tế và bảo lãnh theo URC 522, URDG 758.","Phối hợp Tuân thủ sàng lọc cấm vận và dấu hiệu rửa tiền dựa trên thương mại."],en:["Receive L/C applications, check them against contracts and draft MT700 and MT707.","Examine presented documents under UCP 600, ISBP and the L/C terms.","Calculate and collect margins and fees and track clients' trade finance limits.","Handle collections, international transfers and guarantees under URC 522 and URDG 758.","Work with Compliance on sanctions screening and trade-based money laundering red flags."]},competencies:[{name:{vi:"Thành thạo UCP 600 & ISBP",en:"UCP 600 & ISBP mastery"},desc:{vi:"Vận dụng đúng điều khoản về xuất trình, kiểm tra chứng từ, bảo hiểm, dung sai và thời hạn.",en:"Apply the rules on presentation, examination, insurance, tolerance and deadlines correctly."}},{name:{vi:"Soạn điện SWIFT",en:"SWIFT drafting"},desc:{vi:"Chuyển điều khoản hợp đồng thành các trường MT700 chính xác, nhất quán.",en:"Turn contract terms into accurate, consistent MT700 fields."}},{name:{vi:"Kiểm tra chứng từ",en:"Document examination"},desc:{vi:"Phát hiện bất hợp lệ giữa hóa đơn, vận đơn, bảo hiểm, C/O và L/C trong thời hạn quy định.",en:"Spot discrepancies between invoice, B/L, insurance, C/O and the L/C within the deadline."}},{name:{vi:"Quản trị rủi ro thương mại",en:"Trade risk management"},desc:{vi:"Đánh giá rủi ro đối tác, quốc gia, cấm vận và giá bất thường của hàng hóa.",en:"Assess counterparty, country, sanctions and abnormal pricing risk."}},{name:{vi:"Tuân thủ & liêm chính",en:"Compliance & integrity"},desc:{vi:"Từ chối che giấu thông tin giao dịch, chuyển Tuân thủ mọi dấu hiệu đáng ngờ.",en:"Refuse to hide transaction details and refer every suspicious sign to Compliance."}}],knowledge:{vi:["UCP 600 của ICC về tín dụng chứng từ và ISBP hướng dẫn thực hành kiểm tra chứng từ.","URC 522 về nhờ thu và URDG 758 về bảo lãnh theo yêu cầu.","Incoterms 2020 và mối liên hệ với chứng từ vận tải, bảo hiểm trong L/C.","Chuẩn điện SWIFT MT700, MT707, MT734, MT799 và xu hướng chuyển sang ISO 20022.","Sàng lọc cấm vận và nhận diện rửa tiền dựa trên thương mại (TBML).","Quy định quản lý ngoại hối hiện hành về thanh toán xuất nhập khẩu."],en:["ICC UCP 600 for documentary credits and ISBP for document examination practice.","URC 522 for collections and URDG 758 for demand guarantees.","Incoterms 2020 and their link to transport and insurance documents under an L/C.","SWIFT MT700, MT707, MT734, MT799 and the move to ISO 20022.","Sanctions screening and trade-based money laundering (TBML) detection.","Current foreign exchange rules on import and export payments."]},tools:["SWIFT messaging (MT/MX)","Trade finance module","Sanctions screening system","UCP 600 document checklist","Core Banking","Vessel & port tracking tool"],tools_en:["SWIFT messaging (MT/MX)","Trade finance module","Sanctions screening system","UCP 600 document checklist","Core Banking","Vessel & port tracking tool"],kpis:{vi:["Thời gian phát hành L/C từ khi nhận đủ hồ sơ.","Tỷ lệ điện MT700 phải sửa đổi do lỗi soạn thảo của ngân hàng.","Tỷ lệ kiểm tra chứng từ hoàn tất trong thời hạn 5 ngày làm việc.","Số giao dịch vi phạm cấm vận lọt qua (mục tiêu bằng 0)."],en:["Time to issue an L/C after receiving a complete file.","Share of MT700s amended because of bank drafting errors.","Share of examinations completed within 5 banking days.","Sanctions breaches missed (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra điện SWIFT đến: thông báo L/C, sửa đổi, từ chối chứng từ.",en:"Check incoming SWIFT: L/C advices, amendments and refusals."},{time:"09:30",vi:"Soạn MT700 theo đơn mở L/C, tính ký quỹ và phí.",en:"Draft MT700s from applications and calculate margins and fees."},{time:"11:00",vi:"Kiểm tra bộ chứng từ xuất khẩu, ghi nhận bất hợp lệ.",en:"Examine export document sets and record discrepancies."},{time:"14:00",vi:"Gửi hồ sơ có dấu hiệu cấm vận sang Tuân thủ, trả lời khách hàng.",en:"Send files with sanctions flags to Compliance and reply to clients."},{time:"16:30",vi:"Hạch toán thanh toán, cập nhật hạn mức và lưu hồ sơ giao dịch.",en:"Post settlements, update limits and archive transaction files."}],mistakes:{vi:["Chọn BY PAYMENT cho L/C có hối phiếu kỳ hạn, sai nghĩa vụ thanh toán của ngân hàng.","Tính ký quỹ trên trị giá gốc, bỏ qua dung sai dương của số tiền L/C.","Bỏ qua thông tin cảng chuyển tải, tàu hoặc đối tác có dấu hiệu liên quan cấm vận."],en:["Choosing BY PAYMENT for a credit with a time draft, misstating the bank's obligation.","Computing margin on the base amount and ignoring the positive tolerance.","Overlooking transshipment ports, vessels or parties with sanctions links."]},career:[{vi:"Nhân viên tác nghiệp thanh toán quốc tế",en:"Trade operations officer"},{vi:"Chuyên viên tài trợ thương mại & L/C",en:"Trade finance & L/C specialist"},{vi:"Trưởng phòng Thanh toán Quốc tế",en:"Head of trade finance operations"},{vi:"Giám đốc Sản phẩm Tài trợ Thương mại",en:"Head of trade finance products"}],glossary:[{term:"Usance L/C",vi:"L/C trả chậm: ngân hàng thanh toán sau một thời hạn kể từ ngày xuất trình hoặc ngày vận đơn.",en:"A credit paid after a set period from presentation or B/L date."},{term:"MT700",vi:"Điện SWIFT phát hành thư tín dụng chứng từ, gồm các trường như 32B, 39A, 41a, 42C, 46A.",en:"The SWIFT message that issues a documentary credit, with fields such as 32B, 39A, 41a, 42C, 46A."},{term:"Acceptance",vi:"Ngân hàng chấp nhận hối phiếu kỳ hạn và cam kết trả tiền vào ngày đáo hạn.",en:"The bank accepts a time draft and undertakes to pay it at maturity."},{term:"Tolerance",vi:"Dung sai cho phép về số tiền hoặc số lượng, ví dụ 10/10 tại trường 39A.",en:"Permitted variance in amount or quantity, for example 10/10 in field 39A."},{term:"Sanctions screening",vi:"Sàng lọc tên, tàu, cảng, quốc gia với danh sách cấm vận ngân hàng phải tuân thủ.",en:"Checking names, vessels, ports and countries against the sanctions lists the bank must follow."}],quiz:[{q:{vi:"Theo UCP 600, nếu L/C không quy định khác, số tiền bảo hiểm tối thiểu là bao nhiêu?",en:"Under UCP 600, if the credit is silent, what is the minimum insurance coverage?"},options:{vi:["100% trị giá CIF hoặc CIP","110% trị giá CIF hoặc CIP","120% trị giá FOB","Theo yêu cầu của người bán"],en:["100% of CIF or CIP value","110% of CIF or CIP value","120% of FOB value","Whatever the seller wants"]},answer:1,explain:{vi:"Điều 28 UCP 600 yêu cầu bảo hiểm tối thiểu 110% trị giá CIF hoặc CIP khi L/C không quy định.",en:"UCP 600 Article 28 requires at least 110% of the CIF or CIP value when the credit is silent."}},{q:{vi:"Thời hạn xuất trình mặc định theo UCP 600 khi có chứng từ vận tải gốc là gì?",en:"What is the default presentation period under UCP 600 with original transport documents?"},options:{vi:["7 ngày làm việc","15 ngày","30 ngày","Không muộn hơn 21 ngày lịch sau ngày giao hàng và trong hạn hiệu lực L/C"],en:["7 banking days","15 days","30 days","No later than 21 calendar days after shipment and within the expiry date"]},answer:3,explain:{vi:"Điều 14(c) UCP 600 quy định 21 ngày lịch sau ngày giao hàng nhưng không muộn hơn ngày hết hạn L/C.",en:"UCP 600 Article 14(c) sets 21 calendar days after shipment but not later than the expiry date."}},{q:{vi:"L/C 100000 USD, dung sai +/-5%, tỷ lệ ký quỹ 20%. Số ký quỹ là bao nhiêu?",en:"An L/C of 100000 USD has +/-5% tolerance and a 20% margin rate. What is the margin?"},options:{vi:["21000 USD","20000 USD","19000 USD","25000 USD"],en:["21000 USD","20000 USD","19000 USD","25000 USD"]},answer:0,explain:{vi:"Nghĩa vụ tối đa = 100000 x 1,05 = 105000; ký quỹ = 105000 x 20% = 21000 USD.",en:"Maximum liability = 100000 x 1.05 = 105000; margin = 105000 x 20% = 21000 USD."}},{q:{vi:"Khách đề nghị không ghi cảng chuyển tải có dấu hiệu bị trừng phạt. Bạn làm gì?",en:"A client asks you to omit a transshipment port with sanctions links. What do you do?"},options:{vi:["Làm theo để giữ khách","Ghi một cảng khác gần đó","Giữ thông tin, chuyển Tuân thủ sàng lọc và báo cáo","Phát hành trước rồi báo sau"],en:["Comply to keep the client","Name a nearby port instead","Keep the details, refer to Compliance and escalate","Issue first and report later"]},answer:2,explain:{vi:"Che giấu thông tin để né sàng lọc cấm vận là vi phạm nghiêm trọng; phải giữ nguyên và chuyển Tuân thủ.",en:"Hiding details to evade sanctions screening is a serious breach; keep them and refer to Compliance."}}]}},"KK-174":{scenario:{company:"Whitecrane Bank",supervisor:{name:"Ngô Thanh Hà",role:{vi:"Trưởng phòng Tuân thủ & Phòng chống rửa tiền",en:"Head of Compliance & AML"}},ref_code:"KYC-6092",title:{vi:"Biết khách hàng thật. Biết chủ sở hữu thật.",en:"Know the real customer. Know the real owner."},brief:{vi:"Bạn rà soát hồ sơ KYC-6092 mở tài khoản cho Công ty X. Cổ đông của X: Công ty H nắm 45%, các cổ đông còn lại mỗi người dưới 10%. Ông K, nguyên thứ trưởng của một nước ngoài, nắm 60% Công ty H. Ngưỡng chủ sở hữu hưởng lợi là 25% (trực tiếp hoặc gián tiếp). Bản nháp chỉ xét sở hữu trực tiếp, kết luận không có chủ sở hữu hưởng lợi và áp dụng CDD thông thường. Hãy sửa hai trường và lập báo cáo có căn cứ.",en:"You are reviewing file KYC-6092 to open an account for Company X. X's shareholders: Company H holds 45%, every other shareholder under 10%. Mr. K, a former deputy minister of a foreign country, owns 60% of Company H. The beneficial ownership threshold is 25% (direct or indirect). The draft looks only at direct ownership, finds no beneficial owner and applies standard CDD. Correct both fields and write an evidence-based report."},reference_title:{vi:"Chính sách KYC & sơ đồ sở hữu đã xác minh · KYC-6092",en:"Approved KYC policy & verified ownership chart · KYC-6092"},fields:[{id:"CDD_LEVEL",label:{vi:"Mức độ nhận biết khách hàng",en:"Due diligence level"},initial:"CDD",expected:"EDD",choices:["SDD","CDD","EDD"],reference:"Chính sách đánh giá rủi ro khách hàng",ref_value:{vi:"Rủi ro thấp: SDD; thông thường: CDD; PEP nước ngoài là khách hàng hoặc chủ sở hữu hưởng lợi: EDD",en:"Low risk: SDD; standard: CDD; foreign PEP as customer or beneficial owner: EDD"},hint:{vi:"Xác định chủ sở hữu hưởng lợi trước, rồi kiểm tra người đó có phải người có ảnh hưởng chính trị nước ngoài không.",en:"Identify the beneficial owner first, then check whether that person is a foreign politically exposed person."}},{id:"UBO_PCT",label:{vi:"Tỷ lệ sở hữu gián tiếp của ông K (%)",en:"Mr. K indirect ownership (%)"},initial:"0",expected:"27",reference:"Sơ đồ cơ cấu sở hữu đã xác minh",ref_value:{vi:"Công ty H nắm 45% Công ty X; ông K nắm 60% Công ty H; ngưỡng 25%",en:"Company H holds 45% of Company X; Mr. K holds 60% of Company H; threshold 25%"},hint:{vi:"Sở hữu gián tiếp qua nhiều tầng được tính bằng tích các tỷ lệ dọc theo chuỗi sở hữu.",en:"Indirect ownership through layers is the product of the percentages along the chain."}}],sop32:{vi:"Tỷ lệ sở hữu gián tiếp = tích các tỷ lệ sở hữu qua từng tầng pháp nhân; cá nhân nắm từ 25% trở lên (trực tiếp và gián tiếp cộng lại) là chủ sở hữu hưởng lợi phải nhận biết, xác minh.",en:"Indirect ownership = product of ownership percentages through each legal layer; an individual holding 25% or more (direct plus indirect) is a beneficial owner to identify and verify."},context:{label:"KYC PORTAL / KYC-6092",metrics:[{label:{vi:"Công ty H tại Công ty X",en:"Company H in Company X"},value:"45%"},{label:{vi:"Ông K tại Công ty H",en:"Mr. K in Company H"},value:"60%"},{label:{vi:"Ngưỡng chủ sở hữu hưởng lợi",en:"Beneficial owner threshold"},value:"25%"}]},crisis:{vi:"Giám đốc chi nhánh nhắn: “Khách sẽ chuyển về 50 tỷ đồng tiền gửi trong tuần. Gỡ cờ PEP đi, mở tài khoản theo CDD thông thường ngay hôm nay, hồ sơ nguồn tiền bổ sung sau cũng được.”",en:"The branch director messages you: “The client will bring 50 billion VND of deposits this week. Remove the PEP flag and open the account under standard CDD today, the source of funds can come later.”"},options:{safe:{vi:"Giữ cờ PEP, áp dụng EDD: xác minh nguồn tiền, nguồn tài sản, xin phê duyệt của quản lý cấp cao trước khi mở tài khoản và báo Trưởng phòng Tuân thủ bằng văn bản.",en:"Keep the PEP flag and apply EDD: verify source of funds and wealth, obtain senior management approval before opening and inform the Head of Compliance in writing."},shortcut:{vi:"Gỡ cờ PEP, mở tài khoản ngay và bổ sung hồ sơ nguồn tiền sau.",en:"Remove the PEP flag, open the account now and collect source of funds later."},wait:{vi:"Không xử lý hồ sơ, chờ chi nhánh tự quyết định.",en:"Leave the file untouched and let the branch decide."}},questions:{vi:["Vì sao ông K là chủ sở hữu hưởng lợi với tỷ lệ 27% và hồ sơ phải áp dụng EDD thay vì CDD?","Nếu giao dịch sau khi mở tài khoản có dấu hiệu bất thường, bạn báo cáo thế nào và tránh hành vi tiết lộ thông tin ra sao?"],en:["Why is Mr. K a beneficial owner at 27% and why does the file require EDD instead of CDD?","If transactions after opening look unusual, how do you report them and how do you avoid tipping off the client?"]},hints:{vi:["Vẽ chuỗi sở hữu từ ông K qua Công ty H tới Công ty X và ghi tỷ lệ từng tầng.","Nhân các tỷ lệ theo SOP mục 3.2 rồi so với ngưỡng 25%.","Đọc SOP mục 4.2: không ai được gỡ cờ PEP hay bỏ qua EDD vì áp lực doanh số."],en:["Draw the chain from Mr. K through Company H to Company X and label each layer's percentage.","Multiply the percentages per SOP 3.2, then compare the result with the 25% threshold.","Re-read SOP 4.2: nobody may remove a PEP flag or skip EDD because of sales pressure."]}},learning:{summary:{vi:"Chuyên viên phòng chống rửa tiền và tuân thủ ngân hàng thiết kế và vận hành chương trình nhận biết khách hàng (KYC, CDD), đánh giá rủi ro, giám sát giao dịch, sàng lọc danh sách cấm vận và PEP, điều tra cảnh báo và lập báo cáo giao dịch đáng ngờ gửi cơ quan có thẩm quyền. Nghề bảo vệ ngân hàng khỏi bị lợi dụng cho tội phạm tài chính, đòi hỏi am hiểu luật, tư duy điều tra và bản lĩnh độc lập.",en:"An AML and KYC compliance officer designs and runs the customer due diligence programme, risk assessments, transaction monitoring and sanctions and PEP screening, investigates alerts and files suspicious transaction reports with the authorities. The role protects the bank from being used for financial crime and requires legal knowledge, an investigative mindset and independence."},responsibilities:{vi:["Rà soát hồ sơ KYC, xác định chủ sở hữu hưởng lợi và xếp hạng rủi ro khách hàng.","Sàng lọc khách hàng, giao dịch với danh sách cấm vận, PEP và danh sách đen.","Điều tra cảnh báo giám sát giao dịch, kết luận và lưu hồ sơ điều tra.","Lập báo cáo giao dịch đáng ngờ, giao dịch giá trị lớn đúng hạn, đúng mẫu.","Đào tạo chi nhánh và cập nhật quy trình theo thay đổi pháp luật."],en:["Review KYC files, identify beneficial owners and rate customer risk.","Screen customers and payments against sanctions, PEP and watch lists.","Investigate monitoring alerts, conclude and document each case.","File suspicious and large-value transaction reports on time and in the right format.","Train branches and update procedures as the law changes."]},competencies:[{name:{vi:"Phân tích cơ cấu sở hữu",en:"Ownership analysis"},desc:{vi:"Lần theo chuỗi pháp nhân nhiều tầng để tìm cá nhân thực sự sở hữu, kiểm soát.",en:"Trace multi-layer corporate chains to find the individuals who truly own or control."}},{name:{vi:"Tiếp cận dựa trên rủi ro",en:"Risk-based approach"},desc:{vi:"Áp dụng SDD, CDD, EDD tương xứng với rủi ro khách hàng, sản phẩm, địa bàn.",en:"Apply SDD, CDD or EDD in line with customer, product and geographic risk."}},{name:{vi:"Điều tra giao dịch",en:"Transaction investigation"},desc:{vi:"Nhận diện chia nhỏ giao dịch, luân chuyển vòng tròn, dòng tiền không phù hợp hồ sơ.",en:"Detect structuring, circular flows and activity inconsistent with the profile."}},{name:{vi:"Viết báo cáo pháp lý",en:"Regulatory reporting"},desc:{vi:"Lập báo cáo giao dịch đáng ngờ rõ dữ kiện, căn cứ và lập luận, đúng thời hạn.",en:"Write suspicious transaction reports with clear facts, grounds and reasoning, on time."}},{name:{vi:"Độc lập & bảo mật",en:"Independence & confidentiality"},desc:{vi:"Giữ kết luận trước áp lực kinh doanh và tuyệt đối không tiết lộ việc báo cáo cho khách.",en:"Hold conclusions against sales pressure and never disclose a report to the client."}}],knowledge:{vi:["Luật Phòng, chống rửa tiền số 14/2022/QH15 và Nghị định 19/2023/NĐ-CP hướng dẫn thi hành.","Thông tư 09/2023/TT-NHNN hướng dẫn thực hiện một số điều của Luật Phòng, chống rửa tiền.","Quyết định 11/2023/QĐ-TTg về mức giá trị giao dịch phải báo cáo (400 triệu đồng).","40 Khuyến nghị của FATF và phương pháp tiếp cận dựa trên rủi ro.","Nhận biết chủ sở hữu hưởng lợi, PEP và các biện pháp nhận biết tăng cường (EDD).","Nghĩa vụ báo cáo giao dịch đáng ngờ, lưu trữ hồ sơ và cấm tiết lộ thông tin."],en:["Anti-Money Laundering Law No. 14/2022/QH15 and implementing Decree 19/2023/ND-CP.","Circular 09/2023/TT-NHNN guiding parts of the Anti-Money Laundering Law.","Decision 11/2023/QD-TTg on the reportable transaction threshold (400 million VND).","The FATF 40 Recommendations and the risk-based approach.","Beneficial ownership, PEPs and enhanced due diligence (EDD) measures.","Suspicious transaction reporting, record keeping and the tipping-off prohibition."]},tools:["KYC / eKYC platform","Transaction monitoring system","Sanctions & PEP screening","Case management tool","Ownership mapping tool","Core Banking"],tools_en:["KYC / eKYC platform","Transaction monitoring system","Sanctions & PEP screening","Case management tool","Ownership mapping tool","Core Banking"],kpis:{vi:["Tỷ lệ cảnh báo được xử lý trong thời hạn quy định.","Tỷ lệ báo cáo giao dịch đáng ngờ nộp đúng hạn, đủ căn cứ.","Tỷ lệ hồ sơ khách hàng rủi ro cao được rà soát định kỳ đúng hạn.","Số phát hiện của thanh tra, kiểm toán về phòng chống rửa tiền (mục tiêu bằng 0)."],en:["Share of alerts closed within the required time.","Share of suspicious transaction reports filed on time with sufficient grounds.","Share of high-risk customers reviewed on schedule.","AML findings from inspections or audits (target zero)."]},day:[{time:"08:00",vi:"Xử lý danh sách cảnh báo sàng lọc cấm vận và PEP phát sinh qua đêm.",en:"Work the overnight sanctions and PEP screening alerts."},{time:"09:30",vi:"Rà soát hồ sơ KYC khách hàng doanh nghiệp mới, xác định chủ sở hữu hưởng lợi.",en:"Review new corporate KYC files and identify beneficial owners."},{time:"11:00",vi:"Điều tra cảnh báo giao dịch tiền mặt chia nhỏ tại một chi nhánh.",en:"Investigate a cash structuring alert at a branch."},{time:"14:00",vi:"Soạn báo cáo giao dịch đáng ngờ và trình Trưởng phòng Tuân thủ ký duyệt.",en:"Draft a suspicious transaction report for the Head of Compliance to sign."},{time:"16:30",vi:"Cập nhật danh sách theo dõi và tài liệu đào tạo cho chi nhánh.",en:"Update watch lists and branch training materials."}],mistakes:{vi:["Chỉ xét cổ đông trực tiếp, bỏ sót chủ sở hữu hưởng lợi gián tiếp qua công ty mẹ.","Gỡ cờ PEP hoặc hạ mức nhận biết vì áp lực huy động vốn.","Tiết lộ cho khách hàng hoặc người không có thẩm quyền về việc đã báo cáo giao dịch đáng ngờ."],en:["Looking only at direct shareholders and missing indirect owners through a parent.","Removing a PEP flag or lowering due diligence because of deposit targets.","Telling the client or unauthorised staff that a suspicious transaction report was filed."]},career:[{vi:"Chuyên viên kiểm tra KYC",en:"KYC analyst"},{vi:"Chuyên viên phòng chống rửa tiền",en:"AML compliance officer"},{vi:"Trưởng phòng Phòng chống rửa tiền",en:"Head of AML"},{vi:"Giám đốc Tuân thủ (CCO)",en:"Chief Compliance Officer (CCO)"}],glossary:[{term:"UBO",vi:"Chủ sở hữu hưởng lợi: cá nhân thực sự sở hữu hoặc chi phối khách hàng là pháp nhân.",en:"Ultimate beneficial owner: the individual who truly owns or controls a corporate customer."},{term:"PEP",vi:"Người có ảnh hưởng chính trị, cần biện pháp nhận biết tăng cường do rủi ro tham nhũng.",en:"Politically exposed person, requiring enhanced measures because of corruption risk."},{term:"EDD",vi:"Nhận biết khách hàng tăng cường: xác minh nguồn tiền, nguồn tài sản và phê duyệt cấp cao.",en:"Enhanced due diligence: verifying source of funds and wealth with senior approval."},{term:"STR",vi:"Báo cáo giao dịch đáng ngờ gửi cơ quan phòng chống rửa tiền khi có dấu hiệu nghi vấn.",en:"Suspicious transaction report filed with the AML authority when red flags appear."},{term:"Tipping-off",vi:"Hành vi tiết lộ cho khách hoặc bên ngoài về việc báo cáo, điều tra; bị pháp luật cấm.",en:"Disclosing a report or investigation to the client or outsiders; prohibited by law."}],quiz:[{q:{vi:"Bà M nắm 40% Công ty A; Công ty A nắm 70% Công ty B. Tỷ lệ sở hữu gián tiếp của bà M tại B là bao nhiêu?",en:"Ms. M owns 40% of Company A; Company A owns 70% of Company B. What is Ms. M's indirect stake in B?"},options:{vi:["40%","70%","28%","110%"],en:["40%","70%","28%","110%"]},answer:2,explain:{vi:"Sở hữu gián tiếp = 40% x 70% = 28%, vượt ngưỡng 25% nên bà M là chủ sở hữu hưởng lợi.",en:"Indirect stake = 40% x 70% = 28%, above 25%, so Ms. M is a beneficial owner."}},{q:{vi:"Mức giá trị giao dịch có giá trị lớn phải báo cáo theo quy định hiện hành của Việt Nam là bao nhiêu?",en:"What is Vietnam's current large-value transaction reporting threshold?"},options:{vi:["100 triệu đồng","400 triệu đồng","300 triệu đồng","1 tỷ đồng"],en:["100 million VND","400 million VND","300 million VND","1 billion VND"]},answer:1,explain:{vi:"Quyết định 11/2023/QĐ-TTg quy định mức giao dịch có giá trị lớn phải báo cáo là 400 triệu đồng.",en:"Decision 11/2023/QD-TTg sets the large-value reporting threshold at 400 million VND."}},{q:{vi:"Sau khi gửi báo cáo giao dịch đáng ngờ, RM hỏi có nên báo cho khách biết không. Trả lời đúng là gì?",en:"After a suspicious transaction report is filed, the RM asks whether to tell the client. What is the right answer?"},options:{vi:["Báo khách để giữ quan hệ","Chỉ báo nếu khách là VIP","Báo sau khi khách rút hết tiền","Không, tiết lộ việc báo cáo là hành vi bị cấm; giữ bí mật và tiếp tục giám sát"],en:["Tell the client to keep the relationship","Tell only VIP clients","Tell after the client withdraws","No, disclosure is prohibited; keep it confidential and keep monitoring"]},answer:3,explain:{vi:"Pháp luật cấm tiết lộ việc báo cáo giao dịch đáng ngờ để không cản trở điều tra.",en:"The law forbids disclosing a suspicious transaction report so investigations are not compromised."}},{q:{vi:"Trường hợp nào bắt buộc áp dụng nhận biết khách hàng tăng cường (EDD)?",en:"Which case always requires enhanced due diligence (EDD)?"},options:{vi:["Khách hàng hoặc chủ sở hữu hưởng lợi là PEP nước ngoài","Mọi khách hàng mở tài khoản mới","Khách gửi tiết kiệm dưới 10 triệu đồng","Nhân viên của chính ngân hàng"],en:["The customer or beneficial owner is a foreign PEP","Every new account holder","Savers depositing under 10 million VND","The bank's own employees"]},answer:0,explain:{vi:"Theo FATF và pháp luật phòng chống rửa tiền, PEP nước ngoài luôn thuộc nhóm phải áp dụng biện pháp tăng cường.",en:"Under FATF and AML law, foreign PEPs always require enhanced measures."}}]}},"KK-175":{scenario:{company:"Pinehill Bank",supervisor:{name:"Phan Thị Ngọc Mai",role:{vi:"Kiểm soát viên Giao dịch",en:"Teller Supervisor"}},ref_code:"STK-3305",title:{vi:"Đúng lãi suất. Đúng tiền. Đúng khách hàng.",en:"Right rate. Right amount. Right customer."},brief:{vi:"Khách hàng 72 tuổi đến tất toán trước hạn sổ tiết kiệm STK-3305: gốc 365000000 đồng, kỳ hạn 6 tháng, lãi suất 5,6%/năm, đã gửi 120 ngày. Biểu lãi suất của ngân hàng: rút trước hạn hưởng lãi suất không kỳ hạn 0,2%/năm (số liệu mô phỏng), tính theo số ngày thực tế/365. Phiếu chi nháp áp lãi suất kỳ hạn. Hãy sửa lãi suất áp dụng và tiền lãi, giải thích rõ cho khách, rồi lập báo cáo.",en:"A 72-year-old customer wants to close savings book STK-3305 early: principal 365000000 VND, 6-month term at 5.6% per year, held for 120 days. The bank's rate sheet: early withdrawal earns the demand deposit rate of 0.2% per year (training data), actual days/365. The draft payout slip applies the term rate. Correct the applied rate and the interest, explain it clearly to the customer, then report."},reference_title:{vi:"Biểu lãi suất & phiếu tính lãi đã duyệt · STK-3305",en:"Approved rate sheet & interest slip · STK-3305"},fields:[{id:"RATE_APPLIED",label:{vi:"Lãi suất áp dụng (%/năm)",en:"Applied rate (% per year)"},initial:"5.6%",expected:"0.2%",choices:["5.6%","2.9%","0.2%"],reference:"Biểu lãi suất tiền gửi hiện hành",ref_value:{vi:"Đúng hạn 6 tháng: 5,6%; kỳ hạn 3 tháng: 2,9%; rút trước hạn: lãi suất không kỳ hạn 0,2%",en:"6-month at maturity: 5.6%; 3-month term: 2.9%; early withdrawal: demand rate 0.2%"},hint:{vi:"Rút trước hạn không được hưởng lãi suất kỳ hạn đã cam kết, kể cả kỳ hạn ngắn hơn đã trôi qua.",en:"An early withdrawal earns neither the committed term rate nor a shorter term already elapsed."}},{id:"INTEREST_VND",label:{vi:"Tiền lãi trả khách (đồng)",en:"Interest paid (VND)"},initial:"6720000",expected:"240000",reference:"Phiếu tính lãi rút trước hạn",ref_value:{vi:"Gốc 365000000 đồng; đã gửi 120 ngày; cơ sở tính 365 ngày",en:"Principal 365000000 VND; 120 days held; 365-day basis"},hint:{vi:"Nhân gốc với lãi suất năm đúng, rồi nhân số ngày thực gửi và chia 365.",en:"Multiply the principal by the correct annual rate, then by actual days and divide by 365."}}],sop32:{vi:"Tiền lãi = số tiền gốc x lãi suất áp dụng (%/năm) x số ngày gửi thực tế / 365; rút trước hạn áp dụng lãi suất không kỳ hạn theo biểu lãi suất tại ngày rút.",en:"Interest = principal x applied annual rate x actual days held / 365; early withdrawal uses the demand deposit rate on the sheet at the withdrawal date."},context:{label:"CORE BANKING / STK-3305",metrics:[{label:{vi:"Số tiền gốc",en:"Principal"},value:"365,000,000 VND"},{label:{vi:"Số ngày đã gửi",en:"Days held"},value:"120"},{label:{vi:"Lãi suất kỳ hạn",en:"Term rate"},value:"5.6%"}]},crisis:{vi:"Khách vừa nghe điện thoại vừa giục: “Bên công an bảo phải chuyển ngay toàn bộ tiền vào tài khoản tạm giữ này để phục vụ điều tra, cấm nói với ai.” Hàng chờ phía sau phàn nàn và đề nghị bạn làm nhanh cho xong.",en:"The customer, still on the phone, urges you: “The police told me to move all the money into this holding account for an investigation and to tell no one.” People in the queue complain and ask you to just get it done."},options:{safe:{vi:"Tạm dừng lệnh chuyển theo quy trình phòng chống lừa đảo, báo kiểm soát viên, giải thích dấu hiệu giả danh cơ quan chức năng và hỗ trợ khách liên hệ người thân hoặc công an qua số chính thức.",en:"Pause the transfer under the anti-fraud procedure, alert the supervisor, explain the impersonation red flags and help the customer contact family or the police on an official number."},shortcut:{vi:"Làm nhanh theo yêu cầu vì tiền là của khách và hàng chờ đang dài.",en:"Process it quickly because it is the customer's money and the queue is long."},wait:{vi:"Trả lại sổ, bảo khách tự quyết định và không báo cho ai.",en:"Hand back the book, tell the customer to decide alone and alert no one."}},questions:{vi:["Hãy giải thích cho khách vì sao tiền lãi chỉ còn 240000 đồng thay vì 6720000 đồng, dựa trên biểu lãi suất và cách tính.","Những dấu hiệu nào cho thấy khách đang bị lừa đảo và bạn phối hợp với ai để bảo vệ khách mà vẫn tôn trọng quyền của khách?"],en:["Explain to the customer why the interest is only 240000 VND instead of 6720000 VND, using the rate sheet and the formula.","Which signs show the customer is being scammed, and whom do you involve to protect them while respecting their rights?"]},hints:{vi:["Đối chiếu tình trạng rút trước hạn với từng dòng của biểu lãi suất.","Áp lãi suất đúng vào công thức số ngày thực tế/365 ở SOP mục 3.2.","Đọc SOP mục 4.2: giao dịch có dấu hiệu lừa đảo phải tạm dừng và báo kiểm soát viên ngay."],en:["Match the early withdrawal status with each line of the rate sheet.","Apply the correct rate in the actual days/365 formula in SOP 3.2.","Re-read SOP 4.2: a transaction with fraud signs must be paused and reported to the supervisor at once."]}},learning:{summary:{vi:"Giao dịch viên ngân hàng là gương mặt đầu tiên của chi nhánh: mở tài khoản, nhận gửi và chi trả tiền gửi, chuyển tiền, thu đổi ngoại tệ, kiểm đếm tiền mặt và hướng dẫn khách dùng dịch vụ số. Nghề đòi hỏi chính xác tuyệt đối với tiền và chứng từ, giải thích dễ hiểu cho mọi khách hàng, nhận diện giấy tờ giả, thủ đoạn lừa đảo và tuân thủ nguyên tắc kiểm soát kép.",en:"A bank teller is the first face of the branch: opening accounts, taking and paying out deposits, making transfers, exchanging currency, counting cash and guiding customers to digital services. The role demands absolute accuracy with cash and documents, clear explanations for every customer, detection of forged papers and scams, and strict maker-checker discipline."},responsibilities:{vi:["Nhận biết khách hàng, kiểm tra giấy tờ tùy thân và thẩm quyền giao dịch.","Thực hiện gửi, rút, tất toán tiền gửi và tính lãi đúng biểu lãi suất.","Xử lý chuyển tiền, thu đổi ngoại tệ, nộp rút tiền mặt theo hạn mức được giao.","Tư vấn sản phẩm cơ bản, hướng dẫn khách dùng ngân hàng số an toàn.","Kiểm quỹ cuối ngày, đối chiếu chứng từ và bàn giao cho kiểm soát viên."],en:["Identify customers and check ID and signing authority.","Process deposits, withdrawals and closures and calculate interest per the rate sheet.","Handle transfers, currency exchange and cash within assigned limits.","Advise on basic products and guide customers to use digital banking safely.","Balance the cash drawer, reconcile vouchers and hand over to the supervisor."]},competencies:[{name:{vi:"Chính xác nghiệp vụ",en:"Operational accuracy"},desc:{vi:"Tính lãi, phí, tỷ giá và kiểm đếm tiền không sai sót, lập chứng từ đúng mẫu.",en:"Calculate interest, fees and rates and count cash without error, with correct vouchers."}},{name:{vi:"Giao tiếp khách hàng",en:"Customer communication"},desc:{vi:"Giải thích quy định, tiền lãi, phí bằng ngôn ngữ dễ hiểu, kiên nhẫn với người cao tuổi.",en:"Explain rules, interest and fees in plain words, patiently with elderly customers."}},{name:{vi:"Nhận diện gian lận",en:"Fraud detection"},desc:{vi:"Phát hiện giấy tờ giả, ủy quyền không hợp lệ, khách bị dẫn dắt chuyển tiền.",en:"Spot forged IDs, invalid mandates and customers coached into transfers."}},{name:{vi:"Tuân thủ quy trình",en:"Procedure compliance"},desc:{vi:"Thực hiện đúng kiểm soát kép, hạn mức giao dịch và quy định nhận biết khách hàng.",en:"Follow maker-checker controls, transaction limits and customer identification rules."}},{name:{vi:"Bình tĩnh dưới áp lực",en:"Composure under pressure"},desc:{vi:"Giữ đúng quy trình khi hàng chờ dài, khách nóng giận hoặc bị thúc ép.",en:"Stick to procedure when queues are long or customers are upset or pressured."}}],knowledge:{vi:["Thông tư 48/2018/TT-NHNN về tiền gửi tiết kiệm (sửa đổi bởi Thông tư 04/2022/TT-NHNN) và quy định rút trước hạn.","Thông tư 14/2017/TT-NHNN về phương pháp tính lãi trong hoạt động nhận tiền gửi, cấp tín dụng.","Quy định hiện hành về nhận biết khách hàng, xác thực giấy tờ tùy thân và sinh trắc học.","Nhận biết tiền thật, tiền giả; quy trình kiểm đếm, đóng gói và bàn giao quỹ cuối ngày.","Thủ đoạn lừa đảo phổ biến: giả danh cơ quan chức năng, chiếm đoạt OTP, chuyển tiền bất thường."],en:["Circular 48/2018/TT-NHNN on savings deposits (amended by Circular 04/2022/TT-NHNN) and early withdrawal rules.","Circular 14/2017/TT-NHNN on interest calculation for deposits and credit.","Current rules on customer identification, ID verification and biometrics.","Detecting counterfeit notes; counting, bundling and end-of-day cash handover.","Common scams: impersonating authorities, OTP theft and unusual transfer requests."]},tools:["Core Banking teller module","Queue management system","Cash counter & counterfeit detector","Chip ID & biometric reader","Rate sheet & fee schedule","Fraud alert checklist"],tools_en:["Core Banking teller module","Queue management system","Cash counter & counterfeit detector","Chip ID & biometric reader","Rate sheet & fee schedule","Fraud alert checklist"],kpis:{vi:["Số giao dịch sai sót phải điều chỉnh (mục tiêu bằng 0).","Thời gian phục vụ trung bình mỗi khách.","Điểm hài lòng của khách hàng tại quầy.","Số vụ lừa đảo được phát hiện và ngăn chặn kịp thời."],en:["Transactions needing correction (target zero).","Average service time per customer.","Counter customer satisfaction score.","Scams detected and stopped in time."]},day:[{time:"07:45",vi:"Nhận quỹ đầu ngày, kiểm đếm và ký biên bản với thủ quỹ.",en:"Receive the opening cash float, count it and sign off with the vault teller."},{time:"08:00",vi:"Mở quầy, phục vụ gửi rút tiết kiệm, chuyển tiền và mở tài khoản.",en:"Open the counter for savings, transfers and new accounts."},{time:"11:30",vi:"Trình kiểm soát viên duyệt các giao dịch vượt hạn mức.",en:"Submit over-limit transactions to the supervisor for approval."},{time:"14:00",vi:"Hướng dẫn khách cài đặt ngân hàng số và cảnh báo thủ đoạn lừa đảo.",en:"Help customers set up digital banking and warn them about scams."},{time:"16:30",vi:"Kiểm quỹ cuối ngày, đối chiếu chứng từ và nộp quỹ.",en:"Balance the drawer, reconcile vouchers and return the cash."}],mistakes:{vi:["Áp lãi suất kỳ hạn cho khoản rút trước hạn, chi thừa tiền lãi.","Chi tiền cho người không có ủy quyền hợp lệ dù mang đủ giấy tờ của chủ tài khoản.","Làm nhanh giao dịch chuyển tiền bất thường của người cao tuổi mà không hỏi han, cảnh báo."],en:["Paying the term rate on an early withdrawal, overpaying interest.","Paying someone without a valid mandate even if they hold the owner's papers.","Rushing an unusual transfer for an elderly customer without asking or warning."]},career:[{vi:"Giao dịch viên",en:"Bank teller"},{vi:"Giao dịch viên cao cấp / Chuyên viên dịch vụ khách hàng",en:"Senior teller / Customer service officer"},{vi:"Kiểm soát viên giao dịch",en:"Teller supervisor"},{vi:"Trưởng phòng Giao dịch / Phó giám đốc chi nhánh",en:"Branch operations manager / Deputy branch director"}],glossary:[{term:"Demand deposit rate",vi:"Lãi suất không kỳ hạn, thường áp dụng khi khách rút tiền gửi có kỳ hạn trước hạn.",en:"The non-term rate, usually paid when a term deposit is withdrawn early."},{term:"Early withdrawal",vi:"Rút một phần hoặc toàn bộ tiền gửi có kỳ hạn trước ngày đến hạn.",en:"Withdrawing part or all of a term deposit before its maturity date."},{term:"Maker-checker",vi:"Nguyên tắc kiểm soát kép: một người lập giao dịch, người khác kiểm tra và phê duyệt.",en:"Dual control: one person enters a transaction and another checks and approves it."},{term:"Biometric authentication",vi:"Xác thực khách hàng bằng đặc điểm sinh trắc như khuôn mặt, vân tay so với dữ liệu căn cước.",en:"Verifying customers by face or fingerprint against ID records."},{term:"Impersonation scam",vi:"Lừa đảo giả danh công an, ngân hàng, cơ quan thuế để ép nạn nhân chuyển tiền.",en:"A scam where fraudsters pose as police, banks or tax officers to force transfers."}],quiz:[{q:{vi:"Gốc 100000000 đồng, rút trước hạn sau 73 ngày, lãi suất không kỳ hạn 0,5%/năm, cơ sở 365 ngày. Tiền lãi là bao nhiêu?",en:"Principal 100000000 VND, early withdrawal after 73 days, demand rate 0.5% per year, 365-day basis. What is the interest?"},options:{vi:["500000 đồng","100000 đồng","73000 đồng","1000000 đồng"],en:["500000 VND","100000 VND","73000 VND","1000000 VND"]},answer:1,explain:{vi:"Tiền lãi = 100000000 x 0,5% x 73 / 365 = 100000 đồng.",en:"Interest = 100000000 x 0.5% x 73 / 365 = 100000 VND."}},{q:{vi:"Một người mang căn cước và sổ tiết kiệm của mẹ đến rút tiền, không có giấy ủy quyền. Bạn làm gì?",en:"Someone brings their mother's ID and savings book to withdraw, with no power of attorney. What do you do?"},options:{vi:["Chi tiền vì có đủ giấy tờ gốc","Gọi điện cho người mẹ rồi chi","Từ chối chi, hướng dẫn thủ tục ủy quyền hợp lệ theo quy định","Chi một nửa số tiền"],en:["Pay because the originals are present","Call the mother and then pay","Decline and explain the valid mandate procedure","Pay half the amount"]},answer:2,explain:{vi:"Chỉ chủ tài khoản hoặc người được ủy quyền hợp pháp mới được rút tiền; giấy tờ gốc không thay thế ủy quyền.",en:"Only the owner or a lawful attorney may withdraw; holding originals is not a mandate."}},{q:{vi:"Khách cao tuổi đòi chuyển toàn bộ tiền vào “tài khoản tạm giữ của công an”. Phản ứng đúng là gì?",en:"An elderly customer insists on moving all savings to a “police holding account”. What is the right response?"},options:{vi:["Tạm dừng, báo kiểm soát viên, giải thích dấu hiệu lừa đảo và hỗ trợ khách xác minh qua kênh chính thức","Chuyển ngay vì là tiền của khách","Từ chối thẳng và mời khách ra về","Xin số tài khoản rồi tự chuyển giúp"],en:["Pause, alert the supervisor, explain the scam signs and help verify via official channels","Transfer at once because it is the customer's money","Refuse bluntly and send the customer away","Take the account number and transfer it yourself"]},answer:0,explain:{vi:"Cơ quan chức năng không yêu cầu chuyển tiền vào tài khoản tạm giữ qua điện thoại; giao dịch viên phải tạm dừng và báo cáo.",en:"Authorities never ask for transfers to holding accounts by phone; the teller must pause and escalate."}},{q:{vi:"Cuối ngày quỹ tiền mặt thừa 500000 đồng so với sổ. Xử lý đúng là gì?",en:"At day end the cash drawer is 500000 VND over the books. What is correct?"},options:{vi:["Giữ lại để bù lần thiếu sau","Chia cho cả tổ","Bỏ vào quỹ chung không ghi chép","Lập biên bản, báo kiểm soát viên và hạch toán chờ xử lý theo quy trình"],en:["Keep it to cover a future shortage","Share it with the team","Drop it in a common fund unrecorded","Record it, report to the supervisor and post it to suspense per procedure"]},answer:3,explain:{vi:"Mọi chênh lệch quỹ phải được lập biên bản, báo cáo và hạch toán minh bạch để tìm nguyên nhân.",en:"Every cash difference must be recorded, reported and posted transparently to find the cause."}}]}},"KK-176":{scenario:{company:"Harborlight Insurance",supervisor:{name:"Bùi Văn Khánh",role:{vi:"Trưởng phòng Giám định Bồi thường",en:"Claims Manager"}},ref_code:"CLM-7742",title:{vi:"Đúng nguyên nhân. Đúng tỷ lệ. Đúng bồi thường.",en:"Right cause. Right ratio. Right settlement."},brief:{vi:"Bạn giám định hồ sơ CLM-7742: cháy kho hàng do chập điện. Thiệt hại do lửa 760 triệu đồng, hàng hư hỏng do nước chữa cháy 480 triệu đồng. Số tiền bảo hiểm 6300 triệu đồng, giá trị thực tế tài sản tại thời điểm tổn thất 8400 triệu đồng, mức khấu trừ 25 triệu đồng mỗi vụ (số liệu mô phỏng). Bản nháp xếp thiệt hại do nước vào rủi ro lũ lụt không được bảo hiểm và chưa áp dụng bảo hiểm dưới giá trị. Hãy sửa hai trường và lập báo cáo.",en:"You are adjusting claim CLM-7742: a warehouse fire caused by an electrical short circuit. Fire damage is 760 million VND and goods damaged by firefighting water 480 million VND. Sum insured 6300 million VND, actual value of the property at the time of loss 8400 million VND, deductible 25 million VND per event (training data). The draft treats the water damage as uninsured flood and ignores underinsurance. Correct both fields and report."},reference_title:{vi:"Biên bản giám định & bảng tính bồi thường đã duyệt · CLM-7742",en:"Approved survey report & settlement worksheet · CLM-7742"},fields:[{id:"CAUSE_CODE",label:{vi:"Nguyên nhân trực tiếp của thiệt hại do nước",en:"Proximate cause of the water damage"},initial:"FLOOD",expected:"FIRE",choices:["FIRE","FLOOD","WATER LEAK"],reference:"Biên bản giám định hiện trường",ref_value:{vi:"Nước từ vòi chữa cháy của lực lượng phòng cháy chữa cháy phun vào kho trong lúc dập lửa",en:"Water from fire brigade hoses sprayed into the warehouse while the fire was being put out"},hint:{vi:"Áp dụng nguyên tắc nguyên nhân trực tiếp: tìm sự kiện khởi phát chuỗi tổn thất.",en:"Apply proximate cause: find the event that set the chain of loss in motion."}},{id:"CLAIM_MVND",label:{vi:"Số tiền bồi thường (triệu đồng)",en:"Claim settlement (million VND)"},initial:"735",expected:"905",reference:"Bảng tính bồi thường",ref_value:{vi:"Tổn thất do lửa 760 + do nước chữa cháy 480; STBH 6300; giá trị thực tế 8400; khấu trừ 25",en:"Fire loss 760 + firefighting water 480; sum insured 6300; actual value 8400; deductible 25"},hint:{vi:"Khi số tiền bảo hiểm thấp hơn giá trị thực tế, bồi thường theo tỷ lệ trước khi trừ mức khấu trừ.",en:"When the sum insured is below actual value, apply the pro rata ratio before the deductible."}}],sop32:{vi:"Bồi thường = tổn thất thuộc phạm vi bảo hiểm x (số tiền bảo hiểm / giá trị thực tế tại thời điểm tổn thất) - mức khấu trừ; nếu số tiền bảo hiểm bằng hoặc cao hơn giá trị thực tế thì không áp tỷ lệ.",en:"Settlement = insured loss x (sum insured / actual value at the time of loss) - deductible; no ratio applies if the sum insured equals or exceeds actual value."},context:{label:"CLAIMS SYSTEM / CLM-7742",metrics:[{label:{vi:"Số tiền bảo hiểm",en:"Sum insured"},value:"6,300,000,000 VND"},{label:{vi:"Giá trị thực tế",en:"Actual value"},value:"8,400,000,000 VND"},{label:{vi:"Mức khấu trừ",en:"Deductible"},value:"25,000,000 VND"}]},crisis:{vi:"Đại diện bên được bảo hiểm đề nghị: “Anh ghi thêm lô hàng ẩm mốc tồn từ năm ngoái vào biên bản thiệt hại do nước, công ty em gửi anh 5% số tiền bồi thường. Đại lý cũng muốn giữ khách lớn này.”",en:"The insured's representative proposes: “Add last year's mouldy stock to the water damage report and my company will give you 5% of the settlement. The agent also wants to keep this big client.”"},options:{safe:{vi:"Từ chối, chỉ ghi nhận thiệt hại đã xác minh bằng chứng từ và hiện trường, báo Trưởng phòng Bồi thường và bộ phận chống trục lợi bảo hiểm bằng văn bản.",en:"Refuse, record only losses verified by documents and site evidence, and report in writing to the Claims Manager and the insurance fraud unit."},shortcut:{vi:"Ghi thêm lô hàng cũ để giữ khách lớn và giải quyết hồ sơ nhanh.",en:"Add the old stock to keep the big client and close the claim fast."},wait:{vi:"Ngừng giám định, chờ đại lý và khách tự thống nhất số liệu.",en:"Stop the adjustment and wait for the agent and the client to agree on figures."}},questions:{vi:["Vì sao thiệt hại do nước chữa cháy thuộc rủi ro cháy và số bồi thường là 905 triệu đồng? Trình bày từng bước tính.","Đề nghị ghi thêm hàng tồn cũ là hành vi gì theo pháp luật kinh doanh bảo hiểm và bạn bảo vệ hồ sơ bằng những bằng chứng nào?"],en:["Why does firefighting water damage fall under the fire peril and why is the settlement 905 million VND? Show each step.","What does adding old stock amount to under insurance law, and which evidence protects the claim file?"]},hints:{vi:["Xác định chuỗi sự kiện từ chập điện, cháy đến phun nước chữa cháy rồi tìm nguyên nhân trực tiếp.","So sánh số tiền bảo hiểm với giá trị thực tế, áp tỷ lệ rồi mới trừ khấu trừ ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi đề nghị khai khống tổn thất phải từ chối và báo bộ phận chống trục lợi."],en:["Trace the chain from short circuit to fire to firefighting water, then find the proximate cause.","Compare the sum insured with actual value, apply the ratio, then the deductible in SOP 3.2.","Re-read SOP 4.2: any request to inflate a loss must be refused and reported to the fraud unit."]}},learning:{summary:{vi:"Chuyên viên giám định bồi thường bảo hiểm khảo sát hiện trường, xác định nguyên nhân và mức độ tổn thất, đối chiếu phạm vi bảo hiểm và điều khoản loại trừ, tính số tiền bồi thường và thương lượng với khách hàng, nhà thầu sửa chữa. Nghề bảo đảm khách hàng được bồi thường công bằng, doanh nghiệp bảo hiểm không bị trục lợi, đòi hỏi kiến thức kỹ thuật, pháp lý, kỹ năng điều tra và tính chính trực.",en:"An insurance claims adjuster surveys the loss site, establishes the cause and extent of damage, checks cover and exclusions, calculates the settlement and negotiates with the insured and repairers. The role ensures fair compensation for customers and protects insurers from fraud, and requires technical and legal knowledge, investigative skills and integrity."},responsibilities:{vi:["Tiếp nhận thông báo tổn thất, hướng dẫn khách hạn chế thiệt hại và giữ hiện trường.","Khảo sát hiện trường, chụp ảnh, thu thập biên bản phòng cháy chữa cháy và chứng từ.","Xác định nguyên nhân trực tiếp, phạm vi bảo hiểm và điều khoản loại trừ áp dụng.","Tính số tiền bồi thường theo giá trị thực tế, bảo hiểm dưới giá trị và mức khấu trừ.","Lập báo cáo giám định, đề xuất phương án và phối hợp thu hồi từ bên thứ ba."],en:["Receive loss notices, guide the insured to mitigate damage and preserve the site.","Survey the site, take photos and collect fire brigade reports and records.","Establish the proximate cause, the cover and applicable exclusions.","Calculate the settlement using actual value, underinsurance and the deductible.","Write the adjustment report, propose the settlement and support recovery from third parties."]},competencies:[{name:{vi:"Điều tra nguyên nhân",en:"Cause investigation"},desc:{vi:"Dựng lại chuỗi sự kiện từ chứng cứ hiện trường để xác định nguyên nhân trực tiếp.",en:"Rebuild the chain of events from site evidence to determine the proximate cause."}},{name:{vi:"Đọc hiểu hợp đồng bảo hiểm",en:"Policy interpretation"},desc:{vi:"Áp dụng đúng phạm vi, rủi ro mở rộng, điều khoản loại trừ và điều kiện đặc biệt.",en:"Apply cover, extensions, exclusions and special conditions correctly."}},{name:{vi:"Định lượng tổn thất",en:"Loss quantification"},desc:{vi:"Xác định giá trị thực tế, khấu hao, tỷ lệ bảo hiểm dưới giá trị và giá trị thu hồi.",en:"Determine actual value, depreciation, underinsurance ratio and salvage."}},{name:{vi:"Đàm phán bồi thường",en:"Settlement negotiation"},desc:{vi:"Giải thích căn cứ bồi thường minh bạch và đạt thỏa thuận công bằng với khách hàng.",en:"Explain the basis of settlement transparently and reach a fair agreement."}},{name:{vi:"Chống trục lợi",en:"Fraud prevention"},desc:{vi:"Nhận diện khai khống, hàng cũ, chứng từ giả và từ chối mọi lợi ích cá nhân.",en:"Detect inflated claims, old stock and fake documents, and refuse any personal benefit."}}],knowledge:{vi:["Luật Kinh doanh bảo hiểm số 08/2022/QH15 và các văn bản hướng dẫn.","Nguyên tắc cơ bản của bảo hiểm: trung thực tuyệt đối, quyền lợi có thể được bảo hiểm, bồi thường, thế quyền, nguyên nhân trực tiếp.","Bảo hiểm dưới giá trị, trên giá trị, bảo hiểm trùng và cách phân bổ bồi thường theo tỷ lệ.","Quy định hiện hành về bảo hiểm cháy, nổ bắt buộc đối với cơ sở có nguy hiểm về cháy, nổ.","Kỹ thuật giám định: thu thập chứng cứ, ảnh hiện trường, biên bản phòng cháy chữa cháy, sổ kho."],en:["The Law on Insurance Business No. 08/2022/QH15 and its guiding documents.","Core principles: utmost good faith, insurable interest, indemnity, subrogation and proximate cause.","Underinsurance, overinsurance, double insurance and pro rata apportionment.","Current compulsory fire and explosion insurance rules for high-risk premises.","Adjustment techniques: evidence collection, site photos, fire brigade reports and stock records."]},tools:["Claims management system","Site survey app (photo, GPS)","Moisture meter & thermal camera","Stock reconciliation sheet","Loss adjustment calculator","Fraud red flag checklist"],tools_en:["Claims management system","Site survey app (photo, GPS)","Moisture meter & thermal camera","Stock reconciliation sheet","Loss adjustment calculator","Fraud red flag checklist"],kpis:{vi:["Thời gian giải quyết hồ sơ bồi thường trung bình.","Tỷ lệ hồ sơ bị khiếu nại hoặc điều chỉnh sau khi duyệt.","Số hồ sơ trục lợi được phát hiện và ngăn chặn.","Độ lệch giữa số dự phòng ban đầu và số bồi thường cuối cùng."],en:["Average claim settlement time.","Share of claims disputed or adjusted after approval.","Fraudulent claims detected and stopped.","Gap between the initial reserve and the final settlement."]},day:[{time:"08:00",vi:"Nhận thông báo tổn thất mới, lập dự phòng ban đầu và lịch khảo sát.",en:"Log new loss notices, set initial reserves and schedule surveys."},{time:"09:30",vi:"Khảo sát hiện trường kho bị cháy, chụp ảnh và lấy lời khai.",en:"Survey the burned warehouse, take photos and interview witnesses."},{time:"13:30",vi:"Đối chiếu sổ kho, hóa đơn với hàng hư hỏng thực tế.",en:"Match stock records and invoices with the actual damaged goods."},{time:"15:00",vi:"Tính bồi thường, áp bảo hiểm dưới giá trị và mức khấu trừ.",en:"Calculate the settlement with underinsurance and the deductible."},{time:"16:30",vi:"Hoàn thiện báo cáo giám định và trao đổi với khách hàng.",en:"Finalise the adjustment report and discuss it with the insured."}],mistakes:{vi:["Loại trừ thiệt hại do nước chữa cháy vì nhầm với rủi ro lũ lụt.","Bỏ qua bảo hiểm dưới giá trị, bồi thường toàn bộ tổn thất khi số tiền bảo hiểm thấp hơn giá trị thực tế.","Ghi nhận hàng tồn cũ hoặc tổn thất không có chứng cứ vào biên bản theo đề nghị của khách."],en:["Excluding firefighting water damage by confusing it with flood.","Ignoring underinsurance and paying the full loss when the sum insured is below actual value.","Recording old stock or unproven losses at the insured's request."]},career:[{vi:"Nhân viên giám định bồi thường",en:"Claims assistant"},{vi:"Chuyên viên giám định bồi thường",en:"Claims adjuster"},{vi:"Chuyên viên giám định cao cấp tài sản kỹ thuật",en:"Senior property and engineering adjuster"},{vi:"Trưởng phòng / Giám đốc Bồi thường",en:"Claims manager / Head of claims"}],glossary:[{term:"Proximate cause",vi:"Nguyên nhân trực tiếp, chủ động và hiệu quả gây ra chuỗi sự kiện dẫn đến tổn thất.",en:"The dominant, effective cause that sets in motion the events leading to a loss."},{term:"Underinsurance",vi:"Bảo hiểm dưới giá trị: số tiền bảo hiểm thấp hơn giá trị thực tế, bồi thường theo tỷ lệ.",en:"Sum insured below actual value, so claims are paid pro rata."},{term:"Deductible",vi:"Mức khấu trừ: phần tổn thất bên được bảo hiểm tự chịu trong mỗi vụ.",en:"The part of each loss borne by the insured."},{term:"Subrogation",vi:"Thế quyền: sau khi bồi thường, doanh nghiệp bảo hiểm được đòi bên thứ ba có lỗi.",en:"After paying, the insurer may recover from the liable third party."},{term:"Utmost good faith",vi:"Trung thực tuyệt đối: các bên phải khai báo đầy đủ, trung thực mọi thông tin trọng yếu.",en:"Both parties must disclose all material facts fully and honestly."}],quiz:[{q:{vi:"Số tiền bảo hiểm 3000 triệu, giá trị thực tế 4000 triệu, tổn thất 800 triệu, không có khấu trừ. Số bồi thường là bao nhiêu?",en:"Sum insured 3000 million, actual value 4000 million, loss 800 million, no deductible. What is the settlement?"},options:{vi:["800 triệu","600 triệu","3000 triệu","200 triệu"],en:["800 million","600 million","3000 million","200 million"]},answer:1,explain:{vi:"Bồi thường = 800 x 3000 / 4000 = 600 triệu đồng do bảo hiểm dưới giá trị.",en:"Settlement = 800 x 3000 / 4000 = 600 million because of underinsurance."}},{q:{vi:"Trong bảo hiểm cháy, thiệt hại do nước dùng để chữa cháy được xử lý thế nào?",en:"Under a fire policy, how is damage from water used to fight the fire treated?"},options:{vi:["Luôn bị loại trừ","Thuộc rủi ro lũ lụt","Chỉ bồi thường khi mua thêm bảo hiểm nước","Được coi là hậu quả của rủi ro cháy theo nguyên nhân trực tiếp"],en:["Always excluded","Treated as flood","Paid only with extra water cover","Treated as a consequence of the fire under proximate cause"]},answer:3,explain:{vi:"Nước chữa cháy là hậu quả tất yếu của việc dập lửa nên thiệt hại thuộc rủi ro cháy.",en:"Firefighting water is a direct consequence of extinguishing the fire, so the damage falls under the fire peril."}},{q:{vi:"Nguyên tắc thế quyền cho phép doanh nghiệp bảo hiểm làm gì?",en:"What does subrogation allow the insurer to do?"},options:{vi:["Đòi bên thứ ba có lỗi sau khi đã bồi thường","Tăng phí khi có tổn thất","Hủy hợp đồng ngay","Từ chối mọi khiếu nại"],en:["Recover from the liable third party after paying","Raise premiums after a loss","Cancel the policy at once","Reject every claim"]},answer:0,explain:{vi:"Thế quyền chuyển quyền đòi bồi hoàn của bên được bảo hiểm sang doanh nghiệp bảo hiểm trong phạm vi đã bồi thường.",en:"Subrogation transfers the insured's recovery rights to the insurer up to the amount paid."}},{q:{vi:"Khách đề nghị chia phần trăm nếu bạn ghi tăng tổn thất. Bạn làm gì?",en:"The insured offers you a percentage if you inflate the loss. What do you do?"},options:{vi:["Đồng ý vì là khách lớn","Ghi tăng một ít cho khách vui","Từ chối, ghi nhận đề nghị và báo bộ phận chống trục lợi","Để đại lý quyết định"],en:["Agree because it is a big client","Inflate it a little to keep them happy","Refuse, record the offer and report it to the fraud unit","Let the agent decide"]},answer:2,explain:{vi:"Khai khống tổn thất là trục lợi bảo hiểm; giám định viên phải từ chối và báo cáo bằng văn bản.",en:"Inflating a loss is insurance fraud; the adjuster must refuse and report it in writing."}}]}},"KK-177":{scenario:{company:"Steadyoak Wealth Advisory",supervisor:{name:"Đỗ Hải Yến",role:{vi:"Trưởng nhóm Hoạch định Tài chính",en:"Financial Planning Team Lead"}},ref_code:"FP-2190",title:{vi:"Đúng khẩu vị rủi ro. Đúng tiền nhàn rỗi.",en:"Right risk profile. Right investable cash."},brief:{vi:"Khách hàng 58 tuổi, dự kiến nghỉ hưu sau 2 năm, có 865 triệu đồng tiền gửi và tiền mặt. Chi tiêu thiết yếu 23,5 triệu đồng/tháng; cần 186 triệu đồng học phí cho con sau 8 tháng. Điểm bảng hỏi khẩu vị rủi ro 34/100. Khách nói muốn lãi cao nên bản kế hoạch nháp FP-2190 chọn danh mục GROWTH và đầu tư toàn bộ 865 triệu đồng. Hãy sửa danh mục mẫu và số tiền đầu tư dài hạn, rồi lập báo cáo tư vấn có căn cứ.",en:"A 58-year-old client plans to retire in 2 years and holds 865 million VND in deposits and cash. Essential spending is 23.5 million VND per month; 186 million VND of tuition is due in 8 months. The risk profile questionnaire score is 34/100. The client says they want high returns, so draft plan FP-2190 picks the GROWTH portfolio and invests all 865 million VND. Correct the model portfolio and the long-term investable amount, then write an evidence-based advice report."},reference_title:{vi:"Khung khẩu vị rủi ro & bảng cân đối tài chính đã duyệt · FP-2190",en:"Approved risk framework & personal balance sheet · FP-2190"},fields:[{id:"RISK_MODEL",label:{vi:"Danh mục mẫu",en:"Model portfolio"},initial:"GROWTH",expected:"CONSERVATIVE",choices:["CONSERVATIVE","BALANCED","GROWTH"],reference:"Khung phân loại khẩu vị rủi ro",ref_value:{vi:"Điểm 0-39: CONSERVATIVE; 40-69: BALANCED; 70-100: GROWTH (mô phỏng)",en:"Score 0-39: CONSERVATIVE; 40-69: BALANCED; 70-100: GROWTH (training data)"},hint:{vi:"Danh mục đi theo điểm khẩu vị và khả năng chịu rủi ro, không theo mong muốn lợi nhuận của khách.",en:"The portfolio follows the risk score and risk capacity, not the client's return wish."}},{id:"INVESTABLE",label:{vi:"Số tiền đầu tư dài hạn (triệu đồng)",en:"Long-term investable amount (million VND)"},initial:"865",expected:"538",reference:"Bảng cân đối tài chính cá nhân",ref_value:{vi:"Tài sản thanh khoản 865; chi tiêu thiết yếu 23,5/tháng; học phí 186 sau 8 tháng (triệu đồng)",en:"Liquid assets 865; essential spending 23.5/month; tuition 186 in 8 months (million VND)"},hint:{vi:"Giữ riêng quỹ dự phòng và tiền cho mục tiêu ngắn hạn ở kênh an toàn trước khi đầu tư.",en:"Set aside the emergency fund and short-term goal money in safe vehicles before investing."}}],sop32:{vi:"Số tiền đầu tư dài hạn = tài sản thanh khoản - quỹ dự phòng khẩn cấp (6 tháng chi tiêu thiết yếu) - tiền cho các mục tiêu đến hạn trong 12 tháng.",en:"Long-term investable amount = liquid assets - emergency fund (6 months of essential spending) - money for goals due within 12 months."},context:{label:"PLANNING TOOL / FP-2190",metrics:[{label:{vi:"Tài sản thanh khoản",en:"Liquid assets"},value:"865,000,000 VND"},{label:{vi:"Điểm khẩu vị rủi ro",en:"Risk profile score"},value:"34/100"},{label:{vi:"Tuổi nghỉ hưu dự kiến",en:"Planned retirement age"},value:"60"}]},crisis:{vi:"Trưởng nhóm kinh doanh nhắn: “Quý này thiếu chỉ tiêu, cứ đưa khách vào gói trái phiếu doanh nghiệp chưa niêm yết của đối tác, hoa hồng 4%. Đừng nhắc nhiều về rủi ro kẻo khách sợ, cứ nói là gần như gửi tiết kiệm.”",en:"The sales team lead messages you: “We are short of target this quarter. Put the client into the partner's unlisted corporate bond package, 4% commission. Do not talk much about risk or they will get scared, just say it is almost like a savings deposit.”"},options:{safe:{vi:"Từ chối khuyến nghị sản phẩm không phù hợp, tư vấn theo danh mục CONSERVATIVE, công bố minh bạch hoa hồng và rủi ro, báo bộ phận Tuân thủ về áp lực bán hàng.",en:"Decline to recommend the unsuitable product, advise under the CONSERVATIVE model, disclose commissions and risks clearly, and report the sales pressure to Compliance."},shortcut:{vi:"Giới thiệu gói trái phiếu là gần như tiền gửi để đạt chỉ tiêu quý.",en:"Present the bond package as almost a deposit to hit the quarterly target."},wait:{vi:"Hoãn buổi tư vấn và để khách tự tìm hiểu sản phẩm.",en:"Postpone the meeting and let the client research products alone."}},questions:{vi:["Vì sao khách phù hợp danh mục CONSERVATIVE và chỉ nên đầu tư dài hạn 538 triệu đồng? Hãy giải thích bằng dữ liệu.","Bạn công bố xung đột lợi ích và xử lý áp lực bán sản phẩm hoa hồng cao thế nào để bảo vệ khách hàng?"],en:["Why does the client fit the CONSERVATIVE model and why should only 538 million VND be invested long term? Explain with data.","How do you disclose conflicts of interest and handle pressure to sell high-commission products while protecting the client?"]},hints:{vi:["Đặt điểm khẩu vị rủi ro cạnh khung phân loại và xét thời gian còn lại đến khi nghỉ hưu.","Tách quỹ dự phòng và mục tiêu ngắn hạn khỏi tài sản thanh khoản theo SOP mục 3.2.","Đọc SOP mục 4.2: khuyến nghị phải phù hợp khách hàng, công bố hoa hồng và báo cáo áp lực bán hàng."],en:["Place the risk score against the framework and consider the time left before retirement.","Remove the emergency fund and short-term goals from liquid assets per SOP 3.2.","Re-read SOP 4.2: advice must be suitable, commissions disclosed and sales pressure reported."]}},learning:{summary:{vi:"Chuyên viên hoạch định tài chính cá nhân giúp khách hàng xây dựng kế hoạch tài chính trọn đời: phân tích thu chi, quỹ dự phòng, bảo hiểm, đầu tư, hưu trí, giáo dục con cái, thuế và chuyển giao tài sản. Nghề tạo ra sự an tâm tài chính cho khách khi lời khuyên dựa trên mục tiêu và khả năng chịu rủi ro thật, minh bạch chi phí và đặt lợi ích khách hàng lên trên hoa hồng.",en:"A personal financial planner helps clients build a lifelong financial plan: cash flow, emergency funds, insurance, investing, retirement, education, tax and estate planning. The role creates financial peace of mind when advice rests on real goals and risk capacity, costs are transparent and the client's interest comes before commission."},responsibilities:{vi:["Thu thập thông tin tài chính, mục tiêu và hoàn cảnh gia đình của khách hàng.","Đánh giá khẩu vị và khả năng chịu rủi ro bằng bảng hỏi và phỏng vấn.","Lập bảng cân đối, dòng tiền cá nhân và xác định quỹ dự phòng cần thiết.","Đề xuất phân bổ tài sản, bảo hiểm và kế hoạch hưu trí phù hợp.","Theo dõi, tái cân bằng danh mục và cập nhật kế hoạch định kỳ."],en:["Gather the client's financial data, goals and family situation.","Assess risk tolerance and capacity through questionnaires and interviews.","Build the personal balance sheet and cash flow and size the emergency fund.","Recommend asset allocation, insurance and a retirement plan that fit.","Monitor, rebalance the portfolio and update the plan regularly."]},competencies:[{name:{vi:"Phân tích tài chính cá nhân",en:"Personal financial analysis"},desc:{vi:"Đọc thu chi, tài sản, nợ của khách để tìm khoảng trống và rủi ro tài chính.",en:"Read income, spending, assets and debts to find gaps and financial risks."}},{name:{vi:"Đánh giá phù hợp",en:"Suitability assessment"},desc:{vi:"Kết hợp khẩu vị, khả năng chịu rủi ro, thời gian đầu tư để chọn danh mục.",en:"Combine risk tolerance, capacity and time horizon to choose a portfolio."}},{name:{vi:"Phân bổ tài sản",en:"Asset allocation"},desc:{vi:"Xây dựng danh mục đa dạng giữa tiền gửi, trái phiếu, cổ phiếu, quỹ theo mục tiêu.",en:"Build diversified portfolios across deposits, bonds, equities and funds by goal."}},{name:{vi:"Tư vấn & lắng nghe",en:"Advisory & listening"},desc:{vi:"Đặt câu hỏi mở, giải thích rủi ro dễ hiểu và giúp khách ra quyết định có hiểu biết.",en:"Ask open questions, explain risk simply and help clients make informed decisions."}},{name:{vi:"Đạo đức nghề nghiệp",en:"Professional ethics"},desc:{vi:"Công bố xung đột lợi ích, phí, hoa hồng và từ chối bán sản phẩm không phù hợp.",en:"Disclose conflicts, fees and commissions and refuse to sell unsuitable products."}}],knowledge:{vi:["Quy trình hoạch định tài chính: tìm hiểu khách hàng, xác định mục tiêu, phân tích, khuyến nghị, triển khai và theo dõi.","Nguyên tắc phù hợp và nghĩa vụ hành động vì lợi ích tốt nhất của khách hàng.","Giá trị thời gian của tiền, lãi kép, đa dạng hóa và quan hệ rủi ro - lợi nhuận.","Sản phẩm tài chính phổ biến: tiền gửi, trái phiếu, cổ phiếu, chứng chỉ quỹ, bảo hiểm nhân thọ và bảo hiểm liên kết đầu tư.","Luật Chứng khoán số 54/2019/QH14 và quy định về nhà đầu tư chuyên nghiệp đối với trái phiếu doanh nghiệp phát hành riêng lẻ."],en:["The financial planning process: understanding the client, setting goals, analysis, recommendations, implementation and monitoring.","The suitability principle and the duty to act in the client's best interest.","Time value of money, compounding, diversification and the risk-return trade-off.","Common products: deposits, bonds, equities, fund certificates, life and unit-linked insurance.","Securities Law No. 54/2019/QH14 and professional investor rules for privately placed corporate bonds."]},tools:["Financial planning software","Risk profile questionnaire","Cash flow & net worth worksheet","Retirement calculator","Portfolio analytics","CRM with suitability log"],tools_en:["Financial planning software","Risk profile questionnaire","Cash flow & net worth worksheet","Retirement calculator","Portfolio analytics","CRM with suitability log"],kpis:{vi:["Tỷ lệ khách hàng có kế hoạch tài chính được cập nhật đúng hạn.","Tỷ lệ khuyến nghị đạt kiểm tra phù hợp của bộ phận Tuân thủ.","Tỷ lệ giữ chân khách hàng sau 12 tháng.","Số khiếu nại về tư vấn sai lệch (mục tiêu bằng 0)."],en:["Share of clients with plans updated on schedule.","Share of recommendations passing Compliance suitability checks.","Client retention after 12 months.","Mis-selling complaints (target zero)."]},day:[{time:"08:30",vi:"Xem biến động thị trường và danh sách khách cần tái cân bằng danh mục.",en:"Review market moves and clients due for rebalancing."},{time:"10:00",vi:"Gặp khách hàng mới, thu thập dữ liệu và làm bảng hỏi khẩu vị rủi ro.",en:"Meet a new client, gather data and run the risk questionnaire."},{time:"13:30",vi:"Lập bảng cân đối, dòng tiền và mô phỏng kế hoạch hưu trí.",en:"Build the balance sheet and cash flow and model the retirement plan."},{time:"15:30",vi:"Trình bày khuyến nghị, công bố phí, hoa hồng và lưu biên bản tư vấn.",en:"Present recommendations, disclose fees and commissions and file the advice record."},{time:"17:00",vi:"Cập nhật CRM và hồ sơ đánh giá phù hợp cho bộ phận Tuân thủ.",en:"Update the CRM and suitability records for Compliance."}],mistakes:{vi:["Chọn danh mục theo mong muốn lợi nhuận của khách thay vì điểm khẩu vị và khả năng chịu rủi ro.","Đầu tư cả quỹ dự phòng và tiền cho mục tiêu ngắn hạn vào tài sản biến động.","Giới thiệu trái phiếu, bảo hiểm liên kết đầu tư như tiền gửi để hưởng hoa hồng."],en:["Choosing a portfolio from the client's return wish instead of risk score and capacity.","Investing the emergency fund and short-term goal money in volatile assets.","Presenting bonds or unit-linked insurance as deposits to earn commission."]},career:[{vi:"Chuyên viên hỗ trợ tư vấn tài chính",en:"Financial planning assistant"},{vi:"Chuyên viên hoạch định tài chính cá nhân",en:"Personal financial planner"},{vi:"Chuyên gia tư vấn quản lý tài sản cao cấp",en:"Senior wealth adviser"},{vi:"Giám đốc Quản lý Tài sản Khách hàng",en:"Head of wealth management"}],glossary:[{term:"Risk profile",vi:"Hồ sơ khẩu vị rủi ro: mức độ sẵn sàng và khả năng chịu biến động giá trị đầu tư của khách.",en:"A client's willingness and capacity to bear swings in investment value."},{term:"Emergency fund",vi:"Quỹ dự phòng khẩn cấp, thường bằng 3-6 tháng chi tiêu thiết yếu, giữ ở kênh thanh khoản cao.",en:"A reserve, usually 3-6 months of essential spending, kept in highly liquid form."},{term:"Asset allocation",vi:"Phân bổ tài sản giữa các lớp như tiền gửi, trái phiếu, cổ phiếu theo mục tiêu và rủi ro.",en:"Splitting money across classes such as deposits, bonds and equities by goal and risk."},{term:"Suitability",vi:"Nguyên tắc phù hợp: sản phẩm khuyến nghị phải khớp mục tiêu, kiến thức và khả năng chịu rủi ro.",en:"Recommended products must match the client's goals, knowledge and risk capacity."},{term:"Rebalancing",vi:"Tái cân bằng danh mục về tỷ trọng mục tiêu khi thị trường làm lệch phân bổ.",en:"Bringing a portfolio back to target weights after markets shift the allocation."}],quiz:[{q:{vi:"Quỹ dự phòng khẩn cấp thường được khuyến nghị ở mức nào?",en:"What emergency fund level is usually recommended?"},options:{vi:["3-6 tháng chi tiêu thiết yếu","1 tuần chi tiêu","2 năm thu nhập","Toàn bộ tài sản"],en:["3-6 months of essential spending","One week of spending","Two years of income","All assets"]},answer:0,explain:{vi:"Quỹ dự phòng 3-6 tháng chi tiêu thiết yếu giúp khách không phải bán tài sản đầu tư khi có biến cố.",en:"A 3-6 month reserve avoids forced sales of investments when emergencies hit."}},{q:{vi:"Tài sản thanh khoản 500 triệu, chi tiêu thiết yếu 15 triệu/tháng, quỹ dự phòng 6 tháng, mục tiêu mua xe 120 triệu sau 6 tháng. Số tiền đầu tư dài hạn là bao nhiêu?",en:"Liquid assets 500 million, essential spending 15 million/month, 6-month emergency fund, a 120 million car goal in 6 months. What is the long-term investable amount?"},options:{vi:["410 triệu","380 triệu","290 triệu","500 triệu"],en:["410 million","380 million","290 million","500 million"]},answer:2,explain:{vi:"Đầu tư dài hạn = 500 - 15 x 6 - 120 = 290 triệu đồng.",en:"Investable = 500 - 15 x 6 - 120 = 290 million."}},{q:{vi:"Cấp trên yêu cầu bán sản phẩm hoa hồng cao không phù hợp khẩu vị của khách. Bạn làm gì?",en:"Your manager asks you to sell a high-commission product that does not fit the client's profile. What do you do?"},options:{vi:["Bán và không nhắc đến hoa hồng","Bán nhưng giảm số tiền","Chờ khách tự hỏi","Từ chối khuyến nghị, tư vấn theo nguyên tắc phù hợp và báo Tuân thủ"],en:["Sell it without mentioning commission","Sell a smaller amount","Wait for the client to ask","Decline, advise on suitability grounds and report to Compliance"]},answer:3,explain:{vi:"Lợi ích khách hàng đặt trên hoa hồng; áp lực bán sản phẩm không phù hợp phải được báo cáo.",en:"The client's interest comes before commission; pressure to mis-sell must be reported."}},{q:{vi:"Giữa khách 30 tuổi và khách 58 tuổi, ai thường có khả năng chịu rủi ro dài hạn cao hơn và vì sao?",en:"Between a 30-year-old and a 58-year-old client, who usually has higher long-term risk capacity and why?"},options:{vi:["Khách 58 tuổi vì có nhiều tiền hơn","Khách 30 tuổi vì thời gian đầu tư dài và còn thu nhập lao động để bù biến động","Như nhau","Khách 58 tuổi vì sắp nghỉ hưu"],en:["The 58-year-old because they have more money","The 30-year-old because of a long horizon and future earnings to absorb swings","They are the same","The 58-year-old because retirement is near"]},answer:1,explain:{vi:"Thời gian đầu tư dài và thu nhập tương lai giúp người trẻ chịu được biến động; người sắp nghỉ hưu cần bảo toàn vốn.",en:"A long horizon and future income let younger clients ride out volatility; near-retirees need capital preservation."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(2)})(window.KKR);
